<#
.SYNOPSIS
    Nova Tweaks - performance suite (Fortnite/Minecraft profiles, Windows + macOS dev/Minecraft variants)
.DESCRIPTION
    Nova Tweaks performance suite with real, reversible tweaks and Free/Pro/Ultimate tiers.
#>

# Admin is required for many Windows system tweaks; enforce on Windows only (macOS localhost/dev runs unprivileged).
if (($IsWindows -or $env:OS -eq 'Windows_NT') -and -not ($env:NOVA_SKIP_ADMIN -eq '1')) {
    try {
        $id = [Security.Principal.WindowsIdentity]::GetCurrent()
        $p = New-Object Security.Principal.WindowsPrincipal($id)
        if (-not $p.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
            $args = @('-NoProfile','-ExecutionPolicy','Bypass','-File',"`"$PSCommandPath`"")
            Start-Process -FilePath (Get-Process -Id $PID).Path -ArgumentList $args -Verb RunAs
            exit
        }
    } catch {}
}

$IsWin = $IsWindows -or ($env:OS -eq "Windows_NT")
$IsMac = $IsMacOS -or ($env:OS -ne "Windows_NT" -and (Test-Path "/System/Library/CoreServices/SystemVersion.plist"))
# Dev-only: preview the Windows UI/catalog on macOS. Does NOT execute Windows system changes.
$Script:WindowsPreview = (-not $IsWin) -and ($env:NOVA_WINDOWS_PREVIEW -eq '1')
function Get-NovaViewIsWin { return ($IsWin -or $Script:WindowsPreview) }
# Single-product app variants (separate apps; no in-app game switch). Defaults preserve the combined Windows app.
$Script:FixedGame = if ($env:NOVA_FIXED_GAME -in @('Fortnite','Minecraft')) { $env:NOVA_FIXED_GAME } else { $null }
$Script:AppVariant = if ($env:NOVA_APP_VARIANT) { [string]$env:NOVA_APP_VARIANT } else { $null }

$Script:Root = if ($IsWin) { Join-Path $env:USERPROFILE "NovaTweaks" } else { Join-Path $env:HOME ".novatweaks" }
$Script:BackupDir = Join-Path $Script:Root "backups"
$Script:LogPath = Join-Path $Script:Root "nova.log"
$Script:ConfigPath = Join-Path $Script:Root "config.json"
$Script:AccountsPath = Join-Path $Script:Root "accounts.json"
$Script:TokenPath = Join-Path $Script:Root "session.token"
foreach ($d in @($Script:Root,$Script:BackupDir)) { if (-not (Test-Path $d)) { New-Item -ItemType Directory -Path $d -Force | Out-Null } }
if (-not (Test-Path $Script:LogPath)) { New-Item -ItemType File -Path $Script:LogPath -Force | Out-Null }

# ---------- Account System ----------
function Load-Accounts { if (Test-Path $Script:AccountsPath) { try { return @(Get-Content $Script:AccountsPath -Raw | ConvertFrom-Json) } catch { return @() } }; return @() }
function Save-Accounts { param($accs) $accs | ConvertTo-Json -Depth 8 | Set-Content $Script:AccountsPath -Encoding UTF8 }
function Find-Account { param($email) (Load-Accounts) | Where-Object { $_.Email -eq $email } | Select-Object -First 1 }
function Hash-Pass { param($p) [System.Convert]::ToBase64String([System.Text.Encoding]::UTF8.GetBytes($p + "Nova Tweaks_SALT_2026")) }
function Normalize-NovaAccount { param($acc)
    if (-not $acc) { return $null }
    if (-not $acc.Plan) { $acc.Plan = "Free" }
    if ($acc.Plan -notin @("Free","Pro","Ultimate")) { $acc.Plan = "Free" }
    $names = @($acc.PSObject.Properties.Name)
    if ($names -notcontains "Balance") { $acc | Add-Member -NotePropertyName Balance -NotePropertyValue 0 -Force }
    if ($names -notcontains "PlanUntil") { $acc | Add-Member -NotePropertyName PlanUntil -NotePropertyValue $null -Force }
    if ($names -notcontains "Redeemed") { $acc | Add-Member -NotePropertyName Redeemed -NotePropertyValue @() -Force }
    if ($names -notcontains "Streak") { $acc | Add-Member -NotePropertyName Streak -NotePropertyValue 0 -Force }
    if ($names -notcontains "BestStreak") { $acc | Add-Member -NotePropertyName BestStreak -NotePropertyValue 0 -Force }
    if ($names -notcontains "LastActiveDay") { $acc | Add-Member -NotePropertyName LastActiveDay -NotePropertyValue "" -Force }
    if ($names -notcontains "Badges") { $acc | Add-Member -NotePropertyName Badges -NotePropertyValue @() -Force }
    if ($names -notcontains "AppliedEver") { $acc | Add-Member -NotePropertyName AppliedEver -NotePropertyValue @() -Force }
    if ($names -notcontains "CleanSweeps") { $acc | Add-Member -NotePropertyName CleanSweeps -NotePropertyValue 0 -Force }
    if (-not $acc.Badges) { $acc.Badges = @() }
    if (-not $acc.AppliedEver) { $acc.AppliedEver = @() }
    if ($null -eq $acc.Streak) { $acc.Streak = 0 }
    if ($null -eq $acc.BestStreak) { $acc.BestStreak = 0 }
    if ($null -eq $acc.CleanSweeps) { $acc.CleanSweeps = 0 }
    if ($acc.Plan -ne "Free" -and -not $acc.PlanUntil) {
        # Legacy builds unlocked Pro for everyone; only a dated plan counts as paid.
        $acc.Plan = "Free"
    }
    if ($acc.Plan -ne "Free" -and $acc.PlanUntil) {
        try { if ([datetime]$acc.PlanUntil -lt (Get-Date)) { $acc.Plan = "Free"; $acc.PlanUntil = $null } } catch { $acc.Plan = "Free"; $acc.PlanUntil = $null }
    }
    return $acc
}
function Create-Account { param($email,$password,$name)
    $accs = @(Load-Accounts)
    if ($accs | Where-Object { $_.Email -eq $email }) { return @{ success=$false; message="Account already exists." } }
    $acc = @{ Email=$email; PasswordHash=(Hash-Pass $password); Name=$name; Plan="Free"; LicenseKey=""; Balance=0; PlanUntil=$null; Redeemed=@(); Streak=0; BestStreak=0; LastActiveDay=""; Badges=@(); AppliedEver=@(); CleanSweeps=0; Created=(Get-Date).ToString("o"); LastLogin=(Get-Date).ToString("o") }
    $accs += $acc; Save-Accounts $accs
    return @{ success=$true; message="Account created."; account=$acc }
}
function Verify-Login { param($email,$password)
    $acc = Find-Account $email
    if (-not $acc) { return @{ success=$false; message="No account found." } }
    if ((Hash-Pass $password) -ne $acc.PasswordHash) { return @{ success=$false; message="Wrong password." } }
    $accs = @(Load-Accounts); $a = $accs | Where-Object { $_.Email -eq $email } | Select-Object -First 1
    if ($a) { $a.LastLogin = (Get-Date).ToString("o"); Save-Accounts $accs }
    $acc = Normalize-NovaAccount $acc
    $token = [System.Convert]::ToBase64String([System.Text.Encoding]::UTF8.GetBytes("$email|$(Get-Date -Format 'o')|Nova Tweaks"))
    Set-Content -Path $Script:TokenPath -Value $token -Encoding UTF8
    return @{ success=$true; message="Login successful."; token=$token; account=$acc }
}
function Auto-Login {
    if (-not (Test-Path $Script:TokenPath)) { return $null }
    $token = (Get-Content $Script:TokenPath -Raw).Trim()
    try {
        $decoded = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($token))
        $email = ($decoded -split "\|")[0]
        $acc = Find-Account $email
        if ($acc) { return (Normalize-NovaAccount $acc) }
    } catch {}
    return $null
}
function Logout { if (Test-Path $Script:TokenPath) { Remove-Item $Script:TokenPath -Force } }

$Script:Config = @{ Plan="Free"; PlanUntil=$null; Balance=0; TweakStates=@{}; Email=""; LicenseKey=""; CurrentUser=""; Game="Fortnite" }
if (Test-Path $Script:ConfigPath) {
    try {
        $l = Get-Content $Script:ConfigPath -Raw | ConvertFrom-Json
        foreach ($k in $l.PSObject.Properties.Name) {
            if ($k -eq "TweakStates") {
                $ht = @{}
                if ($l.TweakStates) { foreach ($p in $l.TweakStates.PSObject.Properties) { $ht[$p.Name] = [bool]$p.Value } }
                $Script:Config.TweakStates = $ht
            } else {
                $Script:Config[$k] = $l.$k
            }
        }
    } catch {}
}
if (-not $Script:Config.Plan -or $Script:Config.Plan -notin @("Free","Pro","Ultimate")) { $Script:Config.Plan = "Free" }
if (-not $Script:Config.PSObject.Properties.Name -contains "Balance") { $Script:Config | Add-Member -NotePropertyName Balance -NotePropertyValue 0 -Force }
if (-not $Script:Config.PSObject.Properties.Name -contains "PlanUntil") { $Script:Config | Add-Member -NotePropertyName PlanUntil -NotePropertyValue $null -Force }
if (-not $Script:Config.PSObject.Properties.Name -contains "Game" -or -not $Script:Config.Game -or $Script:Config.Game -notin @("Fortnite","Minecraft")) { $Script:Config.Game = "Fortnite" }
function Save-Config { $Script:Config | ConvertTo-Json -Depth 5 | Set-Content $Script:ConfigPath -Encoding UTF8 }

function Get-NovaGame {
    if ($Script:FixedGame) { return $Script:FixedGame }
    if ($Script:Config.Game -eq "Minecraft") { return "Minecraft" }
    return "Fortnite"
}

function Test-NovaTweakForGame {
    param($Tweak)
    if (-not $Tweak) { return $false }
    if (-not $Tweak.Game) { return $true }
    return ([string]$Tweak.Game -eq (Get-NovaGame))
}

# ---------- Tier helpers ----------
$Script:GiftSecret = "NovaTweaks-Gift-S3cr3t-2026-ChangeMe"
$Script:LicenseSecret = "NovaTweaks-License-S3cr3t-2026-ChangeMe"
function Get-NovaPlanRank { param([string]$p) switch ($p) { "Ultimate" { 2 } "Pro" { 1 } default { 0 } } }
function Get-NovaPlanPriceCents { param([string]$p) switch ($p) { "Pro" { 599 } "Ultimate" { 1299 } default { 0 } } }
function Get-NovaPlanUntil { param($acc) if ($acc.PlanUntil) { try { return [datetime]$acc.PlanUntil } catch {} }; return $null }
function Update-NovaPlanState {
    if ($Script:CurrentUser) {
        $acc = Normalize-NovaAccount $Script:CurrentUser
        $Script:CurrentUser = $acc
        $Script:Config.Plan = $acc.Plan
        $Script:Config.PlanUntil = $acc.PlanUntil
        $Script:Config.Balance = $acc.Balance
    }
}
function Invoke-NovaHmac { param([string]$Secret,[string]$Data)
    $h = [System.Security.Cryptography.HMACSHA256]::new([System.Text.Encoding]::UTF8.GetBytes($Secret))
    $b = $h.ComputeHash([System.Text.Encoding]::UTF8.GetBytes($Data))
    return ([System.BitConverter]::ToString($b) -replace "-").ToLower().Substring(0,10)
}
function New-NovaGiftCode { param([int]$Cents)
    $nonce = [System.Guid]::NewGuid().ToString("N").Substring(0,8).ToUpper()
    $sig = Invoke-NovaHmac -Secret $Script:GiftSecret -Data "$Cents`:$nonce"
    return "NOVA-GIFT-$Cents-$nonce-$sig"
}
function Test-NovaGiftCode { param([string]$Code)
    if ($Code -notmatch "^NOVA-GIFT-(\d+)-([A-F0-9]{8})-([a-f0-9]{10})$") { return $null }
    $cents = [int]$matches[1]
    $nonce = $matches[2]
    $sig = $matches[3]
    if ($cents -lt 100 -or $cents -gt 100000) { return $null }
    $expected = Invoke-NovaHmac -Secret $Script:GiftSecret -Data "$cents`:$nonce"
    if ($sig -ne $expected) { return $null }
    return $cents
}
function New-NovaLicenseKey { param([string]$Kind)
    $days = [int]((Get-Date).ToUniversalTime() - [datetime]"2024-01-01").TotalDays
    $nonce = [System.Guid]::NewGuid().ToString("N").Substring(0,8).ToUpper()
    $sig = Invoke-NovaHmac -Secret $Script:LicenseSecret -Data "$Kind`:$days`:$nonce"
    return "NOVA-$Kind-$days-$nonce-$sig"
}
function Test-NovaLicenseKey { param([string]$Key)
    if ($Key -notmatch "^NOVA-(PRO|ULT)-(\d+)-([A-F0-9]{8})-([a-f0-9]{10})$") { return $null }
    $kind = $matches[1]
    $days = [int]$matches[2]
    $nonce = $matches[3]
    $sig = $matches[4]
    $expected = Invoke-NovaHmac -Secret $Script:LicenseSecret -Data "$kind`:$days`:$nonce"
    if ($sig -ne $expected) { return $null }
    $now = [int]((Get-Date).ToUniversalTime() - [datetime]"2024-01-01").TotalDays
    if ($days -gt $now + 3650) { return $null }
    return $kind
}

# ---------- Plan / tier model ----------
# Free = 30 hand-picked tweaks. Pro = everything except the advanced service pack,
# firmware category and the Ultimate-only list. Ultimate = the full catalog.
$Script:FreeTweakIds = @(
    "memory","temp","startup","mouseprec","power","visual","menu","transp",
    "disableballoontips","disablemenuanim","disablecursorshadow","gamemode",
    "faststartup","hibernate","ntfslast","trim","disableprintspooler","disablefax",
    "winanimoff","displaysleepoff","nosleep","clearrecyclebin",
    "mcoptions","mcmipmap","mcfullscreen","mcgpu","mcfsopt","mcpriority","mccache","mcgamebar"
)
$Script:UltimateTweakIds = @(
    "potato","mpo","fullopt","bcdedit","hags","corepark","timer","usbss","powerthrottle",
    "defendercloud","smartscreen","disablewuauserv","wuautorestart","wins",
    "hypervisoroff","vbsdisable","memoryintegrityoff","mcjvm"
)

function Get-NovaEffectivePlan {
    if ($Script:CurrentUser) {
        $acc = Normalize-NovaAccount $Script:CurrentUser
        $Script:CurrentUser = $acc
        $Script:Config.Plan = $acc.Plan
        return [string]$acc.Plan
    }
    # No signed-in account means no paid entitlement.
    return "Free"
}

function Test-NovaProTweak {
    param($Tweak)
    if (-not $Tweak) { return $false }
    if ([string]$Tweak.Id -like "svc*") { return $false }
    if ([string]$Tweak.Cat -eq "Firmware") { return $false }
    if ([string]$Tweak.Id -in $Script:UltimateTweakIds) { return $false }
    return $true
}

function Test-NovaTweakAllowed {
    param($Tweak, [string]$Plan)
    if (-not $Plan) { $Plan = Get-NovaEffectivePlan }
    $rank = Get-NovaPlanRank $Plan
    if ($rank -ge 2) { return $true }
    if ($rank -eq 1) { return (Test-NovaProTweak $Tweak) }
    return ([string]$Tweak.Id -in $Script:FreeTweakIds)
}

function Get-NovaTweakRequiredPlan {
    param($Tweak)
    if ([string]$Tweak.Id -in $Script:FreeTweakIds) { return "Free" }
    if (Test-NovaProTweak $Tweak) { return "Pro" }
    return "Ultimate"
}

function Save-NovaCurrentAccount {
    if (-not $Script:CurrentUser) { return $null }
    $acc = Normalize-NovaAccount $Script:CurrentUser
    $Script:CurrentUser = $acc
    $accs = @(Load-Accounts)
    $idx = -1
    for ($i = 0; $i -lt $accs.Count; $i++) {
        if ([string]$accs[$i].Email -eq [string]$acc.Email) { $idx = $i; break }
    }
    if ($idx -ge 0) { $accs[$idx] = $acc } else { $accs += $acc }
    Save-Accounts $accs
    $Script:Config.CurrentUser = $acc.Email
    $Script:Config.Email = $acc.Email
    $Script:Config.Plan = $acc.Plan
    $Script:Config.PlanUntil = $acc.PlanUntil
    $Script:Config.Balance = $acc.Balance
    Save-Config
    return $acc
}

function Set-NovaAccountPlan {
    param([string]$Plan, [int]$Days = 30)
    $acc = Normalize-NovaAccount $Script:CurrentUser
    if (-not $acc) { return $null }
    $base = Get-Date
    $until = Get-NovaPlanUntil $acc
    if ($until -and $until -gt $base -and (Get-NovaPlanRank $Plan) -ge (Get-NovaPlanRank $acc.Plan)) {
        $base = $until
    }
    $acc.Plan = $Plan
    $acc.PlanUntil = $base.AddDays($Days).ToString("o")
    $Script:CurrentUser = $acc
    return (Save-NovaCurrentAccount)
}

function Add-NovaBalance {
    param([int]$Cents)
    $acc = Normalize-NovaAccount $Script:CurrentUser
    if (-not $acc) { return $null }
    $acc.Balance = [int]$acc.Balance + $Cents
    $Script:CurrentUser = $acc
    return (Save-NovaCurrentAccount)
}

# ---------- Badges and streaks ----------
function Get-NovaBadgeDefs {
    return @(
        @{ id="first-boot";   name="First Boot";      icon="🚀"; desc="Created your Nova Tweaks account." },
        @{ id="streak-3";     name="Warm Up";         icon="🔥"; desc="Signed in 3 days in a row." },
        @{ id="week-warrior"; name="Week Warrior";    icon="🗓"; desc="Signed in 7 days in a row." },
        @{ id="fortnight";    name="Fortnight";       icon="⚔"; desc="Signed in 14 days in a row." },
        @{ id="monthly-grind";name="Monthly Grind";   icon="🏆"; desc="Signed in 30 days in a row." },
        @{ id="tinkerer";     name="Tinkerer";        icon="🔧"; desc="Applied 5 different tweaks." },
        @{ id="optimizer";    name="Optimizer";       icon="⚙"; desc="Applied 25 different tweaks." },
        @{ id="maxed-out";    name="Maxed Out";       icon="💯"; desc="Applied 75 different tweaks." },
        @{ id="network-guru"; name="Network Guru";    icon="📡"; desc="Applied 6 or more Ping Optimizer / network tweaks." },
        @{ id="clean-sweep";  name="Clean Sweep";     icon="🧹"; desc="Used Revert All at least once." },
        @{ id="gift-hunter";  name="Gift Hunter";     icon="🎁"; desc="Redeemed a giveaway code." },
        @{ id="pro-player";   name="Pro Player";      icon="🥇"; desc="Activated a Pro or Ultimate plan." },
        @{ id="ultimate";     name="Ultimate";        icon="👑"; desc="Activated the Ultimate plan." }
    )
}

function Update-NovaBadges {
    if (-not $Script:CurrentUser) { return $false }
    $acc = Normalize-NovaAccount $Script:CurrentUser
    $existing = @($acc.Badges | Where-Object { $_ -and $_.id })
    $have = @{}
    foreach ($b in $existing) { $have[[string]$b.id] = $b }
    $want = New-Object System.Collections.Generic.List[string]
    [void]$want.Add("first-boot")
    if ([int]$acc.Streak -ge 3) { [void]$want.Add("streak-3") }
    if ([int]$acc.Streak -ge 7) { [void]$want.Add("week-warrior") }
    if ([int]$acc.Streak -ge 14) { [void]$want.Add("fortnight") }
    if ([int]$acc.Streak -ge 30) { [void]$want.Add("monthly-grind") }
    $appliedCount = @($acc.AppliedEver | Where-Object { $_ }).Count
    if ($appliedCount -ge 5) { [void]$want.Add("tinkerer") }
    if ($appliedCount -ge 25) { [void]$want.Add("optimizer") }
    if ($appliedCount -ge 75) { [void]$want.Add("maxed-out") }
    $networkIds = @("pingstab","nagle","autotune","qos","dnsgoogle","dnsquad9","flushdnscache","rscdisable","initialrto","wifipowersave","eeeoff","flowcontroloff")
    $networkApplied = @($networkIds | Where-Object { $_ -in @($acc.AppliedEver) }).Count
    if ($networkApplied -ge 6) { [void]$want.Add("network-guru") }
    if ([int]$acc.CleanSweeps -ge 1) { [void]$want.Add("clean-sweep") }
    if (@($acc.Redeemed | Where-Object { $_ }).Count -ge 1) { [void]$want.Add("gift-hunter") }
    if ((Get-NovaPlanRank $acc.Plan) -ge 1) { [void]$want.Add("pro-player") }
    if ($acc.Plan -eq "Ultimate") { [void]$want.Add("ultimate") }

    $changed = $false
    foreach ($id in $want) {
        if (-not $have.ContainsKey($id)) {
            $existing += @{ id=$id; earned=(Get-Date).ToString("o") }
            $have[$id] = $true
            $changed = $true
        }
    }
    if ($changed) {
        $acc.Badges = @($existing)
        $Script:CurrentUser = $acc
    }
    return $changed
}

function Get-NovaBadgeState {
    $acc = $null
    if ($Script:CurrentUser) { $acc = Normalize-NovaAccount $Script:CurrentUser }
    $earned = @{}
    if ($acc) {
        foreach ($b in @($acc.Badges)) {
            if ($b -and $b.id) { $earned[[string]$b.id] = [string]$b.earned }
        }
    }
    $out = New-Object System.Collections.ArrayList
    foreach ($d in (Get-NovaBadgeDefs)) {
        $has = $earned.ContainsKey([string]$d.id)
        [void]$out.Add(@{
            id = $d.id; name = $d.name; icon = $d.icon; desc = $d.desc
            earned = $has
            earnedOn = $(if ($has) { $earned[[string]$d.id] } else { $null })
        })
    }
    return @($out)
}

function Add-NovaAppliedTweaks {
    param([string[]]$Ids)
    if (-not $Script:CurrentUser -or -not $Ids) { return }
    $acc = Normalize-NovaAccount $Script:CurrentUser
    $applied = @($acc.AppliedEver | Where-Object { $_ })
    $added = $false
    foreach ($id in $Ids) {
        if ($id -and $id -notin $applied) {
            $applied += $id
            $added = $true
        }
    }
    if ($added) {
        $acc.AppliedEver = @($applied)
        $Script:CurrentUser = $acc
        Update-NovaBadges | Out-Null
        Save-NovaCurrentAccount | Out-Null
    }
}

function Add-NovaAppliedTweak {
    param([string]$Id)
    Add-NovaAppliedTweaks -Ids @($Id)
}

function Update-NovaStreak {
    if (-not $Script:CurrentUser) { return $null }
    $acc = Normalize-NovaAccount $Script:CurrentUser
    $today = (Get-Date).Date
    $todayKey = $today.ToString("yyyy-MM-dd")
    $last = $null
    if ($acc.LastActiveDay) {
        try { $last = [datetime]::ParseExact([string]$acc.LastActiveDay, "yyyy-MM-dd", $null) } catch {}
    }
    $changed = $false
    if (-not $last -or $last.Date -lt $today.AddDays(-1) -or $last.Date -gt $today) {
        $acc.Streak = 1
        $changed = $true
    } elseif ($last.Date -eq $today.AddDays(-1)) {
        $acc.Streak = [int]$acc.Streak + 1
        $changed = $true
    }
    if ([string]$acc.LastActiveDay -ne $todayKey) { $acc.LastActiveDay = $todayKey; $changed = $true }
    if ([int]$acc.Streak -gt [int]$acc.BestStreak) { $acc.BestStreak = [int]$acc.Streak; $changed = $true }
    $Script:CurrentUser = $acc
    $badgeChanged = Update-NovaBadges
    if ($changed -or $badgeChanged) { Save-NovaCurrentAccount | Out-Null }
    return $Script:CurrentUser
}

$Script:Logs = [System.Collections.ArrayList]::new()
$Script:NetHistory = [System.Collections.ArrayList]::new()
function Write-Log { param([string]$Msg,[string]$Level="INFO"); $line="$(Get-Date -Format 'HH:mm:ss') [$Level] $Msg"; [void]$Script:Logs.Add($line); Add-Content -Path $Script:LogPath -Value "$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss') [$Level] $Msg" -ErrorAction SilentlyContinue }

# ---------- TWEAK FUNCTIONS ----------

# Input Response Accelerator
function Invoke-InputDelayReducer {
    if (-not $IsWin) { Write-Log "Windows only." "WARN"; return }
    try {
        # Mouse: disable acceleration, set thresholds to 0
        Set-ItemProperty -Path "HKCU:\Control Panel\Mouse" -Name "MouseSpeed" -Value "0" -Type String -Force
        Set-ItemProperty -Path "HKCU:\Control Panel\Mouse" -Name "MouseThreshold1" -Value "0" -Type String -Force
        Set-ItemProperty -Path "HKCU:\Control Panel\Mouse" -Name "MouseThreshold2" -Value "0" -Type String -Force
        # Mouse data queue = 32
        $mousePath = "HKLM:\SYSTEM\CurrentControlSet\Services\mouclass\Parameters"
        if (-not (Test-Path $mousePath)) { New-Item -Path $mousePath -Force | Out-Null }
        Set-ItemProperty -Path $mousePath -Name "MouseDataQueueSize" -Value 32 -Type DWord -Force
        # Keyboard: max repeat rate, min delay
        Set-ItemProperty -Path "HKCU:\Control Panel\Keyboard" -Name "KeyboardSpeed" -Value "31" -Type String -Force
        Set-ItemProperty -Path "HKCU:\Control Panel\Keyboard" -Name "KeyboardDelay" -Value "0" -Type String -Force
        # Keyboard data queue = 32
        $kbPath = "HKLM:\SYSTEM\CurrentControlSet\Services\kbdclass\Parameters"
        if (-not (Test-Path $kbPath)) { New-Item -Path $kbPath -Force | Out-Null }
        Set-ItemProperty -Path $kbPath -Name "KeyboardDataQueueSize" -Value 32 -Type DWord -Force
        # Disable Filter Keys, Sticky Keys, Toggle Keys
        Set-ItemProperty -Path "HKCU:\Control Panel\Accessibility\Keyboard Response" -Name "Flags" -Value "0" -Type String -Force
        Set-ItemProperty -Path "HKCU:\Control Panel\Accessibility\StickyKeys" -Name "Flags" -Value "0" -Type String -Force
        Set-ItemProperty -Path "HKCU:\Control Panel\Accessibility\ToggleKeys" -Name "Flags" -Value "0" -Type String -Force
        # Win32PrioritySeparation = 38 (0x26) - best for gaming
        $priPath = "HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl"
        if (-not (Test-Path $priPath)) { New-Item -Path $priPath -Force | Out-Null }
        Set-ItemProperty -Path $priPath -Name "Win32PrioritySeparation" -Value 38 -Type DWord -Force
        # Disable Enhance Pointer Precision
        Set-ItemProperty -Path "HKCU:\Control Panel\Mouse" -Name "MouseSensitivity" -Value "10" -Type String -Force
        Write-Log "Input Response Accelerator applied (10 changes)." "OK"
    } catch { Write-Log "Input Response Accelerator failed: $($_.Exception.Message)" "ERR" }
}

# Network Spike Smoother
function Invoke-PingStabilizer {
    if ($IsWin) {
        try {
            # Nagle's algorithm
            $iface = "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces"
            Get-ChildItem $iface -ErrorAction SilentlyContinue | ForEach-Object {
                Set-ItemProperty -Path $_.PSPath -Name "TcpAckFrequency" -Value 1 -Type DWord -Force
                Set-ItemProperty -Path $_.PSPath -Name "TCPNoDelay" -Value 1 -Type DWord -Force
            }
            # Network throttling
            $mmcss = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile"
            Set-ItemProperty -Path $mmcss -Name "NetworkThrottlingIndex" -Value 0xFFFFFFFF -Type DWord -Force
            # TCP auto-tuning
            netsh interface tcp set global autotuninglevel=disabled 2>$null | Out-Null
            netsh interface tcp set global ecncapability=disabled 2>$null | Out-Null
            netsh interface tcp set global timestamps=disabled 2>$null | Out-Null
            # Adapter offloads
            Get-NetAdapter -ErrorAction SilentlyContinue | ForEach-Object {
                $name = $_.Name
                try { Set-NetAdapterAdvancedProperty -Name $name -DisplayName "Energy Efficient Ethernet" -DisplayValue "Disabled" -ErrorAction SilentlyContinue } catch {}
                try { Set-NetAdapterAdvancedProperty -Name $name -DisplayName "ARP Offload" -DisplayValue "Disabled" -ErrorAction SilentlyContinue } catch {}
                try { Set-NetAdapterAdvancedProperty -Name $name -DisplayName "NS Offload" -DisplayValue "Disabled" -ErrorAction SilentlyContinue } catch {}
                try { Set-NetAdapterAdvancedProperty -Name $name -DisplayName "Large Send Offload V2 (IPv4)" -DisplayValue "Disabled" -ErrorAction SilentlyContinue } catch {}
            }
            # Flush DNS
            ipconfig /flushdns 2>$null | Out-Null
            Write-Log "Network Spike Smoother applied (Nagle, throttling, offloads, DNS flush)." "OK"
        } catch { Write-Log "Network Spike Smoother failed: $($_.Exception.Message)" "ERR" }
    } else {
        try { dscacheutil -flushcache 2>$null; killall -HUP mDNSResponder 2>$null; Write-Log "DNS cache flushed." "OK" } catch { Write-Log "DNS flush failed." "WARN" }
    }
}

# Mouse Precision
function Invoke-MousePrecision {
