# Game Booster
function Invoke-GameBooster {
    if (-not $IsWin) { Write-Log "Windows only." "WARN"; return }
    $keep = @("System","Registry","smss","csrss","winlogon","services","lsass","explorer","dwm","svchost","conhost","powershell","pwsh","cmd","taskmgr","FortniteClient-Win64-Shipping")
    Get-Process | Where-Object { $_.ProcessName -notin $keep -and $_.MainWindowHandle -ne 0 } | ForEach-Object { try { $_.CloseMainWindow() | Out-Null; Write-Log "Closed: $($_.ProcessName)" "OK" } catch {} }
    Invoke-MemoryCleanup
    Write-Log "Game Booster complete." "OK"
}

# Locate the Fortnite client so the FPS Booster can give it a high GPU preference.
function Get-NovaFortniteExe {
    if (-not $IsWin) { return $null }
    $candidates = New-Object System.Collections.Generic.List[string]
    if ($env:ProgramFiles) { [void]$candidates.Add((Join-Path $env:ProgramFiles "Epic Games\Fortnite\FortniteGame\Binaries\Win64\FortniteClient-Win64-Shipping.exe")) }
    if (${env:ProgramFiles(x86)}) { [void]$candidates.Add((Join-Path ${env:ProgramFiles(x86)} "Epic Games\Fortnite\FortniteGame\Binaries\Win64\FortniteClient-Win64-Shipping.exe")) }
    foreach ($c in $candidates) { if ($c -and (Test-Path $c)) { return $c } }    try {
        $manifests = Join-Path $env:ProgramData "Epic\EpicGamesLauncher\Data\Manifests"
        if (Test-Path $manifests) {
            foreach ($f in Get-ChildItem $manifests -Filter *.item -ErrorAction SilentlyContinue) {
                try {
                    $j = Get-Content $f.FullName -Raw | ConvertFrom-Json
                    if ([string]$j.DisplayName -match "Fortnite") {
                        $p = Join-Path ([string]$j.InstallLocation) "FortniteGame\Binaries\Win64\FortniteClient-Win64-Shipping.exe"
                        if (Test-Path $p) { return $p }
                    }
                } catch {}
            }
        }
    } catch {}
    return $null
}

function Invoke-FortniteGpuPreference {
    param([switch]$Off)
    if (-not $IsWin) { Write-Log "Windows only." "WARN"; return }
    $p = "HKCU:\Software\Microsoft\DirectX\UserGpuPreferences"
    $exe = Get-NovaFortniteExe
    $candidates = New-Object System.Collections.Generic.List[string]
    if ($exe) { [void]$candidates.Add($exe) }
    if ($env:ProgramFiles) { [void]$candidates.Add((Join-Path $env:ProgramFiles "Epic Games\Fortnite\FortniteGame\Binaries\Win64\FortniteClient-Win64-Shipping.exe")) }
    if (${env:ProgramFiles(x86)}) { [void]$candidates.Add((Join-Path ${env:ProgramFiles(x86)} "Epic Games\Fortnite\FortniteGame\Binaries\Win64\FortniteClient-Win64-Shipping.exe")) }
    try {
        if (-not (Test-Path $p)) { New-Item -Path $p -Force | Out-Null }
        foreach ($c in ($candidates | Select-Object -Unique)) {
            if (-not $c) { continue }
            if ($Off) {
                try { Remove-ItemProperty -Path $p -Name $c -ErrorAction SilentlyContinue } catch {}
            } else {
                Set-ItemProperty -Path $p -Name $c -Value "GpuPreference=2;" -Type String -Force
            }
        }
        if ($Off) { Write-Log "Fortnite GPU preference reset." "OK" }
        else { Write-Log "Fortnite set to high-performance GPU." "OK" }
    } catch { Write-Log "Fortnite GPU preference failed: $($_.Exception.Message)" "WARN" }
}

function Invoke-FortnitePriority {
    param([string]$Priority = "High")
    if (-not $IsWin) { Write-Log "Windows only." "WARN"; return }
    $procs = @(Get-Process -Name "FortniteClient-Win64-Shipping" -ErrorAction SilentlyContinue)
    if ($procs.Count -eq 0) { Write-Log "Fortnite is not running. Start Fortnite, then apply." "WARN"; return }
    $cls = if ($Priority -eq "Normal") { [System.Diagnostics.ProcessPriorityClass]::Normal } else { [System.Diagnostics.ProcessPriorityClass]::High }
    foreach ($pr in $procs) {
        try { $pr.PriorityClass = $cls; Write-Log "Fortnite process priority set to $Priority." "OK" } catch { Write-Log "Could not set Fortnite priority: $($_.Exception.Message)" "WARN" }
    }
}

# FPS Booster: real Windows graphics/scheduling changes, plus a smaller macOS pass.
function Invoke-FpsBooster {
    $applied = New-Object System.Collections.Generic.List[string]
    if ($IsWin) {
        try {
            $p = "HKCU:\Software\Microsoft\GameBar"
            if (-not (Test-Path $p)) { New-Item -Path $p -Force | Out-Null }
            Set-ItemProperty -Path $p -Name "AutoGameModeEnabled" -Value 1 -Type DWord -Force
            Set-ItemProperty -Path $p -Name "AllowAutoGameMode" -Value 1 -Type DWord -Force
            [void]$applied.Add("Windows Game Mode on")
        } catch {}
        try {
            $p = "HKCU:\System\GameConfigStore"
            if (-not (Test-Path $p)) { New-Item -Path $p -Force | Out-Null }
            Set-ItemProperty -Path $p -Name "GameDVR_Enabled" -Value 0 -Type DWord -Force
            $p2 = "HKCU:\Software\Microsoft\Windows\CurrentVersion\GameDVR"
            if (-not (Test-Path $p2)) { New-Item -Path $p2 -Force | Out-Null }
            Set-ItemProperty -Path $p2 -Name "AppCaptureEnabled" -Value 0 -Type DWord -Force
            Set-ItemProperty -Path $p2 -Name "HistoricalCaptureEnabled" -Value 0 -Type DWord -Force
            [void]$applied.Add("Game DVR / background capture off")
        } catch {}
        try {
            $p = "HKCU:\System\GameConfigStore"
            if (-not (Test-Path $p)) { New-Item -Path $p -Force | Out-Null }
            Set-ItemProperty -Path $p -Name "GameDVR_FSEBehaviorMode" -Value 2 -Type DWord -Force
            Set-ItemProperty -Path $p -Name "GameDVR_HonorUserFSEBehaviorMode" -Value 1 -Type DWord -Force
            [void]$applied.Add("Fullscreen optimizations off")
        } catch {}
        try {
            $p = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games"
            if (-not (Test-Path $p)) { New-Item -Path $p -Force | Out-Null }
            Set-ItemProperty -Path $p -Name "GPU Priority" -Value 8 -Type DWord -Force
            Set-ItemProperty -Path $p -Name "Priority" -Value 6 -Type DWord -Force
            Set-ItemProperty -Path $p -Name "Scheduling Category" -Value "High" -Type String -Force
            Set-ItemProperty -Path $p -Name "SFIO Priority" -Value "High" -Type String -Force
            [void]$applied.Add("Game CPU/GPU scheduling priority raised")
        } catch {}
        $exe = Get-NovaFortniteExe
        if ($exe) {
            try {
                $p = "HKCU:\Software\Microsoft\DirectX\UserGpuPreferences"
                if (-not (Test-Path $p)) { New-Item -Path $p -Force | Out-Null }
                Set-ItemProperty -Path $p -Name $exe -Value "GpuPreference=2;" -Type String -Force
                [void]$applied.Add("Fortnite set to high-performance GPU")
            } catch {}
        }
        $procs = @(Get-Process -Name "FortniteClient-Win64-Shipping" -ErrorAction SilentlyContinue)
        if ($procs.Count -gt 0) {
            foreach ($pr in $procs) {
                try { $pr.PriorityClass = [System.Diagnostics.ProcessPriorityClass]::High; [void]$applied.Add("Fortnite process priority set to High") } catch {}
            }
        }
        try { Invoke-PowerPlan; [void]$applied.Add("Ultimate/High Performance power plan") } catch {}
        try { Invoke-MemoryCleanup; [void]$applied.Add("Memory trimmed and standby list purged") } catch {}
        Write-Log ("FPS Booster applied: " + ($applied -join ", ")) "OK"
    } else {
        try { defaults write NSGlobalDomain NSAppSleepDisabled -bool YES 2>$null; [void]$applied.Add("App Nap off") } catch {}
        try { defaults write com.apple.universalaccess reduceTransparency -bool true 2>$null; [void]$applied.Add("Transparency reduced") } catch {}
        try { defaults write com.apple.universalaccess reduceMotion -bool true 2>$null; [void]$applied.Add("Motion reduced") } catch {}
        try { defaults write NSGlobalDomain NSAutomaticWindowAnimationsEnabled -bool false 2>$null; [void]$applied.Add("Window animations off") } catch {}
        try { dscacheutil -flushcache 2>$null; killall -HUP mDNSResponder 2>$null; [void]$applied.Add("DNS cache flushed") } catch {}
        try { purge 2>$null; [void]$applied.Add("Memory purged") } catch {}
        try { killall Dock 2>$null } catch {}
        Write-Log ("macOS performance pass applied: " + ($applied -join ", ")) "OK"
    }
    return @($applied)
}

# Real CPU load, memory usage, free disk and platform for the home tiles.
function Get-NovaSysStats {
    $out = @{ cpu = $null; ram = $null; diskFree = $null; os = $(if ($IsWin) { "Windows" } else { "macOS" }) }
    try {
        if ($IsWin) {
            $load = Get-CimInstance Win32_Processor -ErrorAction SilentlyContinue | Measure-Object -Property LoadPercentage -Average
            if ($load -and $null -ne $load.Average) { $out.cpu = [math]::Round($load.Average) }
            $osInfo = Get-CimInstance Win32_OperatingSystem -ErrorAction SilentlyContinue
            if ($osInfo -and $osInfo.TotalVisibleMemorySize -gt 0) {
                $out.ram = [math]::Round((1 - ($osInfo.FreePhysicalMemory / $osInfo.TotalVisibleMemorySize)) * 100)
            }
            $drive = Get-PSDrive -Name ($env:SystemDrive.TrimEnd(':')) -ErrorAction SilentlyContinue
            if ($drive) { $out.diskFree = [math]::Round($drive.Free / 1GB, 1) }
        } else {
            $ncpu = 0; try { $ncpu = [int](sysctl -n hw.ncpu 2>$null) } catch {}
            if ($ncpu -lt 1) { $ncpu = 1 }
            $sum = 0.0
            $lines = & ps -A -o %cpu= 2>$null
            foreach ($line in $lines) { $v = 0.0; if ([double]::TryParse(([string]$line).Trim(), [ref]$v)) { $sum += $v } }
            $out.cpu = [math]::Round($sum / $ncpu)
            $total = 0.0; try { $total = [double](sysctl -n hw.memsize 2>$null) } catch {}
            $pageSize = 4096; $freePages = 0
            $vm = & vm_stat 2>$null
            foreach ($line in $vm) {
                if ($line -match "page size of (\d+) bytes") { $pageSize = [int]$matches[1] }
                if ($line -match "Pages free:\s+(\d+)") { $freePages += [int]$matches[1] }
                if ($line -match "Pages inactive:\s+(\d+)") { $freePages += [int]$matches[1] }
            }
            if ($total -gt 0) { $out.ram = [math]::Round((1 - (($freePages * $pageSize) / $total)) * 100) }
            $df = & df -k / 2>$null | Select-Object -Last 1
            if ($df) { $parts = ($df -split "\s+"); if ($parts.Count -ge 4) { $out.diskFree = [math]::Round([double]$parts[3] / 1048576, 1) } }
        }
    } catch {}
    if ($null -ne $out.cpu) { $out.cpu = [math]::Max(0, [math]::Min(100, $out.cpu)) }
    if ($null -ne $out.ram) { $out.ram = [math]::Max(0, [math]::Min(100, $out.ram)) }
    return $out
}

# Live network health: real ICMP ping samples, average, jitter and packet loss.
function Get-NovaNetworkStats {
    param([string]$Target = "1.1.1.1", [int]$Count = 4)
    if ($Target -notmatch "^[A-Za-z0-9\.\-]+$") { $Target = "1.1.1.1" }
    if ($Count -lt 2) { $Count = 2 }
    if ($Count -gt 8) { $Count = 8 }
    $samples = New-Object System.Collections.Generic.List[double]
    $sent = $Count
    $received = 0
    $out = ""
    try {
        if ($IsWin) { $out = (& ping -n $Count -w 1200 $Target 2>&1 | Out-String) }
        else { $out = (& ping -c $Count -W 1200 $Target 2>&1 | Out-String) }
    } catch { $out = "" }
    if (-not $out) {
        return @{ success = $false; message = "Could not run ping on this system."; target = $Target }
    }
    foreach ($m in [regex]::Matches($out, "(?:time|Time)[=<]\s*([0-9]+(?:\.[0-9]+)?)\s*ms")) {
        [void]$samples.Add([double]$m.Groups[1].Value)
    }
    if ($IsWin) {
        $sm = [regex]::Match($out, "Sent\s*=\s*(\d+),\s*Received\s*=\s*(\d+)")
        if ($sm.Success) { $sent = [int]$sm.Groups[1].Value; $received = [int]$sm.Groups[2].Value }
        else { $received = $samples.Count }
    } else {
        $sm = [regex]::Match($out, "(\d+)\s+packets transmitted,\s+(\d+)\s+(?:packets )?received")
        if ($sm.Success) { $sent = [int]$sm.Groups[1].Value; $received = [int]$sm.Groups[2].Value }
        else { $received = $samples.Count }
    }
    if ($sent -le 0) { $sent = $Count }
    if ($received -le 0) { $received = $samples.Count }
    $avg = $null; $min = $null; $max = $null; $jitter = 0
    if ($samples.Count -gt 0) {
        $avg = [math]::Round(($samples | Measure-Object -Average).Average, 1)
        $min = [math]::Round(($samples | Measure-Object -Minimum).Minimum, 1)
        $max = [math]::Round(($samples | Measure-Object -Maximum).Maximum, 1)
        if ($samples.Count -ge 2) {
            $sum = 0.0
            for ($i = 1; $i -lt $samples.Count; $i++) { $sum += [math]::Abs($samples[$i] - $samples[$i - 1]) }
            $jitter = [math]::Round($sum / ($samples.Count - 1), 1)
        }
    }
    $loss = if ($sent -gt 0) { [math]::Round((($sent - $received) / $sent) * 100, 1) } else { 0 }
    $row = @{ t = [DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds(); avg = $avg; jitter = $jitter; loss = $loss }
    [void]$Script:NetHistory.Add($row)
    while ($Script:NetHistory.Count -gt 60) { $Script:NetHistory.RemoveAt(0) }
    return @{
        success = $true
        target = $Target
        avg = $avg; min = $min; max = $max; jitter = $jitter; loss = $loss
        sent = $sent; received = $received
        samples = @($samples)
        history = @($Script:NetHistory)
        at = (Get-Date).ToString("o")
    }
}

# BCDEDIT (micro-stutter fix)
function Invoke-BCDEdit {
    if (-not $IsWin) { Write-Log "Windows only." "WARN"; return }
    try {
        bcdedit /set disabledynamictick yes 2>$null | Out-Null
        bcdedit /set useplatformclock true 2>$null | Out-Null
        bcdedit /set tscsyncpolicy Enhanced 2>$null | Out-Null
        Write-Log "BCDEDIT: dynamic tick disabled, platform clock enabled." "OK"
    } catch { Write-Log "BCDEDIT failed (may need admin)." "WARN" }
}

# Revert All
function Revert-All {
    if ($IsWin) {
        # Power plan + base network/BCD
        powercfg /setactive 381b4222-f694-41f0-9685-ff5bb260df2e 2>$null
        netsh interface tcp set global autotuninglevel=normal 2>$null | Out-Null
        bcdedit /set disabledynamictick no 2>$null | Out-Null
        bcdedit /set useplatformtick no 2>$null | Out-Null
        bcdedit /set useplatformclock false 2>$null | Out-Null
        bcdedit /set tscsyncpolicy Default 2>$null | Out-Null
        bcdedit /timeout 30 2>$null | Out-Null
        try { netsh int tcp set supplemental template=internet congestionprovider=CUBIC 2>$null | Out-Null } catch {}
        @("XblAuthManager","XblGameSave","XboxGipSvc","XboxNetApiSvc","DiagTrack","dmwappushservice","SysMain") | ForEach-Object { Set-Service -Name $_ -StartupType Manual -ErrorAction SilentlyContinue }

        # Network
        try {
            Get-NetAdapter -ErrorAction SilentlyContinue | ForEach-Object {
                try { Set-DnsClientServerAddress -InterfaceIndex $_.ifIndex -ResetServerAddresses -ErrorAction SilentlyContinue } catch {}
                try { Set-NetAdapterRss -Name $_.Name -Enabled $true -ErrorAction SilentlyContinue } catch {}
                try { Set-NetAdapterAdvancedProperty -Name $_.Name -DisplayName "Interrupt Moderation" -DisplayValue "Enabled" -ErrorAction SilentlyContinue } catch {}
            }
        } catch {}
        try { Get-ChildItem "HKLM:\SYSTEM\CurrentControlSet\Services\NetBT\Parameters\Interfaces" -ErrorAction SilentlyContinue | ForEach-Object { Set-ItemProperty -Path $_.PSPath -Name "NetbiosOptions" -Value 0 -Type DWord -Force } } catch {}
        try { Set-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows NT\DNSClient" -Name "EnableMulticast" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue } catch {}
        try { Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip6\Parameters" -Name "DisabledComponents" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue } catch {}
        try { Set-SmbServerConfiguration -EnableSMB1Protocol $true -Force -ErrorAction SilentlyContinue } catch {}
        try { Set-SmbClientConfiguration -EnableInsecureGuestLogons $true -Force -ErrorAction SilentlyContinue } catch {}
        ipconfig /flushdns 2>$null | Out-Null

        # Power
        powercfg /setacvalueindex SCHEME_CURRENT SUB_PROCESSOR PROCTHROTTLEMIN 5 2>$null | Out-Null
        powercfg /setdcvalueindex SCHEME_CURRENT SUB_PROCESSOR PROCTHROTTLEMIN 5 2>$null | Out-Null
        powercfg /setacvalueindex SCHEME_CURRENT SUB_PROCESSOR PERFBOOSTMODE 1 2>$null | Out-Null
        powercfg /setdcvalueindex SCHEME_CURRENT SUB_PROCESSOR PERFBOOSTMODE 1 2>$null | Out-Null
        powercfg /setacvalueindex SCHEME_CURRENT SUB_PROCESSOR SYSCOOLPOL 0 2>$null | Out-Null
        powercfg /setdcvalueindex SCHEME_CURRENT SUB_PROCESSOR SYSCOOLPOL 0 2>$null | Out-Null
        powercfg /setacvalueindex SCHEME_CURRENT SUB_PCIEXPRESS ASPM 1 2>$null | Out-Null
        powercfg /setdcvalueindex SCHEME_CURRENT SUB_PCIEXPRESS ASPM 1 2>$null | Out-Null
        powercfg /setacvalueindex SCHEME_CURRENT SUB_ENERGYSAVER ESBATTTHRESHOLD 20 2>$null | Out-Null
        powercfg /setactive SCHEME_CURRENT 2>$null | Out-Null
        powercfg /change standby-timeout-ac 30 2>$null | Out-Null
        powercfg /change hibernate-timeout-ac 180 2>$null | Out-Null
        powercfg /change disk-timeout-ac 20 2>$null | Out-Null
        powercfg /change disk-timeout-dc 20 2>$null | Out-Null

        # Visual
        try { Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\PushNotifications" -Name "ToastEnabled" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue } catch {}
        try { Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Notifications\Settings" -Name "NOC_GLOBAL_SETTING_TOASTS_ENABLED" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue } catch {}
        try { Set-ItemProperty -Path "HKCU:\Control Panel\Desktop" -Name "MinAnimate" -Value "1" -Type String -Force -ErrorAction SilentlyContinue } catch {}
        try { Set-ItemProperty -Path "HKCU:\Control Panel\Desktop\WindowMetrics" -Name "MinAnimate" -Value "1" -Type String -Force -ErrorAction SilentlyContinue } catch {}
        try { Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects" -Name "VisualFXSetting" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue } catch {}
        try {
            $adv = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced"
            Set-ItemProperty -Path $adv -Name "SnapAssist" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue
            Set-ItemProperty -Path $adv -Name "SnapFill" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue
            Set-ItemProperty -Path $adv -Name "JointResize" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue
        } catch {}

        # Services + vendor tasks
        Set-Service -Name "RemoteRegistry" -StartupType Manual -ErrorAction SilentlyContinue
        try { Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\Terminal Server" -Name "fDenyTSConnections" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue } catch {}
        $telTasks = @(
            "\Microsoft\Windows\Application Experience\ProgramDataUpdater",
            "\Microsoft\Windows\Application Experience\AitAgent",
            "\Microsoft\Windows\Application Experience\Microsoft Compatibility Appraiser",
            "\Microsoft\Windows\Customer Experience Improvement Program\Consolidator",
            "\Microsoft\Windows\Customer Experience Improvement Program\UsbCeip"
        )
        foreach ($t in $telTasks) {
            try {
                $i = $t.LastIndexOf('\')
                Enable-ScheduledTask -TaskPath $t.Substring(0, $i + 1) -TaskName $t.Substring($i + 1) -ErrorAction SilentlyContinue | Out-Null
            } catch {}
        }
        try { Set-Service -Name "NvTelemetryContainer" -StartupType Automatic -ErrorAction SilentlyContinue; Start-Service -Name "NvTelemetryContainer" -ErrorAction SilentlyContinue } catch {}
        try { Get-ScheduledTask -TaskName "Nv*" -ErrorAction SilentlyContinue | ForEach-Object { Enable-ScheduledTask -TaskPath $_.TaskPath -TaskName $_.TaskName -ErrorAction SilentlyContinue | Out-Null } } catch {}
        try { Set-Service -Name "AMD Crash Defender Service" -StartupType Manual -ErrorAction SilentlyContinue } catch {}
        try { Get-ScheduledTask -TaskName "AMD*" -ErrorAction SilentlyContinue | ForEach-Object { Enable-ScheduledTask -TaskPath $_.TaskPath -TaskName $_.TaskName -ErrorAction SilentlyContinue | Out-Null } } catch {}

        # Storage
        fsutil behavior set memoryusage 1 2>$null | Out-Null

        # Privacy
        try { Set-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\LocationAndSensors" -Name "DisableLocation" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue } catch {}
        foreach ($cap in @("location", "webcam", "microphone")) {
            try { Set-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\CapabilityAccessManager\ConsentStore\$cap" -Name "Value" -Value "Allow" -Type String -Force -ErrorAction SilentlyContinue } catch {}
        }
        try {
            Set-ItemProperty -Path "HKCU:\Software\Microsoft\Clipboard" -Name "EnableClipboardHistory" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue
            Set-ItemProperty -Path "HKCU:\Software\Microsoft\Clipboard" -Name "CloudClipboardAutomaticUpload" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue
        } catch {}
        try { Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" -Name "Start_TrackProgs" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue } catch {}
        try { Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Privacy" -Name "TailoredExperiencesWithDiagnosticDataEnabled" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue } catch {}

        # General
        try { Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem" -Name "LongPathsEnabled" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue } catch {}
        try { Set-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Schedule\Maintenance" -Name "MaintenanceDisabled" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue } catch {}

        Write-Log "Windows revert complete. Reboot recommended." "OK"
    } else {
        try {
            defaults write com.apple.universalaccess reduceTransparency -bool false
            defaults write com.apple.universalaccess reduceMotion -bool false
            defaults write NSGlobalDomain NSAutomaticWindowAnimationsEnabled -bool true
            defaults delete com.apple.dock expose-animation-duration 2>$null
            defaults delete com.apple.dashboard mcx-disabled 2>$null
            defaults delete NSGlobalDomain KeyRepeat 2>$null
            defaults delete NSGlobalDomain InitialKeyRepeat 2>$null
            defaults write com.apple.assistant.support "Assistant Enabled" -bool true 2>$null
            defaults write com.apple.Siri SiriEnabled -bool true 2>$null
            tmutil enable 2>$null
            softwareupdate --schedule on 2>$null | Out-Null
            defaults write com.apple.SoftwareUpdate AutomaticCheckEnabled -bool true 2>$null
            defaults write com.apple.SoftwareUpdate AutomaticDownload -bool true 2>$null
            defaults write com.apple.SoftwareUpdate CriticalUpdateInstall -bool true 2>$null
            defaults delete com.apple.dock autohide-time-modifier 2>$null
            defaults delete com.apple.dock autohide-delay 2>$null
            defaults write NSGlobalDomain AppleEnableMenuBarTransparency -bool true 2>$null
            defaults write com.apple.screencapture disable-shadow -bool false 2>$null
            defaults write com.apple.coreservices.useractivityd ActivityAdvertisingAllowed -bool true 2>$null
            defaults write com.apple.coreservices.useractivityd ActivityReceivingAllowed -bool true 2>$null
            mdutil -i on / 2>$null
            pmset -c sleep 10 2>$null; pmset -a sms 1 2>$null
            killall Dock 2>$null
            killall SystemUIServer 2>$null
            killall Siri 2>$null
            Write-Log "macOS revert complete." "OK"
        } catch { Write-Log "Revert partial." "WARN" }
    }
    # Restore per-service toggles and run any explicit Off actions.
    if ($Script:Tweaks) {
        foreach ($t in $Script:Tweaks) {
            try {
                if ($t.Off) { & $t.Off }
                elseif ($t.Svc) { Invoke-ServiceRestore -Name $t.Svc }
            } catch {}
        }
    }
    $Script:Config.TweakStates = @{}
    Save-Config
}

