    if (-not $IsMac) { Write-Log "macOS only." "WARN"; return }
    try { & defaults delete $Domain $Key 2>$null; Write-Log "defaults delete $Domain $Key" "OK" } catch { Write-Log "defaults delete failed: $Domain $Key" "WARN" }
