function Invoke-MacCleanup {
    param([string[]]$Paths, [string]$Label = "Cache")
    if (-not $IsMac) { Write-Log "macOS only." "WARN"; return }
    foreach ($p in $Paths) {
        try {
            if (Test-Path $p) {
                Get-ChildItem -Path $p -Force -ErrorAction SilentlyContinue | ForEach-Object {
