    # General additions
    @{Id="longpaths";Name="Enable long file paths";Desc="Removes the 260-character path limit for apps that opt in. Helps mod and asset tools.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="General";Action={Invoke-LongPaths}},
    @{Id="nomaintenance";Name="Disable automatic maintenance";Desc="Stops Windows from running background maintenance during your session.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="General";Action={Invoke-DisableAutoMaintenance}},

    # macOS additions
    @{Id="macsiri";Name="Disable Siri (Mac)";Desc="Turns off Siri and its background listener. Less idle CPU.";Risk="Safe";Free=$true;Win=$false;Mac=$true;Cat="Services";Action={Invoke-MacDisableSiri}},
    @{Id="mactm";Name="Disable Time Machine (Mac)";Desc="Stops Time Machine from running background backups. Re-enable when you want backups.";Risk="Caution";Free=$true;Win=$false;Mac=$true;Cat="Storage";Action={Invoke-MacDisableTimeMachine}},
    @{Id="macupdates";Name="Disable automatic updates (Mac)";Desc="Stops macOS from checking and downloading updates in the background.";Risk="Caution";Free=$true;Win=$false;Mac=$true;Cat="Services";Action={Invoke-MacDisableAutoUpdates}},
    @{Id="macdock";Name="Disable Dock animations (Mac)";Desc="Removes Dock hide/show animation and delay for a snappier desktop.";Risk="Safe";Free=$true;Win=$false;Mac=$true;Cat="Visual";Action={Invoke-MacDockAnimationsOff}},
    @{Id="macmenubar";Name="Disable menu bar transparency (Mac)";Desc="Makes the menu bar opaque. Less compositor work.";Risk="Safe";Free=$true;Win=$false;Mac=$true;Cat="Visual";Action={Invoke-MacMenuBarTransparencyOff}},
    @{Id="macshots";Name="Disable screenshot shadow (Mac)";Desc="Removes the drop shadow from screenshots. Faster captures and smaller files.";Risk="Safe";Free=$true;Win=$false;Mac=$true;Cat="Visual";Action={Invoke-MacScreenshotShadowOff}},
    @{Id="machandoff";Name="Disable Handoff (Mac)";Desc="Stops Handoff/Continuity advertising and receiving in the background.";Risk="Safe";Free=$true;Win=$false;Mac=$true;Cat="Services";Action={Invoke-MacDisableHandoff}},

    # ---------- v5.3 EXPANSION: GENERAL ----------
    @{Id="winwelcomeoff";Name="Disable Windows welcome suggestions";Desc="Turns off the post-update welcome screen, suggested apps and soft-landing prompts. Less background content fetching.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="General";Action={Invoke-RegGroup -Items @(
        @{Path="HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager";Name="SoftLandingEnabled";Value=0},
        @{Path="HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager";Name="SubscribedContent-310093Enabled";Value=0},
        @{Path="HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager";Name="SubscribedContent-338388Enabled";Value=0},
        @{Path="HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager";Name="SubscribedContent-338389Enabled";Value=0}
    )}},
    @{Id="startrecommendoff";Name="Disable Start menu recommendations";Desc="Removes recommended apps and tips from Start. Less background content and a cleaner menu.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="General";Action={Invoke-RegGroup -Items @(
        @{Path="HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced";Name="Start_IrisRecommendations";Value=0},
        @{Path="HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced";Name="Start_AccountNotifications";Value=0}
    )}},
    @{Id="startrecentoff";Name="Hide recent items in Start";Desc="Stops Start from tracking and showing recently opened apps and documents.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="General";Action={Invoke-RegSet -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" -Name "Start_TrackDocs" -Value 0}},
    @{Id="quickaccessrecent";Name="Hide recent files in Quick Access";Desc="Stops File Explorer from listing recently used files. Less disk and shell work.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="General";Action={Invoke-RegSet -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" -Name "ShowRecent" -Value 0}},
    @{Id="quickaccessfrequent";Name="Hide frequent folders in Quick Access";Desc="Stops File Explorer from listing frequently used folders.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="General";Action={Invoke-RegSet -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" -Name "ShowFrequent" -Value 0}},
    @{Id="wininkoff";Name="Disable Windows Ink Workspace";Desc="Removes the Ink Workspace and its background pen services.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="General";Action={Invoke-RegSet -Path "HKLM:\SOFTWARE\Policies\Microsoft\WindowsInkWorkspace" -Name "AllowWindowsInkWorkspace" -Value 0}},
    @{Id="meetnowhide";Name="Hide Meet Now button";Desc="Removes the Meet Now icon from the taskbar and its background helper.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="General";Action={Invoke-RegSet -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" -Name "HideSCAMeetNow" -Value 1}},
    @{Id="bingsearchoff";Name="Disable Bing search in Start";Desc="Stops Start search from sending queries to Bing and Cortana. Local results only.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="General";Action={Invoke-RegGroup -Items @(
        @{Path="HKCU:\Software\Microsoft\Windows\CurrentVersion\Search";Name="BingSearchEnabled";Value=0},
        @{Path="HKCU:\Software\Microsoft\Windows\CurrentVersion\Search";Name="CortanaConsent";Value=0}
    )}},
    @{Id="searchboxhide";Name="Hide taskbar search box";Desc="Collapses the taskbar search box to an icon-only button and reduces shell rendering.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="General";Action={Invoke-RegSet -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Search" -Name "SearchboxTaskbarMode" -Value 1}},
    @{Id="taskviewhide";Name="Hide Task View button";Desc="Removes the Task View button from the taskbar.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="General";Action={Invoke-RegSet -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" -Name "ShowTaskViewButton" -Value 0}},
    @{Id="widgetstaskbarhide";Name="Hide widgets taskbar button";Desc="Removes the widgets/news button from the taskbar. Pair with Disable Widgets/News for the full effect.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="General";Action={Invoke-RegSet -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" -Name "TaskbarDa" -Value 0}},
    @{Id="lockstoriesoff";Name="Disable lock screen Spotlight";Desc="Turns off rotating lock-screen images, tips and Spotlight overlays. Less network and compositor work.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="General";Action={Invoke-RegGroup -Items @(
        @{Path="HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager";Name="RotatingLockScreenEnabled";Value=0},
        @{Path="HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager";Name="RotatingLockScreenOverlayEnabled";Value=0}
    )}},
    @{Id="activityfeedoff";Name="Disable Timeline activity feed";Desc="Stops Windows collecting, publishing and uploading activity history for Timeline.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="General";Action={Invoke-RegGroup -Items @(
        @{Path="HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced";Name="EnableActivityFeed";Value=0},
        @{Path="HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced";Name="PublishUserActivities";Value=0},
        @{Path="HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced";Name="UploadUserActivities";Value=0}
    )}},
    @{Id="desktopslideshowoff";Name="Disable desktop slideshow";Desc="Stops the desktop wallpaper slideshow and its periodic image decoding.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="General";Action={Invoke-RegSet -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Wallpapers" -Name "BackgroundType" -Value 0}},
    @{Id="clearrecyclebin";Name="Empty Recycle Bin";Desc="Permanently deletes everything in the Recycle Bin. Frees disk space.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="General";Action={if($IsWin){Clear-RecycleBin -Force -ErrorAction SilentlyContinue; Write-Log "Recycle Bin emptied." "OK"}}},

    # ---------- v5.3 EXPANSION: INPUT ----------
    @{Id="mousesens10";Name="Max mouse sensitivity";Desc="Sets the Windows pointer speed to 10 for faster desktop movement. Pair with Mouse Precision for 1:1 tracking.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Input";Action={Invoke-RegSet -Path "HKCU:\Control Panel\Mouse" -Name "MouseSensitivity" -Value "10" -Type String}},
    @{Id="filterkeysoff";Name="Disable Filter Keys";Desc="Turns off Filter Keys so brief or repeated key presses are not ignored.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Input";Action={Invoke-RegSet -Path "HKCU:\Control Panel\Accessibility\Keyboard Response" -Name "Flags" -Value "122" -Type String}},
    @{Id="stickykeysoff";Name="Disable Sticky Keys";Desc="Turns off Sticky Keys so modifier keys do not latch during play.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Input";Action={Invoke-RegSet -Path "HKCU:\Control Panel\Accessibility\StickyKeys" -Name "Flags" -Value "506" -Type String}},
    @{Id="togglekeysoff";Name="Disable Toggle Keys";Desc="Turns off Toggle Keys beeps for Caps Lock, Num Lock and Scroll Lock.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Input";Action={Invoke-RegSet -Path "HKCU:\Control Panel\Accessibility\ToggleKeys" -Name "Flags" -Value "58" -Type String}},
    @{Id="mousekeysoff";Name="Disable Mouse Keys";Desc="Turns off Mouse Keys so the numeric keypad cannot move the pointer.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Input";Action={Invoke-RegSet -Path "HKCU:\Control Panel\Accessibility\MouseKeys" -Name "Flags" -Value "0" -Type String}},
    @{Id="cursorblinkoff";Name="Disable cursor blink";Desc="Stops the text cursor from blinking. Removes a small continuous repaint.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Input";Action={Invoke-RegSet -Path "HKCU:\Control Panel\Desktop" -Name "CursorBlinkRate" -Value "-1" -Type String}},
    @{Id="scrollinactiveoff";Name="Disable scroll inactive windows";Desc="Stops the mouse wheel from scrolling windows you are not using. Prevents accidental input in the background.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Input";Action={Invoke-RegSet -Path "HKCU:\Control Panel\Desktop" -Name "MouseWheelRouting" -Value 0}},
    @{Id="hungapptimeout";Name="Faster hung app timeout";Desc="Shortens the wait before Windows marks an app as not responding and kills it faster.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Input";Action={Invoke-RegGroup -Items @(
        @{Path="HKCU:\Control Panel\Desktop";Name="HungAppTimeout";Value="1000";Type="String"},
        @{Path="HKCU:\Control Panel\Desktop";Name="WaitToKillAppTimeout";Value="2000";Type="String"}
    )}},
    @{Id="autokillhung";Name="Auto-end hung apps";Desc="Lets Windows close unresponsive apps automatically instead of waiting for a dialog.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Input";Action={Invoke-RegSet -Path "HKCU:\Control Panel\Desktop" -Name "AutoEndTasks" -Value "1" -Type String}},
    @{Id="foregroundboost";Name="Foreground priority boost";Desc="Sets Win32PrioritySeparation to 38 so the active game gets a larger CPU quantum slice.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Input";Action={Invoke-RegSet -Path "HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl" -Name "Win32PrioritySeparation" -Value 38}},

    # ---------- v5.3 EXPANSION: NETWORK ----------
    @{Id="dnsgoogle";Name="Google DNS";Desc="Sets 8.8.8.8 and 8.8.4.4 on active adapters, then flushes DNS. Low-latency public resolver.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Ping Optimizer";Action={if($IsWin){Get-NetAdapter -ErrorAction SilentlyContinue | ForEach-Object { try { Set-DnsClientServerAddress -InterfaceIndex $_.ifIndex -ServerAddresses @("8.8.8.8","8.8.4.4") -ErrorAction SilentlyContinue } catch {} }; ipconfig /flushdns 2>$null | Out-Null; Write-Log "Google DNS applied." "OK"};Off={if($IsWin){Get-NetAdapter -ErrorAction SilentlyContinue | ForEach-Object { try { Set-DnsClientServerAddress -InterfaceIndex $_.ifIndex -ResetServerAddresses -ErrorAction SilentlyContinue } catch {} }; ipconfig /flushdns 2>$null | Out-Null; Write-Log "DNS reset to automatic." "OK"}}}},
    @{Id="dnsquad9";Name="Quad9 DNS";Desc="Sets 9.9.9.9 and 149.112.112.112 on active adapters with malware blocking. Flushes DNS after.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Ping Optimizer";Action={if($IsWin){Get-NetAdapter -ErrorAction SilentlyContinue | ForEach-Object { try { Set-DnsClientServerAddress -InterfaceIndex $_.ifIndex -ServerAddresses @("9.9.9.9","149.112.112.112") -ErrorAction SilentlyContinue } catch {} }; ipconfig /flushdns 2>$null | Out-Null; Write-Log "Quad9 DNS applied." "OK"};Off={if($IsWin){Get-NetAdapter -ErrorAction SilentlyContinue | ForEach-Object { try { Set-DnsClientServerAddress -InterfaceIndex $_.ifIndex -ResetServerAddresses -ErrorAction SilentlyContinue } catch {} }; ipconfig /flushdns 2>$null | Out-Null; Write-Log "DNS reset to automatic." "OK"}}}},
    @{Id="dnsauto";Name="Reset DNS to automatic";Desc="Clears manual DNS servers and returns every adapter to DHCP-provided DNS.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Ping Optimizer";Action={if($IsWin){Get-NetAdapter -ErrorAction SilentlyContinue | ForEach-Object { try { Set-DnsClientServerAddress -InterfaceIndex $_.ifIndex -ResetServerAddresses -ErrorAction SilentlyContinue } catch {} }; ipconfig /flushdns 2>$null | Out-Null; Write-Log "DNS reset to automatic." "OK"}}},
    @{Id="teredooff";Name="Disable Teredo tunneling";Desc="Turns off the Teredo IPv6 transition tunnel. Less background tunnel traffic.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Ping Optimizer";Action={Invoke-Cmd -Cmd "netsh interface teredo set state disabled";Off={Invoke-Cmd -Cmd "netsh interface teredo set state default"}}},
    @{Id="isatapoff";Name="Disable ISATAP";Desc="Turns off the ISATAP IPv6 transition adapter. Less background network overhead.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Ping Optimizer";Action={Invoke-Cmd -Cmd "netsh interface isatap set state disabled";Off={Invoke-Cmd -Cmd "netsh interface isatap set state default"}}},
    @{Id="six4off";Name="Disable 6to4";Desc="Turns off the 6to4 IPv6 relay. Fewer virtual adapters and less background traffic.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Ping Optimizer";Action={Invoke-Cmd -Cmd "netsh interface 6to4 set state disabled";Off={Invoke-Cmd -Cmd "netsh interface 6to4 set state default"}}},
    @{Id="rscdisable";Name="Disable Receive Segment Coalescing";Desc="Stops the NIC from batching received packets. Lower latency, slightly more CPU.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Ping Optimizer";Action={Invoke-Cmd -Cmd "netsh int tcp set global rsc=disabled";Off={Invoke-Cmd -Cmd "netsh int tcp set global rsc=enabled"}}},
    @{Id="initialrto";Name="Lower TCP initial retransmit timeout";Desc="Sets the initial TCP retransmission timeout to 2000 ms. Faster recovery from a dropped packet.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Ping Optimizer";Action={Invoke-Cmd -Cmd "netsh int tcp set global initialRto=2000"}},
    @{Id="wifipowersave";Name="Disable Wi-Fi power saving";Desc="Sets adapter power saving to Disabled so the Wi-Fi radio does not sleep between packets.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Ping Optimizer";Action={Invoke-AdapterProp -DisplayName "Power Saving Mode" -Value "Disabled";Off={Invoke-AdapterProp -DisplayName "Power Saving Mode" -Value "Enabled"}}},
    @{Id="eeeoff";Name="Disable Energy Efficient Ethernet";Desc="Turns off EEE on Ethernet adapters. Keeps the link fully awake for steadier latency.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Ping Optimizer";Action={Invoke-AdapterProp -DisplayName "Energy Efficient Ethernet" -Value "Disabled";Off={Invoke-AdapterProp -DisplayName "Energy Efficient Ethernet" -Value "Enabled"}}},
    @{Id="flowcontroloff";Name="Disable Ethernet flow control";Desc="Turns off adapter flow control so pause frames do not delay game packets.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Ping Optimizer";Action={Invoke-AdapterProp -DisplayName "Flow Control" -Value "Disabled";Off={Invoke-AdapterProp -DisplayName "Flow Control" -Value "Auto"}}},
    @{Id="woloff";Name="Disable Wake on Magic Packet";Desc="Stops the NIC from waking the PC for magic packets. Less standby power and background wake events.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Ping Optimizer";Action={Invoke-AdapterProp -DisplayName "Wake on Magic Packet" -Value "Disabled";Off={Invoke-AdapterProp -DisplayName "Wake on Magic Packet" -Value "Enabled"}}},
    @{Id="smbmultichannel";Name="Disable SMB Multichannel";Desc="Stops SMB from opening multiple network connections. Less overhead on small home networks.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Ping Optimizer";Action={Invoke-Cmd -Cmd "Set-SmbClientConfiguration -EnableMultiChannel $false -Force -ErrorAction SilentlyContinue"}},
    @{Id="netdiscoveryoff";Name="Disable Network Discovery";Desc="Blocks the Network Discovery firewall group. Less broadcast chatter and a smaller attack surface.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Ping Optimizer";Action={Invoke-Cmd -Cmd "netsh advfirewall firewall set rule group='Network Discovery' new enable=No"}},
    @{Id="filesharingoff";Name="Disable File and Printer Sharing";Desc="Blocks the File and Printer Sharing firewall group. Less inbound surface and background SMB traffic.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Ping Optimizer";Action={Invoke-Cmd -Cmd "netsh advfirewall firewall set rule group='File and Printer Sharing' new enable=No"}},
    @{Id="flushdnscache";Name="Flush DNS cache";Desc="Clears the Windows resolver cache. Fixes stale DNS entries without resetting the whole stack.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Ping Optimizer";Action={Invoke-Cmd -Cmd "ipconfig /flushdns"}},
    @{Id="flusharp";Name="Flush ARP cache";Desc="Clears the ARP neighbor cache so stale MAC mappings are rebuilt. Helps after router or switch changes.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Ping Optimizer";Action={Invoke-Cmd -Cmd "netsh interface ip delete arpcache"}},

    # ---------- v5.3 EXPANSION: POWER ----------
    @{Id="displaysleepoff";Name="Disable display sleep";Desc="Stops the monitor from sleeping or dimming on AC power. Useful for long sessions and benchmarks.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Power";Action={Invoke-Cmd -Cmd "powercfg /change monitor-timeout-ac 0";Off={Invoke-Cmd -Cmd "powercfg /change monitor-timeout-ac 10"}}},
    @{Id="procmax100";Name="Keep processor at 100% max";Desc="Sets the processor maximum state to 100% on AC and battery so Windows cannot cap clocks.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Power";Action={Invoke-PowerSet -Subgroup "SUB_PROCESSOR" -Setting "PROCTHROTTLEMAX" -AC 100 -DC 100}},
    @{Id="energysaveroff";Name="Disable Energy Saver";Desc="Turns off the Energy Saver power mode that throttles hardware to save power.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Power";Action={Invoke-PowerSet -Subgroup "SUB_ENERGYSAVER" -Setting "ESBATTTHRESHOLD" -AC 0 -DC 0}},
    @{Id="adaptbrightnessoff";Name="Disable adaptive brightness";Desc="Stops Windows from changing display brightness based on ambient light. Steadier frame pacing.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Power";Action={Invoke-PowerSet -Subgroup "SUB_VIDEO" -Setting "ADAPTBRIGHT" -AC 0 -DC 0;Off={Invoke-PowerSet -Subgroup "SUB_VIDEO" -Setting "ADAPTBRIGHT" -AC 1 -DC 1}}},
    @{Id="waketimersoff";Name="Disable wake timers";Desc="Stops scheduled tasks and maintenance from waking the PC. Fewer surprise wake events.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Power";Action={Invoke-PowerSet -Subgroup "SUB_SLEEP" -Setting "BD3B718A-0680-4D9D-8AB2-E1D2B4AC806D" -AC 0 -DC 0;Off={Invoke-PowerSet -Subgroup "SUB_SLEEP" -Setting "BD3B718A-0680-4D9D-8AB2-E1D2B4AC806D" -AC 1 -DC 1}}},
    @{Id="usbwakeoff";Name="Disable USB wake";Desc="Stops USB devices from waking the PC from sleep. Prevents accidental wakes from mice and hubs.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Power";Action={Invoke-PowerSet -Subgroup "SUB_USB" -Setting "48E6B7A6-50F5-4782-A5D4-53BB8F07E226" -AC 0 -DC 0;Off={Invoke-PowerSet -Subgroup "SUB_USB" -Setting "48E6B7A6-50F5-4782-A5D4-53BB8F07E226" -AC 1 -DC 1}}},
    @{Id="modernstandbyoff";Name="Disable Modern Standby";Desc="Forces classic S3 sleep instead of Modern Standby. Reboot required; not supported on every laptop.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Power";Action={Invoke-RegSet -Path "HKLM:\SYSTEM\CurrentControlSet\Control\Power" -Name "PlatformAoAcOverride" -Value 0;Off={Invoke-Cmd -Cmd "Remove-ItemProperty -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Power' -Name PlatformAoAcOverride -Force -ErrorAction SilentlyContinue"}}},
    @{Id="powerplanhigh";Name="High Performance power plan";Desc="Switches to the built-in High Performance plan. Less aggressive clock dropping than Balanced.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Power";Action={Invoke-Cmd -Cmd "powercfg /setactive 8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c";Off={Invoke-Cmd -Cmd "powercfg /setactive 381b4222-f694-41f0-9685-ff5bb260df2e"}}},
    @{Id="powerplanbalanced";Name="Balanced power plan";Desc="Returns to the standard Balanced plan. Useful after testing or on battery.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Power";Action={Invoke-Cmd -Cmd "powercfg /setactive 381b4222-f694-41f0-9685-ff5bb260df2e"}},
    @{Id="cpuidleoff";Name="Disable CPU idle states";Desc="Prevents the CPU from entering deep idle states under load. Lower latency, higher heat and power draw.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Power";Action={Invoke-PowerSet -Subgroup "SUB_PROCESSOR" -Setting "IDLEDISABLE" -AC 1 -DC 1;Off={Invoke-PowerSet -Subgroup "SUB_PROCESSOR" -Setting "IDLEDISABLE" -AC 0 -DC 0}}},

    # ---------- v5.3 EXPANSION: VISUAL ----------
    @{Id="dragfullwindows";Name="Disable window contents while dragging";Desc="Shows only an outline while moving windows. Makes dragging feel instant on slower GPUs.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Visual";Action={Invoke-RegSet -Path "HKCU:\Control Panel\Desktop" -Name "DragFullWindows" -Value "0" -Type String}},
    @{Id="iconsonly";Name="Disable Explorer thumbnails";Desc="Shows icons instead of image and video thumbnails. Less shell decoding and disk I/O.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Visual";Action={Invoke-RegSet -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" -Name "IconsOnly" -Value 1}},
    @{Id="notificationcenteroff";Name="Disable Notification Center";Desc="Turns off the Action Center/Notification Center panel and its background rendering.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Visual";Action={Invoke-RegSet -Path "HKCU:\Software\Policies\Microsoft\Windows\Explorer" -Name "DisableNotificationCenter" -Value 1}},
    @{Id="taskbarbadgesoff";Name="Disable taskbar badges";Desc="Stops app badges and counters from drawing on taskbar icons.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Visual";Action={Invoke-RegSet -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" -Name "TaskbarBadges" -Value 0}},
    @{Id="startanimoff";Name="Disable Start animations";Desc="Turns off Start menu open/close animations for an instant menu.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Visual";Action={Invoke-RegSet -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" -Name "Start_Animation" -Value 0}},

    # ---------- v5.3 EXPANSION: STORAGE ----------
    @{Id="clearupdatecache";Name="Clear Windows Update cache";Desc="Stops Windows Update, deletes downloaded update files and restarts the service. Frees disk space.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Storage";Action={Invoke-Cmd -Cmd "Stop-Service wuauserv -Force -ErrorAction SilentlyContinue; Remove-Item 'C:\Windows\SoftwareDistribution\Download\*' -Recurse -Force -ErrorAction SilentlyContinue; Start-Service wuauserv -ErrorAction SilentlyContinue"}},
    @{Id="clearwerqueue";Name="Clear error report queue";Desc="Deletes queued and archived Windows Error Reporting crash dumps. Frees disk space.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Storage";Action={Invoke-Cleanup -Paths @("C:\ProgramData\Microsoft\Windows\WER\ReportQueue","C:\ProgramData\Microsoft\Windows\WER\ReportArchive","$env:LOCALAPPDATA\Microsoft\Windows\WER") -Label "Error reports"}},
    @{Id="clearstorecache";Name="Reset Microsoft Store cache";Desc="Runs the Store cache reset tool. Fixes stuck downloads and frees stale package cache.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Storage";Action={Invoke-Cmd -Cmd "wsreset.exe -i"}},
    @{Id="clearthumbcache";Name="Clear thumbnail cache";Desc="Deletes Explorer thumbnail databases so they rebuild cleanly. Frees disk space.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Storage";Action={Invoke-Cleanup -Paths @("$env:LOCALAPPDATA\Microsoft\Windows\Explorer") -Label "Thumbnail cache"}},
    @{Id="clearfontcachewin";Name="Clear Windows font cache";Desc="Stops the font cache service, deletes cached font data and restarts it. Fixes stale font rendering.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Storage";Action={Invoke-Cmd -Cmd "Stop-Service FontCache -Force -ErrorAction SilentlyContinue; Remove-Item 'C:\Windows\ServiceProfiles\LocalService\AppData\Local\FontCache\*' -Recurse -Force -ErrorAction SilentlyContinue; Start-Service FontCache -ErrorAction SilentlyContinue"}},
    @{Id="cleardxshader";Name="Clear DirectX shader cache";Desc="Deletes the DirectX shader cache. Games rebuild it on next launch.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Storage";Action={Invoke-Cleanup -Paths @("$env:LOCALAPPDATA\D3DSCache") -Label "DirectX shader cache"}},
    @{Id="clearnvshader";Name="Clear NVIDIA shader cache";Desc="Deletes NVIDIA DX and GL shader caches. Frees space if you change drivers often.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Storage";Action={Invoke-Cleanup -Paths @("$env:LOCALAPPDATA\NVIDIA\DXCache","$env:LOCALAPPDATA\NVIDIA\GLCache") -Label "NVIDIA shader cache"}},
    @{Id="clearamdshader";Name="Clear AMD shader cache";Desc="Deletes AMD DX and GL shader caches. Frees space if you change drivers often.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Storage";Action={Invoke-Cleanup -Paths @("$env:LOCALAPPDATA\AMD\DxCache","$env:LOCALAPPDATA\AMD\GLCache") -Label "AMD shader cache"}},
    @{Id="cleardonotcache";Name="Clear Delivery Optimization cache";Desc="Deletes cached update chunks used for peer-to-peer delivery. Frees disk space.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Storage";Action={Invoke-Cmd -Cmd "Delete-DeliveryOptimizationCache -Force -ErrorAction SilentlyContinue"}},
    @{Id="clearcrashdumps";Name="Clear crash dumps";Desc="Deletes user and system crash dump files. Frees disk space after a crash.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Storage";Action={Invoke-Cleanup -Paths @("$env:LOCALAPPDATA\CrashDumps","C:\Windows\Minidump") -Label "Crash dumps"}},
    @{Id="clearfortnitecache";Name="Clear Fortnite shader cache";Desc="Deletes Fortnite's generated shader cache. The game rebuilds it on next launch.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Storage";Game="Fortnite";Action={Invoke-Cleanup -Paths @("$env:LOCALAPPDATA\FortniteGame\Saved\ShaderCache") -Label "Fortnite shader cache"}},
    @{Id="fnclearlogs";Name="Clear Fortnite logs";Desc="Deletes Fortnite log files to free space and remove stale diagnostics. Logs are recreated on next launch.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Storage";Game="Fortnite";Action={Invoke-Cleanup -Paths @("$env:LOCALAPPDATA\FortniteGame\Saved\Logs") -Label "Fortnite logs"}},
    @{Id="fnclearcrashes";Name="Clear Fortnite crash reports";Desc="Deletes Fortnite crash report files. Frees disk space; no gameplay data is affected.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Storage";Game="Fortnite";Action={Invoke-Cleanup -Paths @("$env:LOCALAPPDATA\FortniteGame\Saved\Crashes","$env:LOCALAPPDATA\CrashReportClient\Saved") -Label "Fortnite crash reports"}},
    @{Id="fngpu";Name="Fortnite high-performance GPU";Desc="Sets Fortnite (FortniteClient-Win64-Shipping.exe) to use the high-performance GPU in Windows graphics settings.";Risk="Safe";Free=$false;Win=$true;Mac=$false;Cat="Game";Game="Fortnite";Action={Invoke-FortniteGpuPreference};Off={Invoke-FortniteGpuPreference -Off}},
    @{Id="fnpriority";Name="Fortnite high process priority";Desc="Raises the priority of the running Fortnite process to High. Start Fortnite first, then apply.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Game";Game="Fortnite";Action={Invoke-FortnitePriority -Priority "High"};Off={Invoke-FortnitePriority -Priority "Normal"}},
    @{Id="optimizessd";Name="Retrim system drive";Desc="Runs Optimize-Volume with -ReTrim on C: to refresh SSD free blocks. Frees performance on full drives.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Storage";Action={Invoke-Cmd -Cmd "Optimize-Volume -DriveLetter C -ReTrim -ErrorAction SilentlyContinue"}},

    # ---------- v5.3 EXPANSION: FIRMWARE-ADJACENT ----------
    @{Id="hypervisoroff";Name="Disable Hyper-V hypervisor at boot";Desc="Sets hypervisorlaunchtype off. Removes virtualization overhead for gaming but breaks WSL2, Docker and VBS. Reboot required.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Firmware";Action={Invoke-BcdSet -Setting "hypervisorlaunchtype" -Value "off";Off={Invoke-BcdSet -Setting "hypervisorlaunchtype" -Value "auto"}}},
    @{Id="vbsdisable";Name="Disable VBS at boot";Desc="Turns off Virtualization-Based Security. Frees CPU cycles for games; lowers isolation. Reboot required.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Firmware";Action={Invoke-RegGroup -Items @(
        @{Path="HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard";Name="EnableVirtualizationBasedSecurity";Value=0},
        @{Path="HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard\Scenarios\HypervisorEnforcedCodeIntegrity";Name="Enabled";Value=0}
    )};Off={Invoke-RegGroup -Items @(
        @{Path="HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard";Name="EnableVirtualizationBasedSecurity";Value=1},
        @{Path="HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard\Scenarios\HypervisorEnforcedCodeIntegrity";Name="Enabled";Value=1}
    )}},
    @{Id="memoryintegrityoff";Name="Disable Memory Integrity";Desc="Turns off HVCI/Memory Integrity. Recovers CPU performance at the cost of kernel-level protection. Reboot required.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Firmware";Action={Invoke-RegSet -Path "HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard\Scenarios\HypervisorEnforcedCodeIntegrity" -Name "Enabled" -Value 0;Off={Invoke-RegSet -Path "HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard\Scenarios\HypervisorEnforcedCodeIntegrity" -Name "Enabled" -Value 1}}},

    # ---------- v5.3 EXPANSION: PRIVACY ----------
    @{Id="suggestedcontentoff";Name="Disable suggested content";Desc="Turns off suggested apps, tips and promotional content across Settings and the shell.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Privacy";Action={Invoke-RegGroup -Items @(
        @{Path="HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager";Name="SubscribedContent-338393Enabled";Value=0},
        @{Path="HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager";Name="SubscribedContent-353694Enabled";Value=0},
        @{Path="HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager";Name="SubscribedContent-353696Enabled";Value=0},
        @{Path="HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager";Name="SystemPaneSuggestionsEnabled";Value=0}
    )}},
    @{Id="silentinstalloff";Name="Disable silent app installs";Desc="Stops Windows from installing promoted apps in the background.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Privacy";Action={Invoke-RegGroup -Items @(
        @{Path="HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager";Name="SilentInstalledAppsEnabled";Value=0},
        @{Path="HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager";Name="PreInstalledAppsEnabled";Value=0},
        @{Path="HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager";Name="OemPreInstalledAppsEnabled";Value=0}
    )}},
    @{Id="inkingoff";Name="Disable inking and typing personalization";Desc="Stops Windows collecting handwriting, typing and contact data for suggestions.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Privacy";Action={Invoke-RegGroup -Items @(
        @{Path="HKCU:\Software\Microsoft\InputPersonalization";Name="RestrictImplicitTextCollection";Value=1},
        @{Path="HKCU:\Software\Microsoft\InputPersonalization";Name="RestrictImplicitInkCollection";Value=1},
        @{Path="HKCU:\Software\Microsoft\InputPersonalization\TrainedDataStore";Name="HarvestContacts";Value=0}
    )}},
    @{Id="speechoff";Name="Disable online speech recognition";Desc="Turns off cloud speech recognition. Less audio processing and data upload.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Privacy";Action={Invoke-RegSet -Path "HKCU:\Software\Microsoft\Speech_OneCore\Settings\OnlineSpeechPrivacy" -Name "HasAccepted" -Value 0}},
    @{Id="cloudsearchoff";Name="Disable cloud search";Desc="Keeps Start and search results local instead of querying the cloud.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Privacy";Action={Invoke-RegSet -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Search" -Name "CloudSearchEnabled" -Value 0}},
    @{Id="remoteassistoff";Name="Disable Remote Assistance";Desc="Blocks unsolicited Remote Assistance invitations. Smaller attack surface.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Privacy";Action={Invoke-RegSet -Path "HKLM:\SYSTEM\CurrentControlSet\Control\Remote Assistance" -Name "fAllowToGetHelp" -Value 0}},
    @{Id="wifisenseoff";Name="Disable Wi-Fi Sense";Desc="Stops Windows from sharing or connecting to crowdsourced Wi-Fi networks.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Privacy";Action={Invoke-RegGroup -Items @(
        @{Path="HKLM:\SOFTWARE\Microsoft\WcmSvc\wifinetworkmanager\config";Name="AutoConnectAllowedOEM";Value=0},
        @{Path="HKCU:\Software\Microsoft\WcmSvc\wifinetworkmanager\config";Name="AutoConnectAllowedOEM";Value=0}
    )}},
    @{Id="recentdocsclear";Name="Clear recent documents";Desc="Deletes the Recent Items list and stops Start from tracking documents.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Privacy";Action={Invoke-Cleanup -Paths @("$env:APPDATA\Microsoft\Windows\Recent") -Label "Recent documents"}},
    @{Id="runhistoryclear";Name="Clear Run dialog history";Desc="Deletes the Win+R history so previous commands are not stored.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Privacy";Action={Invoke-Cmd -Cmd "Remove-Item 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\RunMRU\*' -Force -ErrorAction SilentlyContinue"}},
    @{Id="mruclear";Name="Clear Explorer MRU lists";Desc="Deletes Explorer's most-recently-used file and folder lists.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Privacy";Action={Invoke-Cmd -Cmd "Remove-Item 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\RecentDocs\*' -Force -ErrorAction SilentlyContinue; Remove-Item 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\TypedPaths\*' -Force -ErrorAction SilentlyContinue"}},
    @{Id="notificationhistoryoff";Name="Disable notification history";Desc="Stops Windows storing notification history and action-center entries.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Privacy";Action={Invoke-RegSet -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Notifications\Settings" -Name "NOC_GLOBAL_SETTING_TOASTS_ENABLED" -Value 0}},

    # ---------- v5.3 EXPANSION: SERVICE TOGGLES ----------
    @{Id="svcajrouter";Name="Disable AllJoyn Router";Desc="Stops the AllJoyn Router service used by legacy IoT device discovery.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="AJRouter";Action={Invoke-ServiceDisable -Name "AJRouter"}},
    @{Id="svcalg";Name="Disable Application Layer Gateway";Desc="Stops the ALG service that helps legacy NAT traversal for some protocols.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="ALG";Action={Invoke-ServiceDisable -Name "ALG"}},
    @{Id="svcappreadiness";Name="Disable App Readiness";Desc="Stops the service that pre-stages Store apps before login. Faster boot and less background disk work.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="AppReadiness";Action={Invoke-ServiceDisable -Name "AppReadiness"}},
    @{Id="svcappx";Name="Disable AppX Deployment";Desc="Stops the AppX deployment service used to install and update Store apps. Store app installs will fail.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="AppXSvc";Action={Invoke-ServiceDisable -Name "AppXSvc"}},
    @{Id="svcassignedaccess";Name="Disable Assigned Access Manager";Desc="Stops the kiosk/assigned-access service. Not needed on a gaming PC.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="AssignedAccessManagerSvc";Action={Invoke-ServiceDisable -Name "AssignedAccessManagerSvc"}},
    @{Id="svcbthavctp";Name="Disable Bluetooth AVCTP";Desc="Stops Bluetooth audio/video control transport. Disable only if you do not use Bluetooth audio.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="BthAvctpSvc";Action={Invoke-ServiceDisable -Name "BthAvctpSvc"}},
    @{Id="svcbthhf";Name="Disable Bluetooth Hands-Free";Desc="Stops the Bluetooth hands-free profile. Disable only if you do not use a Bluetooth headset mic.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="BthHFSrv";Action={Invoke-ServiceDisable -Name "BthHFSrv"}},
    @{Id="svccertprop";Name="Disable Certificate Propagation";Desc="Stops smart-card certificate propagation into the user profile.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="CertPropSvc";Action={Invoke-ServiceDisable -Name "CertPropSvc"}},
    @{Id="svcclipsvc";Name="Disable Client License Service";Desc="Stops the Store license service. Already-installed apps keep working; Store purchases may not.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="ClipSVC";Action={Invoke-ServiceDisable -Name "ClipSVC"}},
    @{Id="svccloudbackup";Name="Disable Cloud Backup and Restore";Desc="Stops Windows cloud backup and restore. Less background upload activity.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="CloudBackupRestoreSvc";Action={Invoke-ServiceDisable -Name "CloudBackupRestoreSvc"}},
    @{Id="svcdsmsvc";Name="Disable Device Setup Manager";Desc="Stops background device metadata and setup downloads. Faster idle.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="DsmSvc";Action={Invoke-ServiceDisable -Name "DsmSvc"}},
    @{Id="svcdssvc";Name="Disable Data Sharing Service";Desc="Stops the data sharing broker used by some Store apps.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="DsSvc";Action={Invoke-ServiceDisable -Name "DsSvc"}},
    @{Id="svcdusm";Name="Disable Data Usage service";Desc="Stops the data usage monitor. Network usage reporting in Settings will stop updating.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="DusmSvc";Action={Invoke-ServiceDisable -Name "DusmSvc"}},
    @{Id="svcefs";Name="Disable Encrypting File System";Desc="Stops EFS. Do not disable if you use EFS-encrypted files.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="EFS";Action={Invoke-ServiceDisable -Name "EFS"}},
    @{Id="svcentapp";Name="Disable Enterprise App Management";Desc="Stops enterprise app deployment. Not needed on a personal PC.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="EntAppSvc";Action={Invoke-ServiceDisable -Name "EntAppSvc"}},
    @{Id="svcframeserver";Name="Disable Camera Frame Server";Desc="Stops the shared camera pipeline. Webcams will not work until re-enabled.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="FrameServer";Action={Invoke-ServiceDisable -Name "FrameServer"}},
    @{Id="svcfhsvc";Name="Disable File History";Desc="Stops the File History backup service. Less background disk and network activity.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="fhsvc";Action={Invoke-ServiceDisable -Name "fhsvc"}},
    @{Id="svcgraphicsperf";Name="Disable Graphics Performance Monitor";Desc="Stops the graphics performance logging service used by Task Manager graphs.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="GraphicsPerfSvc";Action={Invoke-ServiceDisable -Name "GraphicsPerfSvc"}},
    @{Id="svchidserv";Name="Disable HID Access";Desc="Stops the Human Interface Device access service. Gamepads and special HID devices may stop working.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="hidserv";Action={Invoke-ServiceDisable -Name "hidserv"}},
    @{Id="svcinstallservice";Name="Disable Store Install Service";Desc="Stops the Microsoft Store install service. Store installs and updates will fail.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="InstallService";Action={Invoke-ServiceDisable -Name "InstallService"}},
    @{Id="svcinventory";Name="Disable Inventory Service";Desc="Stops the inventory service used by enterprise management.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="InventorySvc";Action={Invoke-ServiceDisable -Name "InventorySvc"}},
    @{Id="svcktMRm";Name="Disable KTM RM";Desc="Stops the KTM distributed transaction coordinator helper. Rarely needed on a gaming PC.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="KtmRm";Action={Invoke-ServiceDisable -Name "KtmRm"}},
    @{Id="svclicensemanager";Name="Disable License Manager";Desc="Stops the Windows license manager service. Activation status is unaffected.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="LicenseManager";Action={Invoke-ServiceDisable -Name "LicenseManager"}},
    @{Id="svclltd";Name="Disable Link-Layer Topology Discovery";Desc="Stops LLTD network map discovery. Less LAN broadcast chatter.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="lltdsvc";Action={Invoke-ServiceDisable -Name "lltdsvc"}},
    @{Id="svclmhosts";Name="Disable NetBIOS Helper";Desc="Stops the TCP/IP NetBIOS helper. Less legacy name-resolution traffic.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="lmhosts";Action={Invoke-ServiceDisable -Name "lmhosts"}},
    @{Id="svclxp";Name="Disable Language Experience";Desc="Stops language pack and input-method background updates.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="LxpSvc";Action={Invoke-ServiceDisable -Name "LxpSvc"}},
    @{Id="svcmcp";Name="Disable MCP Management";Desc="Stops the Microsoft cloud management service. Not needed on a home PC.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="McpManagementService";Action={Invoke-ServiceDisable -Name "McpManagementService"}},
    @{Id="svcmessaging";Name="Disable Messaging Service";Desc="Stops the SMS/messaging service. Not needed on a desktop.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="MessagingService";Action={Invoke-ServiceDisable -Name "MessagingService"}},
    @{Id="svcmixedreality";Name="Disable Mixed Reality OpenXR";Desc="Stops the OpenXR runtime service. VR headsets will not work until re-enabled.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="MixedRealityOpenXRSvc";Action={Invoke-ServiceDisable -Name "MixedRealityOpenXRSvc"}},
    @{Id="svcmsiscsi";Name="Disable iSCSI Initiator";Desc="Stops the iSCSI initiator service. Not needed unless you boot or store games on iSCSI.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="MSiSCSI";Action={Invoke-ServiceDisable -Name "MSiSCSI"}},
    @{Id="svcncasvc";Name="Disable Network Connectivity Assistant";Desc="Stops the connectivity assistant that probes network health. Less background traffic.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="NcaSvc";Action={Invoke-ServiceDisable -Name "NcaSvc"}},
    @{Id="svcncbservice";Name="Disable Network Connection Broker";Desc="Stops the broker used by UWP apps to maintain background network connections.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="NcbService";Action={Invoke-ServiceDisable -Name "NcbService"}},
    @{Id="svcnetsetup";Name="Disable Network Setup Service";Desc="Stops the network setup service used for driver and adapter setup.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="NetSetupSvc";Action={Invoke-ServiceDisable -Name "NetSetupSvc"}},
    @{Id="svcnettcp";Name="Disable Net.Tcp Port Sharing";Desc="Stops the WCF port-sharing service. Not needed by games.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="NetTcpPortSharing";Action={Invoke-ServiceDisable -Name "NetTcpPortSharing"}},
    @{Id="svcnfsclnt";Name="Disable NFS Client";Desc="Stops the Network File System client. Not needed unless you mount NFS shares.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="NfsClnt";Action={Invoke-ServiceDisable -Name "NfsClnt"}},
    @{Id="svcpeerdist";Name="Disable BranchCache";Desc="Stops peer-to-peer content caching. Less background disk and network use.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="PeerDistSvc";Action={Invoke-ServiceDisable -Name "PeerDistSvc"}},
    @{Id="svcperceptionsim";Name="Disable Perception Simulation";Desc="Stops the Windows perception simulation service used by mixed reality.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="perceptionsimulation";Action={Invoke-ServiceDisable -Name "perceptionsimulation"}},
    @{Id="svcpimindex";Name="Disable Contact Data Index";Desc="Stops the contact data indexing service used by People and Mail.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="PimIndexMaintenanceSvc";Action={Invoke-ServiceDisable -Name "PimIndexMaintenanceSvc"}},
    @{Id="svcpla";Name="Disable Performance Logs and Alerts";Desc="Stops performance counter logging. Less background disk writes.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="pla";Action={Invoke-ServiceDisable -Name "pla"}},
    @{Id="svcpnrp";Name="Disable Peer Name Resolution";Desc="Stops the PNRP peer name service. Less LAN broadcast traffic.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="PNRPsvc";Action={Invoke-ServiceDisable -Name "PNRPsvc"}},
    @{Id="svcpolicyagent";Name="Disable IPsec Policy Agent";Desc="Stops the IPsec policy agent. Disable only if you do not use IPsec/VPN policies.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="PolicyAgent";Action={Invoke-ServiceDisable -Name "PolicyAgent"}},
    @{Id="svcprintnotify";Name="Disable Print Notifications";Desc="Stops print job notifications. Printing still works through the spooler.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="PrintNotify";Action={Invoke-ServiceDisable -Name "PrintNotify"}},
    @{Id="svcprintworkflow";Name="Disable Print Workflow";Desc="Stops the modern print workflow service. Legacy printing is unaffected.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="PrintWorkflowUserSvc";Action={Invoke-ServiceDisable -Name "PrintWorkflowUserSvc"}},
    @{Id="svcqwave";Name="Disable QWAVE";Desc="Stops the Quality Windows Audio Video Experience QoS service. Less background network shaping.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="QWAVE";Action={Invoke-ServiceDisable -Name "QWAVE"}},
    @{Id="svcremoteaccess";Name="Disable Routing and Remote Access";Desc="Stops the RRAS service. Not needed unless this PC is a router or VPN server.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="RemoteAccess";Action={Invoke-ServiceDisable -Name "RemoteAccess"}},
    @{Id="svcretailemo";Name="Disable Retail Demo";Desc="Stops the retail demo service used in store display PCs.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="RetailDemo";Action={Invoke-ServiceDisable -Name "RetailDemo"}},
    @{Id="svcrmsvc";Name="Disable Radio Management";Desc="Stops the radio management service for Wi-Fi and mobile broadband. Re-enable before using Wi-Fi.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="RmSvc";Action={Invoke-ServiceDisable -Name "RmSvc"}},
    @{Id="svcrpclocator";Name="Disable RPC Locator";Desc="Stops the legacy RPC locator service. Not needed on modern Windows.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="RpcLocator";Action={Invoke-ServiceDisable -Name "RpcLocator"}},
    @{Id="svcscardsvr";Name="Disable Smart Card";Desc="Stops smart-card support. Do not disable if you use a smart card to sign in.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="SCardSvr";Action={Invoke-ServiceDisable -Name "SCardSvr"}},
    @{Id="svcscpolicy";Name="Disable Smart Card Removal Policy";Desc="Stops the smart-card removal policy service.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="SCPolicySvc";Action={Invoke-ServiceDisable -Name "SCPolicySvc"}},
    @{Id="svcsdrsvc";Name="Disable Windows Backup";Desc="Stops the Windows Backup service. Scheduled backups will not run.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="SDRSVC";Action={Invoke-ServiceDisable -Name "SDRSVC"}},
    @{Id="svcsemgr";Name="Disable NFC/SE Manager";Desc="Stops near-field communication and secure-element support. Not needed on most desktops.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="SEMgrSvc";Action={Invoke-ServiceDisable -Name "SEMgrSvc"}},
    @{Id="svcsensordata";Name="Disable Sensor Data Service";Desc="Stops sensor data aggregation for apps. Less background sensor polling.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="SensorDataService";Action={Invoke-ServiceDisable -Name "SensorDataService"}},
    @{Id="svcsensorservice";Name="Disable Sensor Service";Desc="Stops the sensor service. Auto-rotate and some laptop sensors will stop working.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="SensorService";Action={Invoke-ServiceDisable -Name "SensorService"}},
    @{Id="svcsensrsvc";Name="Disable Sensor Monitoring";Desc="Stops sensor monitoring for location and motion. Less background polling.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="SensrSvc";Action={Invoke-ServiceDisable -Name "SensrSvc"}},
    @{Id="svcsharedreality";Name="Disable Spatial Data Service";Desc="Stops the spatial data service used by mixed reality.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="SharedRealitySvc";Action={Invoke-ServiceDisable -Name "SharedRealitySvc"}},
    @{Id="svcshpam";Name="Disable Shared PC Account Manager";Desc="Stops the shared-PC account manager used in schools and kiosks.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="shpamsvc";Action={Invoke-ServiceDisable -Name "shpamsvc"}},
    @{Id="svcsmphost";Name="Disable Storage Spaces SMP";Desc="Stops the Storage Spaces management provider. Not needed without Storage Spaces.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="smphost";Action={Invoke-ServiceDisable -Name "smphost"}},
    @{Id="svcsmsrouter";Name="Disable SMS Router";Desc="Stops the Windows SMS router service. Not needed without cellular messaging.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="SmsRouter";Action={Invoke-ServiceDisable -Name "SmsRouter"}},
    @{Id="svcsnmptrap";Name="Disable SNMP Trap";Desc="Stops sending SNMP traps. Not needed on a home network.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="SNMPTRAP";Action={Invoke-ServiceDisable -Name "SNMPTRAP"}},
    @{Id="svcspectrum";Name="Disable Windows Perception Service";Desc="Stops the perception service used by mixed reality and some camera features.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="spectrum";Action={Invoke-ServiceDisable -Name "spectrum"}},
    @{Id="svcssdpsrv";Name="Disable SSDP Discovery";Desc="Stops SSDP/UPnP discovery. Less LAN broadcast traffic; some media apps lose device discovery.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="SSDPSRV";Action={Invoke-ServiceDisable -Name "SSDPSRV"}},
    @{Id="svcsstp";Name="Disable Secure Socket Tunneling";Desc="Stops the SSTP VPN service. Disable only if you do not use SSTP VPNs.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="SstpSvc";Action={Invoke-ServiceDisable -Name "SstpSvc"}},
    @{Id="svcstisvc";Name="Disable Still Image Acquisition";Desc="Stops scanner and still-camera acquisition events.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="StiSvc";Action={Invoke-ServiceDisable -Name "StiSvc"}},
    @{Id="svcstorsvc";Name="Disable Storage Service";Desc="Stops the storage service that manages Storage Spaces and disk notifications.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="StorSvc";Action={Invoke-ServiceDisable -Name "StorSvc"}},
    @{Id="svcsvsvc";Name="Disable Spot Verifier";Desc="Stops the spot verifier service used to validate corrupted files.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="svsvc";Action={Invoke-ServiceDisable -Name "svsvc"}},
    @{Id="svcswprv";Name="Disable Shadow Copy Provider";Desc="Stops the software shadow copy provider. System Restore and some backups will not work.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="SwPrv";Action={Invoke-ServiceDisable -Name "SwPrv"}},
    @{Id="svctiering";Name="Disable Storage Tiers Management";Desc="Stops storage tier optimization for tiered volumes.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="TieringEngineService";Action={Invoke-ServiceDisable -Name "TieringEngineService"}},
    @{Id="svctimebroker";Name="Disable Time Broker";Desc="Stops the time broker that schedules UWP background work.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="TimeBrokerSvc";Action={Invoke-ServiceDisable -Name "TimeBrokerSvc"}},
    @{Id="svctzauto";Name="Disable Time Zone Updater";Desc="Stops automatic time-zone changes. Set your time zone manually first.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="tzautoupdate";Action={Invoke-ServiceDisable -Name "tzautoupdate"}},
    @{Id="svcuevagent";Name="Disable User Experience Virtualization";Desc="Stops the UE-V settings roaming service. Not needed on a personal PC.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="UevAgentService";Action={Invoke-ServiceDisable -Name "UevAgentService"}},
    @{Id="svcumrdp";Name="Disable RDP Port Redirector";Desc="Stops the Remote Desktop user-mode port redirector. Pair with Block Remote Desktop.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="UmRdpService";Action={Invoke-ServiceDisable -Name "UmRdpService"}},
    @{Id="svcupnphost";Name="Disable UPnP Device Host";Desc="Stops hosting UPnP devices from this PC. Less background discovery traffic.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="upnphost";Action={Invoke-ServiceDisable -Name "upnphost"}},
    @{Id="svcual";Name="Disable User Access Logging";Desc="Stops user access logging used by Windows Server roles.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="UserAccessLoggingSvc";Action={Invoke-ServiceDisable -Name "UserAccessLoggingSvc"}},
    @{Id="svcuserdata";Name="Disable User Data Access";Desc="Stops user data access for UWP apps. Some Store apps lose saved data.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="UserDataSvc";Action={Invoke-ServiceDisable -Name "UserDataSvc"}},
    @{Id="svcusermanager";Name="Disable User Manager";Desc="Stops the user manager service used by multi-user and Store scenarios.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="UserManager";Action={Invoke-ServiceDisable -Name "UserManager"}},
    @{Id="svcvds";Name="Disable Virtual Disk";Desc="Stops the virtual disk service used by Disk Management and some storage tools.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="vds";Action={Invoke-ServiceDisable -Name "vds"}},
    @{Id="svcw32time";Name="Disable Windows Time";Desc="Stops automatic clock sync. Your clock can drift; enable before online play if it does.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="W32Time";Action={Invoke-ServiceDisable -Name "W32Time"}},
    @{Id="svcbio";Name="Disable Biometric Service";Desc="Stops Windows Hello biometric support. Password and PIN sign-in still work.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="WbioSrvc";Action={Invoke-ServiceDisable -Name "WbioSrvc"}},
    @{Id="svcdiaghost";Name="Disable Diagnostic Service Host";Desc="Stops the diagnostic policy service host. Less background troubleshooting.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="WdiServiceHost";Action={Invoke-ServiceDisable -Name "WdiServiceHost"}},
    @{Id="svcdiagsystem";Name="Disable Diagnostic System Host";Desc="Stops the diagnostic system host. Less background troubleshooting and logging.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="WdiSystemHost";Action={Invoke-ServiceDisable -Name "WdiSystemHost"}},
    @{Id="svcwebclient";Name="Disable WebClient";Desc="Stops the WebDAV client service. Not needed unless you open WebDAV shares.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="WebClient";Action={Invoke-ServiceDisable -Name "WebClient"}},
    @{Id="svcwec";Name="Disable Windows Event Collector";Desc="Stops event collection from other machines. Not needed on a home PC.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="Wecsvc";Action={Invoke-ServiceDisable -Name "Wecsvc"}},
    @{Id="svcwephost";Name="Disable Encryption Provider Host";Desc="Stops the encryption provider host used by some enterprise security software.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="WEPHOSTSVC";Action={Invoke-ServiceDisable -Name "WEPHOSTSVC"}},
    @{Id="svcwiarpc";Name="Disable Image Acquisition";Desc="Stops Windows Image Acquisition for scanners and cameras.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="WiaRpc";Action={Invoke-ServiceDisable -Name "WiaRpc"}},
    @{Id="svcwman";Name="Disable Windows Management Service";Desc="Stops the Windows Management service used by some enterprise management tools.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="WManSvc";Action={Invoke-ServiceDisable -Name "WManSvc"}},
    @{Id="svcwmiapsrv";Name="Disable WMI Performance Adapter";Desc="Stops the WMI performance adapter. Frees a small amount of background CPU.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="wmiApSrv";Action={Invoke-ServiceDisable -Name "wmiApSrv"}},
    @{Id="svcwmpnet";Name="Disable WMP Network Sharing";Desc="Stops Windows Media Player network sharing. Less background network activity.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="WMPNetworkSvc";Action={Invoke-ServiceDisable -Name "WMPNetworkSvc"}},
    @{Id="svcwpcmonsvc";Name="Disable Parental Controls";Desc="Stops the Family Safety monitoring service.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="WpcMonSvc";Action={Invoke-ServiceDisable -Name "WpcMonSvc"}},
    @{Id="svcwpdbusenum";Name="Disable Portable Device Enumerator";Desc="Stops enumerating portable devices and media players.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="WPDBusEnum";Action={Invoke-ServiceDisable -Name "WPDBusEnum"}},
    @{Id="svcxbgm";Name="Disable Xbox Game Monitoring";Desc="Stops the Xbox game monitoring helper. Pair with the other Xbox service tweaks.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Services";Svc="xbgm";Action={Invoke-ServiceDisable -Name "xbgm"}},

    # ---------- v5.3 EXPANSION: macOS GENERAL ----------
    @{Id="macreopenwindows";Name="Disable window restore at login";Desc="Stops macOS reopening every app window after login or reboot. Faster, cleaner login.";Risk="Safe";Free=$true;Win=$false;Mac=$true;Cat="General";Action={Invoke-MacDefaultsGroup -Items @(
        @{Domain="com.apple.loginwindow";Key="TALLogoutSavesState";Type="bool";Value="false"},
        @{Domain="NSGlobalDomain";Key="NSQuitAlwaysKeepsWindows";Type="bool";Value="false"}
    )}},
    @{Id="maccrashdialog";Name="Disable crash reporter dialog";Desc="Stops the application-quit-unexpectedly dialog from interrupting you. Reports are still logged.";Risk="Safe";Free=$true;Win=$false;Mac=$true;Cat="General";Action={Invoke-MacDefaults -Domain "com.apple.CrashReporter" -Key "DialogType" -Type string -Value "none"}},

    # ---------- v5.3 EXPANSION: macOS INPUT ----------
    @{Id="macmouseaccel";Name="Disable mouse acceleration (Mac)";Desc="Turns off macOS pointer acceleration for 1:1 mouse movement. Log out and back in to apply.";Risk="Caution";Free=$true;Win=$false;Mac=$true;Cat="Input";Action={Invoke-MacDefaults -Domain ".GlobalPreferences" -Key "com.apple.mouse.scaling" -Type float -Value "-1"}},
    @{Id="mactrackpadaccel";Name="Disable trackpad acceleration (Mac)";Desc="Turns off trackpad pointer acceleration for linear movement. Log out and back in to apply.";Risk="Caution";Free=$true;Win=$false;Mac=$true;Cat="Input";Action={Invoke-MacDefaults -Domain ".GlobalPreferences" -Key "com.apple.trackpad.scaling" -Type float -Value "-1"}},
    @{Id="mackeyrepeat";Name="Fast keyboard repeat (Mac)";Desc="Sets the shortest key-repeat delay and fastest repeat rate. Snappier movement and menu navigation.";Risk="Safe";Free=$true;Win=$false;Mac=$true;Cat="Input";Action={Invoke-MacDefaultsGroup -Items @(
        @{Domain="NSGlobalDomain";Key="KeyRepeat";Type="int";Value="2"},
        @{Domain="NSGlobalDomain";Key="InitialKeyRepeat";Type="int";Value="15"}
    )}},
    @{Id="macpresshold";Name="Disable press-and-hold (Mac)";Desc="Stops the accent-character popup from swallowing repeated key presses.";Risk="Safe";Free=$true;Win=$false;Mac=$true;Cat="Input";Action={Invoke-MacDefaults -Domain "NSGlobalDomain" -Key "ApplePressAndHoldEnabled" -Type bool -Value "false"}},
    @{Id="macscrollanim";Name="Disable smooth scrolling (Mac)";Desc="Turns off animated scrolling for instant, lower-overhead scrolling.";Risk="Safe";Free=$true;Win=$false;Mac=$true;Cat="Input";Action={Invoke-MacDefaults -Domain "NSGlobalDomain" -Key "NSScrollAnimationEnabled" -Type bool -Value "false"}},
    @{Id="macrubberband";Name="Disable rubber-band scrolling (Mac)";Desc="Stops the elastic overscroll bounce. Less compositor work while scrolling.";Risk="Safe";Free=$true;Win=$false;Mac=$true;Cat="Input";Action={Invoke-MacDefaults -Domain "NSGlobalDomain" -Key "NSScrollViewRubberbanding" -Type bool -Value "false"}},

    # ---------- v5.3 EXPANSION: macOS NETWORK ----------
    @{Id="macdnscloud";Name="Cloudflare DNS (Mac)";Desc="Sets 1.1.1.1 and 1.0.0.1 on every network service and flushes DNS.";Risk="Safe";Free=$true;Win=$false;Mac=$true;Cat="Ping Optimizer";Action={Invoke-MacDns -Servers @("1.1.1.1","1.0.0.1")};Off={Invoke-MacDns -Servers @("Empty")}},
    @{Id="macdnsgoogle";Name="Google DNS (Mac)";Desc="Sets 8.8.8.8 and 8.8.4.4 on every network service and flushes DNS.";Risk="Safe";Free=$true;Win=$false;Mac=$true;Cat="Ping Optimizer";Action={Invoke-MacDns -Servers @("8.8.8.8","8.8.4.4")};Off={Invoke-MacDns -Servers @("Empty")}},
    @{Id="macdnsauto";Name="Reset DNS to automatic (Mac)";Desc="Clears manual DNS servers on every network service and returns to DHCP.";Risk="Safe";Free=$true;Win=$false;Mac=$true;Cat="Ping Optimizer";Action={Invoke-MacDns -Servers @("Empty")}},
    @{Id="macipv6off";Name="Disable IPv6 (Mac)";Desc="Turns off IPv6 on every network service. Less background traffic on IPv4-only networks.";Risk="Caution";Free=$true;Win=$false;Mac=$true;Cat="Ping Optimizer";Action={Invoke-MacIpv6Off};Off={Invoke-MacIpv6Off -On}},
    @{Id="macairdropoff";Name="Disable AirDrop (Mac)";Desc="Turns off AirDrop advertising and receiving. Less background radio activity.";Risk="Safe";Free=$true;Win=$false;Mac=$true;Cat="Ping Optimizer";Action={Invoke-MacDefaults -Domain "com.apple.NetworkBrowser" -Key "DisableAirDrop" -Type bool -Value "true"}},
    @{Id="macflushdns";Name="Flush DNS cache (Mac)";Desc="Clears the macOS DNS cache and restarts mDNSResponder. Fixes stale lookups.";Risk="Safe";Free=$true;Win=$false;Mac=$true;Cat="Ping Optimizer";Action={if($IsMac){& dscacheutil -flushcache 2>$null; & killall -HUP mDNSResponder 2>$null; Write-Log "DNS cache flushed." "OK"}}},

    # ---------- v5.3 EXPANSION: macOS POWER ----------
    @{Id="macpowernap";Name="Disable Power Nap (Mac)";Desc="Stops background mail, backup and update work while the Mac sleeps.";Risk="Safe";Free=$true;Win=$false;Mac=$true;Cat="Power";Action={Invoke-MacPmset -Arguments "-a powernap 0";Off={Invoke-MacPmset -Arguments "-a powernap 1"}}},
    @{Id="macwomp";Name="Disable wake on network (Mac)";Desc="Stops network access from waking the Mac. Less surprise wake activity.";Risk="Safe";Free=$true;Win=$false;Mac=$true;Cat="Power";Action={Invoke-MacPmset -Arguments "-a womp 0";Off={Invoke-MacPmset -Arguments "-a womp 1"}}},
    @{Id="machibernate";Name="Disable hibernation (Mac)";Desc="Sets hibernatemode 0 so the Mac uses normal sleep instead of writing RAM to disk.";Risk="Caution";Free=$true;Win=$false;Mac=$true;Cat="Power";Action={Invoke-MacPmset -Arguments "-a hibernatemode 0";Off={Invoke-MacPmset -Arguments "-a hibernatemode 3"}}},
    @{Id="macstandby";Name="Disable standby (Mac)";Desc="Stops the deeper standby state after sleep. Faster wake, slightly more standby power.";Risk="Caution";Free=$true;Win=$false;Mac=$true;Cat="Power";Action={Invoke-MacPmset -Arguments "-a standby 0";Off={Invoke-MacPmset -Arguments "-a standby 1"}}},
    @{Id="macdisplaysleep";Name="Disable display sleep (Mac)";Desc="Stops the display from sleeping. Useful for long sessions and benchmarks.";Risk="Safe";Free=$true;Win=$false;Mac=$true;Cat="Power";Action={Invoke-MacPmset -Arguments "-a displaysleep 0";Off={Invoke-MacPmset -Arguments "-a displaysleep 10"}}},
    @{Id="macgpuswitch";Name="Force discrete GPU (Mac)";Desc="Forces the discrete GPU on dual-GPU Intel Macs. More performance, more heat and battery drain.";Risk="Caution";Free=$true;Win=$false;Mac=$true;Cat="Power";Action={Invoke-MacPmset -Arguments "-a gpuswitch 1";Off={Invoke-MacPmset -Arguments "-a gpuswitch 2"}}},
    @{Id="maclowpoweroff";Name="Disable Low Power Mode (Mac)";Desc="Turns off Low Power Mode throttling so clocks stay high.";Risk="Safe";Free=$true;Win=$false;Mac=$true;Cat="Power";Action={Invoke-MacPmset -Arguments "-a lowpowermode 0"}},

    # ---------- v5.3 EXPANSION: macOS VISUAL ----------
    @{Id="macreducemotion";Name="Reduce motion (Mac)";Desc="Turns off parallax, zoom and window motion effects. Less compositor work.";Risk="Safe";Free=$true;Win=$false;Mac=$true;Cat="Visual";Action={Invoke-MacDefaults -Domain "com.apple.universalaccess" -Key "reduceMotion" -Type bool -Value "true";Off={Invoke-MacDefaults -Domain "com.apple.universalaccess" -Key "reduceMotion" -Type bool -Value "false"}}},
    @{Id="macfinderanim";Name="Disable Finder animations (Mac)";Desc="Removes Finder open/close animations. Snappier file browsing.";Risk="Safe";Free=$true;Win=$false;Mac=$true;Cat="Visual";Action={Invoke-MacDefaults -Domain "com.apple.finder" -Key "DisableAllAnimations" -Type bool -Value "true"; Invoke-MacRefresh -Names @("Finder");Off={Invoke-MacDefaults -Domain "com.apple.finder" -Key "DisableAllAnimations" -Type bool -Value "false"; Invoke-MacRefresh -Names @("Finder")}}},
    @{Id="macdockbounce";Name="Disable Dock bounce (Mac)";Desc="Stops app icons from bouncing when launched.";Risk="Safe";Free=$true;Win=$false;Mac=$true;Cat="Visual";Action={Invoke-MacDefaults -Domain "com.apple.dock" -Key "no-bouncing" -Type bool -Value "true"; Invoke-MacRefresh -Names @("Dock");Off={Invoke-MacDefaults -Domain "com.apple.dock" -Key "no-bouncing" -Type bool -Value "false"; Invoke-MacRefresh -Names @("Dock")}}},
    @{Id="macdocklaunch";Name="Disable Dock launch animation (Mac)";Desc="Removes the Dock app-launch animation.";Risk="Safe";Free=$true;Win=$false;Mac=$true;Cat="Visual";Action={Invoke-MacDefaults -Domain "com.apple.dock" -Key "launchanim" -Type bool -Value "false"; Invoke-MacRefresh -Names @("Dock");Off={Invoke-MacDefaults -Domain "com.apple.dock" -Key "launchanim" -Type bool -Value "true"; Invoke-MacRefresh -Names @("Dock")}}},
    @{Id="macdockminimize";Name="Use scale minimize effect (Mac)";Desc="Switches the minimize effect from genie to scale. Less animation work.";Risk="Safe";Free=$true;Win=$false;Mac=$true;Cat="Visual";Action={Invoke-MacDefaults -Domain "com.apple.dock" -Key "mineffect" -Type string -Value "scale"; Invoke-MacRefresh -Names @("Dock");Off={Invoke-MacDefaults -Domain "com.apple.dock" -Key "mineffect" -Type string -Value "genie"; Invoke-MacRefresh -Names @("Dock")}}},
    @{Id="macmissioncontrol";Name="Speed up Mission Control (Mac)";Desc="Shortens the Mission Control animation for an almost instant transition.";Risk="Safe";Free=$true;Win=$false;Mac=$true;Cat="Visual";Action={Invoke-MacDefaults -Domain "com.apple.dock" -Key "expose-animation-duration" -Type float -Value "0.1"; Invoke-MacRefresh -Names @("Dock");Off={Invoke-MacDefaults -Domain "com.apple.dock" -Key "expose-animation-duration" -Type float -Value "0.5"; Invoke-MacRefresh -Names @("Dock")}}},
    @{Id="macdockmagnifyoff";Name="Disable Dock magnification (Mac)";Desc="Turns off Dock icon magnification. Less redraw work as the pointer moves.";Risk="Safe";Free=$true;Win=$false;Mac=$true;Cat="Visual";Action={Invoke-MacDefaults -Domain "com.apple.dock" -Key "magnification" -Type bool -Value "false"; Invoke-MacRefresh -Names @("Dock");Off={Invoke-MacDefaults -Domain "com.apple.dock" -Key "magnification" -Type bool -Value "true"; Invoke-MacRefresh -Names @("Dock")}}},

    # ---------- v5.3 EXPANSION: macOS SERVICES ----------
    @{Id="macappstoreauto";Name="Disable App Store auto-updates (Mac)";Desc="Stops the App Store from downloading and installing updates in the background.";Risk="Caution";Free=$true;Win=$false;Mac=$true;Cat="Services";Action={Invoke-MacDefaultsGroup -Items @(
        @{Domain="com.apple.commerce";Key="AutoUpdate";Type="bool";Value="false"},
        @{Domain="com.apple.SoftwareUpdate";Key="AutomaticDownload";Type="bool";Value="false"}
    )}},
    @{Id="macdashboardoff";Name="Disable Dashboard (Mac)";Desc="Turns off the legacy Dashboard layer and its background widgets.";Risk="Safe";Free=$true;Win=$false;Mac=$true;Cat="Services";Action={Invoke-MacDefaults -Domain "com.apple.dashboard" -Key "mcx-disabled" -Type bool -Value "true"; Invoke-MacRefresh -Names @("Dashboard");Off={Invoke-MacDefaults -Domain "com.apple.dashboard" -Key "mcx-disabled" -Type bool -Value "false"; Invoke-MacRefresh -Names @("Dashboard")}}},

    # ---------- v5.3 EXPANSION: macOS STORAGE ----------
    @{Id="maclocalsnapshots";Name="Disable local Time Machine snapshots (Mac)";Desc="Stops macOS keeping local APFS snapshots for Time Machine. Frees disk space.";Risk="Caution";Free=$true;Win=$false;Mac=$true;Cat="Storage";Action={Invoke-MacRoot -Command "tmutil disablelocal" -Label "Local snapshots disabled.";Off={Invoke-MacRoot -Command "tmutil enablelocal" -Label "Local snapshots enabled."}}},
    @{Id="macquicklookcache";Name="Clear Quick Look cache (Mac)";Desc="Clears the Quick Look thumbnail cache so previews rebuild cleanly.";Risk="Safe";Free=$true;Win=$false;Mac=$true;Cat="Storage";Action={Invoke-MacCleanup -Paths @("$env:HOME/Library/Caches/com.apple.QuickLook.thumbnailcache") -Label "Quick Look cache"}},
    @{Id="maclaunchservices";Name="Rebuild LaunchServices database (Mac)";Desc="Rebuilds the app-launch database. Fixes duplicate Open With entries and stale app associations.";Risk="Caution";Free=$true;Win=$false;Mac=$true;Cat="Storage";Action={Invoke-Cmd -Cmd "/System/Library/Frameworks/CoreServices.framework/Frameworks/LaunchServices.framework/Support/lsregister -kill -r -domain local -domain system -domain user"}},
    @{Id="maclogclear";Name="Clear user logs (Mac)";Desc="Deletes user-level log files. Frees disk space; system logs are untouched.";Risk="Safe";Free=$true;Win=$false;Mac=$true;Cat="Storage";Action={Invoke-MacCleanup -Paths @("$env:HOME/Library/Logs") -Label "User logs"}},
    @{Id="maccacheclear";Name="Clear user caches (Mac)";Desc="Deletes user cache folders. Apps rebuild them; first launches may be slower.";Risk="Caution";Free=$true;Win=$false;Mac=$true;Cat="Storage";Action={Invoke-MacCleanup -Paths @("$env:HOME/Library/Caches") -Label "User caches"}},

    # ---------- v5.3 EXPANSION: macOS FIRMWARE-ADJACENT ----------
    @{Id="macautopoweron";Name="Disable auto power-on after power loss";Desc="Clears the NVRAM AutoBoot flag so the Mac stays off when power returns. Intel Macs only.";Risk="Caution";Free=$true;Win=$false;Mac=$true;Cat="Firmware";Action={Invoke-MacNvram -Setting "AutoBoot" -Value "%00";Off={Invoke-MacRoot -Command "nvram -d AutoBoot" -Label "Auto power-on restored."}}},
    @{Id="macbootchime";Name="Disable boot chime";Desc="Clears the NVRAM BootAudio flag to silence the startup chime. Firmware-level, reversible with nvram -d BootAudio.";Risk="Safe";Free=$true;Win=$false;Mac=$true;Cat="Firmware";Action={Invoke-MacNvram -Setting "BootAudio" -Value "%00";Off={Invoke-MacRoot -Command "nvram -d BootAudio" -Label "Boot chime restored."}}},

    # ---------- v5.3 EXPANSION: macOS PRIVACY ----------
    @{Id="maclocationoff";Name="Disable Location Services (Mac)";Desc="Turns off macOS Location Services. Apps lose location access.";Risk="Caution";Free=$true;Win=$false;Mac=$true;Cat="Privacy";Action={Invoke-MacDefaults -Domain "com.apple.locationd" -Key "LocationServicesEnabled" -Type bool -Value "false"}},
    @{Id="macanalytics";Name="Disable analytics submission (Mac)";Desc="Stops macOS from automatically submitting diagnostic and usage data.";Risk="Safe";Free=$true;Win=$false;Mac=$true;Cat="Privacy";Action={Invoke-MacDefaultsGroup -Items @(
        @{Domain="com.apple.SubmitDiagInfo";Key="AutoSubmit";Type="bool";Value="false"},
        @{Domain="com.apple.SubmitDiagInfo";Key="AutoSubmitVersion";Type="int";Value="0"}
    )}},
    @{Id="macadlib";Name="Disable personalized ads (Mac)";Desc="Turns off Apple's personalized advertising and ad identifier.";Risk="Safe";Free=$true;Win=$false;Mac=$true;Cat="Privacy";Action={Invoke-MacDefaultsGroup -Items @(
        @{Domain="com.apple.AdLib";Key="allowApplePersonalizedAdvertising";Type="bool";Value="false"},
        @{Domain="com.apple.AdLib";Key="allowIdentifierForAdvertising";Type="bool";Value="false"}
    )}},
    @{Id="macspotlightsuggest";Name="Disable Spotlight suggestions (Mac)";Desc="Stops Spotlight from sending search terms to Apple for suggestions.";Risk="Safe";Free=$true;Win=$false;Mac=$true;Cat="Privacy";Action={Invoke-MacDefaults -Domain "com.apple.lookup.shared" -Key "LookupSuggestionsDisabled" -Type bool -Value "true"}},
    @{Id="macrecentoff";Name="Disable recent items (Mac)";Desc="Stops macOS tracking recently used documents and apps.";Risk="Safe";Free=$true;Win=$false;Mac=$true;Cat="Privacy";Action={Invoke-MacDefaults -Domain "NSGlobalDomain" -Key "NSRecentDocumentsLimit" -Type int -Value "0"}},
    @{Id="macsafarisuggest";Name="Disable Safari search suggestions (Mac)";Desc="Stops Safari from sending search terms to Apple and other providers for suggestions.";Risk="Safe";Free=$true;Win=$false;Mac=$true;Cat="Privacy";Action={Invoke-MacDefaultsGroup -Items @(
        @{Domain="com.apple.Safari";Key="SuppressSearchSuggestions";Type="bool";Value="true"},
        @{Domain="com.apple.Safari";Key="UniversalSearchEnabled";Type="bool";Value="false"}
    )}},

    # ---------- v5.3 EXPANSION: macOS GAME ----------
    @{Id="macgamecenter";Name="Disable Game Center (Mac)";Desc="Stops the Game Center daemon from running in the background.";Risk="Safe";Free=$true;Win=$false;Mac=$true;Cat="Game";Action={Invoke-MacDefaults -Domain "com.apple.gamed" -Key "Disabled" -Type bool -Value "true"; Invoke-MacRefresh -Names @("gamed")}},
    # ---------- MINECRAFT (Windows) ----------
    @{Id="mcoptions";Name="Minecraft Performance Preset";Desc="Sets render distance 8, simulation distance 5, 260 FPS cap, VSync off, fast graphics, minimal particles, no entity shadows and no smooth lighting. Original values are saved for restore.";Risk="Safe";Free=$true;Win=$true;Mac=$true;Cat="Game";Game="Minecraft";Action={Invoke-MinecraftPreset};Off={Restore-MinecraftPreset}},
    @{Id="mcmipmap";Name="Minecraft Mipmap Tuning";Desc="Sets mipmap levels to 4, which smooths distant blocks with less shimmer and minimal GPU cost.";Risk="Safe";Free=$true;Win=$true;Mac=$true;Cat="Game";Game="Minecraft";Action={Invoke-MinecraftOptionSet -Key "mipmapLevels" -Value "4"};Off={Invoke-MinecraftOptionRestore -Key "mipmapLevels"}},
    @{Id="mcfullscreen";Name="Minecraft Fullscreen Mode";Desc="Sets Minecraft to launch in true fullscreen, which usually lowers input latency and avoids borderless capture overhead.";Risk="Safe";Free=$true;Win=$true;Mac=$true;Cat="Game";Game="Minecraft";Action={Invoke-MinecraftOptionSet -Key "fullscreen" -Value "true"};Off={Invoke-MinecraftOptionRestore -Key "fullscreen"}},
    @{Id="mcgpu";Name="Minecraft High-Performance GPU";Desc="Adds the Minecraft Java and Store executables to Windows' high-performance GPU preference. Laptops with two GPUs stop picking the integrated one.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Game";Game="Minecraft";Action={Set-MinecraftGpuPreference};Off={Set-MinecraftGpuPreference -Remove}},
    @{Id="mcfsopt";Name="Minecraft Fullscreen Optimizations Off";Desc="Disables Windows fullscreen optimizations for the Minecraft Java executable so the game controls the display path.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Game";Game="Minecraft";Action={Set-MinecraftFullscreenOpt};Off={Set-MinecraftFullscreenOpt -Remove}},
    @{Id="mcpriority";Name="Minecraft High Process Priority";Desc="Raises the priority of the running Minecraft Java or Store process to High. Start Minecraft first, then apply.";Risk="Caution";Free=$true;Win=$true;Mac=$false;Cat="Game";Game="Minecraft";Action={Invoke-MinecraftPriority -Priority "High"};Off={Invoke-MinecraftPriority -Priority "Normal"}},
    @{Id="mccache";Name="Clear Minecraft Logs & Crash Reports";Desc="Deletes old Minecraft logs, crash reports and leftover temporary files. Worlds, resource packs and shader packs are never touched.";Risk="Safe";Free=$true;Win=$true;Mac=$true;Cat="Game";Game="Minecraft";Action={Clear-MinecraftCache}},
    @{Id="mcgamebar";Name="Minecraft Game Bar & Capture Off";Desc="Disables the Xbox Game Bar overlay, background capture and startup panel so nothing records or overlays Minecraft.";Risk="Safe";Free=$true;Win=$true;Mac=$false;Cat="Game";Game="Minecraft";Action={Invoke-MinecraftGameBar};Off={Restore-MinecraftGameBar}},
    @{Id="mcjvm";Name="Minecraft G1GC JVM Arguments";Desc="Writes tuned G1GC JVM arguments into each launcher profile, with heap sized from your installed RAM (2-8 GB). A full launcher_profiles.json backup is kept.";Risk="Caution";Free=$false;Win=$true;Mac=$true;Cat="Game";Game="Minecraft";Action={Invoke-MinecraftJvmArgs};Off={Restore-MinecraftJvmArgs}}
)

if (-not $Script:Config.TweakStates) { $Script:Config.TweakStates = @{} }
$props = $Script:Config.TweakStates.PSObject.Properties.Name
foreach ($t in $Script:Tweaks) { if ($t.Id -notin $props) { $Script:Config.TweakStates | Add-Member -NotePropertyName $t.Id -NotePropertyValue $false -Force } }

# Auto-login
$Script:CurrentUser = Auto-Login
if ($Script:CurrentUser) {
    $Script:CurrentUser = Normalize-NovaAccount $Script:CurrentUser
    $Script:Config.Plan = $Script:CurrentUser.Plan
    $Script:Config.PlanUntil = $Script:CurrentUser.PlanUntil
    $Script:Config.Balance = $Script:CurrentUser.Balance
    $Script:Config.CurrentUser = $Script:CurrentUser.Email
    $Script:Config.Email = $Script:CurrentUser.Email
    Save-Config
    Write-Log "Auto-login: $($Script:CurrentUser.Email) ($($Script:CurrentUser.Plan))" "OK"
} else {
    $Script:Config.Plan = "Free"
}

# ---------- HTML (Vibrant Red Theme) ----------
$HtmlPage = @'
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<script>
(function(){
  if(!(window.chrome&&window.chrome.webview))return;
  var pending={},seq=0;
  var nativeFetch=window.fetch;
  window.fetch=function(input,init){
    var url=typeof input==='string'?input:((input&&input.url)||'');
    if(url.charAt(0)==='/'){
      return new Promise(function(resolve,reject){
        var id=++seq;pending[id]={resolve:resolve,reject:reject};
        var body=(init&&init.body)?init.body:'';
        window.chrome.webview.postMessage(JSON.stringify({id:id,path:url,body:String(body)}));
      });
    }
    return nativeFetch.apply(this,arguments);
  };
  window.chrome.webview.addEventListener('message',function(ev){
    var m=ev.data;
    if(typeof m==='string'){try{m=JSON.parse(m);}catch(e){return;}}
    var p=pending[m.id];if(!p)return;delete pending[m.id];
    p.resolve(new Response(m.body,{status:200,headers:{'Content-Type':'application/json'}}));
  });
})();
</script>
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Nova Tweaks</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;600;700&family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;500&display=swap" rel="stylesheet">
<style>
*{box-sizing:border-box;margin:0;padding:0}
:root{
--bg:#050508;--bg2:#0a0a0f;--sidebar:#0d0d14;--card:#111119;--card2:#181822;--cardhover:#1f1f2e;
--red:#ff1a2e;--red2:#cc0018;--red3:#ff4d5e;--redglow:rgba(255,26,46,.4);--redglow2:rgba(255,26,46,.15);--redglow3:rgba(255,26,46,.05);
--danger:#ff4757;--warn:#ffaa00;--green:#00ff88;--blue:#00aaff;--purple:#aa44ff;
--text:#f5f5fa;--textdim:#8888a0;--textmuted:#55556a;--border:#1e1e2e;--border2:#2e2e42;
--shadow:0 4px 24px rgba(0,0,0,.5);--shadow-lg:0 12px 48px rgba(0,0,0,.7);--shadow-red:0 4px 24px rgba(255,26,46,.3);
--radius:12px;--radius-sm:8px;--radius-xs:4px
}
body{font-family:'Plus Jakarta Sans','Inter',system-ui,sans-serif;background:var(--bg);color:var(--text);display:flex;height:100vh;overflow:hidden;-webkit-font-smoothing:antialiased;letter-spacing:-.01em}

/* Animated background */
body::before{content:'';position:fixed;inset:0;background:radial-gradient(ellipse 80% 50% at 20% 40%,rgba(255,26,46,.06),transparent),radial-gradient(ellipse 60% 40% at 80% 60%,rgba(255,26,46,.04),transparent),radial-gradient(ellipse 50% 30% at 50% 90%,rgba(170,68,255,.03),transparent);pointer-events:none;z-index:0}

/* Login overlay */
.login-overlay{position:fixed;inset:0;background:radial-gradient(ellipse at center,rgba(255,26,46,.12),var(--bg));z-index:10000;display:flex;align-items:center;justify-content:center;backdrop-filter:blur(8px)}
.login-box{background:linear-gradient(145deg,rgba(17,17,25,.95),rgba(24,24,34,.95));border:1px solid rgba(255,26,46,.3);border-radius:20px;padding:48px;width:440px;max-width:92vw;box-shadow:var(--shadow-lg),0 0 80px rgba(255,26,46,.15);position:relative;overflow:hidden;backdrop-filter:blur(20px)}
.login-box::before{content:'';position:absolute;top:0;left:0;right:0;height:3px;background:linear-gradient(90deg,transparent,var(--red),var(--red3),transparent)}
.login-box::after{content:'';position:absolute;inset:0;background:radial-gradient(circle at 50% 0%,rgba(255,26,46,.08),transparent 60%);pointer-events:none}
.login-logo{font-family:"Space Grotesk","Plus Jakarta Sans",sans-serif;font-size:48px;font-weight:900;background:linear-gradient(135deg,var(--red),var(--red3),#ff8a95);-webkit-background-clip:text;-webkit-text-fill-color:transparent;text-align:center;margin-bottom:2px;letter-spacing:-2px;position:relative;z-index:1}
.login-sub{text-align:center;color:var(--textmuted);font-size:11px;text-transform:uppercase;letter-spacing:4px;margin-bottom:32px;position:relative;z-index:1}
.login-tabs{display:flex;gap:4px;margin-bottom:28px;background:rgba(0,0,0,.3);border-radius:10px;padding:4px;position:relative;z-index:1}
.login-tab{flex:1;padding:10px;border:none;background:transparent;color:var(--textdim);border-radius:8px;cursor:pointer;font-size:13px;font-weight:600;transition:all .25s}
.login-tab.active{background:linear-gradient(135deg,var(--red),var(--red2));color:#fff;box-shadow:0 4px 16px var(--redglow)}
.login-field{margin-bottom:18px;position:relative;z-index:1}
.login-field label{display:block;font-size:11px;font-weight:600;color:var(--textdim);margin-bottom:6px;text-transform:uppercase;letter-spacing:1.5px}
.login-input{width:100%;background:rgba(0,0,0,.4);border:1px solid var(--border2);color:var(--text);padding:13px 16px;border-radius:10px;font-size:14px;transition:all .25s;font-family:inherit}
.login-input:focus{outline:none;border-color:var(--red);box-shadow:0 0 0 3px var(--redglow2),0 0 20px var(--redglow3)}
.login-btn{width:100%;background:linear-gradient(135deg,var(--red),var(--red2));color:#fff;border:none;padding:14px;border-radius:10px;font-weight:700;cursor:pointer;font-size:14px;transition:all .25s;box-shadow:0 4px 20px var(--redglow);text-transform:uppercase;letter-spacing:1.5px;position:relative;z-index:1}
.login-btn:hover{transform:translateY(-2px);box-shadow:0 8px 32px var(--redglow);filter:brightness(1.15)}
.login-btn:active{transform:translateY(0)}
.login-error{color:var(--danger);font-size:12px;margin-top:10px;text-align:center;min-height:16px;position:relative;z-index:1}
.login-footer{text-align:center;margin-top:22px;color:var(--textmuted);font-size:11px;position:relative;z-index:1}
.login-footer a{color:var(--red);text-decoration:none;font-weight:600}

/* Sidebar */
.sidebar{width:230px;background:linear-gradient(180deg,var(--sidebar) 0%,#08080e 100%);border-right:1px solid var(--border);padding:20px 12px;display:flex;flex-direction:column;gap:2px;position:relative;overflow:hidden;z-index:1}
.sidebar::before{content:'';position:absolute;top:0;left:0;right:0;height:240px;background:radial-gradient(circle at 50% 0%,var(--redglow2),transparent 70%);pointer-events:none;opacity:.8}
.brand{font-family:"Space Grotesk","Plus Jakarta Sans",sans-serif;font-size:28px;font-weight:900;background:linear-gradient(135deg,var(--red),var(--red3),#ff8a95);-webkit-background-clip:text;-webkit-text-fill-color:transparent;padding:0 8px;position:relative;z-index:1;letter-spacing:-1px}
.brandsub{font-size:10px;color:var(--textmuted);padding:0 8px;margin-bottom:16px;position:relative;z-index:1;text-transform:uppercase;letter-spacing:3px}
.planbadge{display:inline-block;padding:5px 14px;border-radius:20px;font-size:10px;font-weight:800;margin:0 8px 20px;background:linear-gradient(135deg,var(--red),var(--red2));color:#fff;box-shadow:0 2px 12px var(--redglow);position:relative;z-index:1;letter-spacing:1px}
.navbtn{background:transparent;border:none;color:var(--textdim);padding:11px 14px;border-radius:var(--radius-sm);cursor:pointer;font-size:13px;text-align:left;width:100%;transition:all .2s;font-weight:500;position:relative;z-index:1;display:flex;align-items:center;gap:10px}
.navbtn:hover{background:rgba(255,255,255,.04);color:var(--text);transform:translateX(3px)}
.navbtn.active{background:linear-gradient(90deg,rgba(255,26,46,.15),transparent);color:var(--red);border-left:3px solid var(--red);padding-left:11px;font-weight:600}
.navicon{font-size:14px;opacity:.8;width:20px;text-align:center}
.sidebar-bottom{margin-top:auto;padding:12px 8px;border-top:1px solid var(--border);position:relative;z-index:1}
.account-badge{display:flex;align-items:center;gap:10px;padding:10px;background:linear-gradient(135deg,rgba(255,26,46,.08),rgba(255,26,46,.02));border:1px solid rgba(255,26,46,.2);border-radius:10px;margin-bottom:10px}
.account-avatar{width:36px;height:36px;border-radius:50%;background:linear-gradient(135deg,var(--red),var(--red2));display:flex;align-items:center;justify-content:center;font-weight:800;color:#fff;font-size:15px;box-shadow:0 2px 10px var(--redglow)}
.userinfo{font-size:12px;color:var(--text);font-weight:600}
.ptsinfo{font-size:10px;color:var(--textmuted);margin-top:1px}
.progress{height:4px;background:var(--border);border-radius:2px;overflow:hidden;margin-top:8px}
.progress-fill{height:100%;background:linear-gradient(90deg,var(--red),var(--red3),#ff8a95);border-radius:2px;transition:width .6s cubic-bezier(.4,0,.2,1);box-shadow:0 0 8px var(--redglow)}
.logoutbtn{background:transparent;border:1px solid var(--border);color:var(--textdim);padding:7px 12px;border-radius:8px;cursor:pointer;font-size:11px;margin-top:8px;width:100%;transition:all .2s;font-weight:500}
.logoutbtn:hover{border-color:var(--red);color:var(--red);background:rgba(255,26,46,.05)}

/* Content */
.maincol{flex:1;display:flex;flex-direction:column;min-width:0;height:100vh;position:relative}
.topbar{display:flex;align-items:center;gap:4px;padding:9px 16px;background:linear-gradient(180deg,rgba(13,13,20,.98),rgba(9,9,14,.94));border-bottom:1px solid var(--border);position:relative;z-index:3;overflow-x:auto;flex-shrink:0;box-shadow:0 4px 22px rgba(0,0,0,.38)}
.topbar::-webkit-scrollbar{height:4px}
.topbar-label{font-size:9px;text-transform:uppercase;letter-spacing:1.6px;color:var(--textmuted);margin:0 8px 0 4px;font-weight:800;flex-shrink:0}
.topbar .navbtn{width:auto;padding:8px 12px;font-size:12px;border-radius:8px;white-space:nowrap;flex-shrink:0;gap:7px}
.topbar .navbtn:hover{transform:translateY(-1px);background:rgba(255,255,255,.045)}
.topbar .navbtn.active{background:linear-gradient(135deg,rgba(255,26,46,.2),rgba(255,26,46,.06));border-left:none;padding-left:12px;color:var(--red);box-shadow:inset 0 0 0 1px rgba(255,26,46,.35),0 2px 10px rgba(255,26,46,.12)}
.topbar .navicon{width:16px;font-size:13px}
.content{flex:1;overflow-y:auto;padding:28px 32px;background:radial-gradient(ellipse at top right,rgba(255,26,46,.05),transparent 50%);position:relative;z-index:1;min-height:0}
.page{display:none;animation:fadeIn .35s cubic-bezier(.4,0,.2,1)}.page.active{display:block}
@keyframes fadeIn{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}

/* Game profile switch */
.gameswitch{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:10px}
.gamebtn{display:flex;align-items:center;gap:12px;text-align:left;padding:14px;border:1px solid var(--border);border-radius:12px;background:rgba(255,255,255,.02);color:var(--text);cursor:pointer;transition:all .22s;font-family:inherit}
.gamebtn:hover{border-color:rgba(255,26,46,.55);background:rgba(255,26,46,.06);transform:translateY(-1px)}
.gamebtn.active{border-color:var(--red);background:linear-gradient(135deg,rgba(255,26,46,.16),rgba(255,26,46,.03));box-shadow:0 0 22px rgba(255,26,46,.16)}
.gamebtn .gameicon{width:38px;height:38px;border-radius:10px;display:flex;align-items:center;justify-content:center;font-size:20px;background:#0a0a10;border:1px solid var(--border2);flex-shrink:0}
.gamebtn b{display:block;font-size:13.5px}
.gamebtn span{display:block;font-size:11px;color:var(--textdim);margin-top:2px}
.gamebtn.active .gameicon{border-color:rgba(255,26,46,.6);box-shadow:0 0 14px rgba(255,26,46,.25)}

/* Game welcome overlay */
.game-welcome{position:fixed;inset:0;z-index:20000;display:none;align-items:center;justify-content:center;background:radial-gradient(ellipse at center,rgba(255,26,46,.14),rgba(5,5,8,.97) 62%);backdrop-filter:blur(10px);overflow:hidden}
.game-welcome.show{display:flex;animation:gameFade .35s ease both}
.game-welcome.out{animation:gameOut .45s ease both}
.game-welcome::before{content:'';position:absolute;width:150vmax;height:150vmax;background:conic-gradient(from 0deg,transparent 0 78%,rgba(255,26,46,.16) 84%,transparent 90% 100%);animation:gameSweep 2.4s linear infinite;pointer-events:none}
.game-welcome-inner{position:relative;text-align:center;padding:32px;max-width:92vw}
.game-welcome-icon{font-size:72px;line-height:1;filter:drop-shadow(0 0 28px rgba(255,26,46,.45));animation:gamePop .7s cubic-bezier(.2,.9,.25,1.2) both}
.game-welcome-title{font-size:clamp(34px,6vw,66px);font-weight:900;letter-spacing:-2px;margin-top:16px;background:linear-gradient(135deg,#fff,var(--red3),var(--red));-webkit-background-clip:text;-webkit-text-fill-color:transparent;animation:gameRise .7s .15s cubic-bezier(.2,.8,.2,1) both}
.game-welcome-sub{font-size:12px;text-transform:uppercase;letter-spacing:5px;color:var(--textdim);margin-top:12px;animation:gameRise .7s .3s cubic-bezier(.2,.8,.2,1) both}
.game-welcome-bar{width:min(320px,70vw);height:4px;border-radius:4px;background:rgba(255,255,255,.08);margin:28px auto 0;overflow:hidden}
.game-welcome-bar i{display:block;height:100%;width:0;background:linear-gradient(90deg,var(--red),var(--red3),#ff8a95);box-shadow:0 0 16px rgba(255,26,46,.6);animation:gameLoad 2.4s .2s cubic-bezier(.3,.1,.2,1) both}
@keyframes gameFade{from{opacity:0}to{opacity:1}}
@keyframes gameOut{from{opacity:1}to{opacity:0}}
@keyframes gameSweep{to{transform:rotate(360deg)}}
@keyframes gamePop{from{opacity:0;transform:scale(.5) rotate(-12deg)}to{opacity:1;transform:scale(1) rotate(0)}}
@keyframes gameRise{from{opacity:0;transform:translateY(18px)}to{opacity:1;transform:translateY(0)}}
@keyframes gameLoad{0%{width:0}55%{width:62%}100%{width:100%}}
@media (max-width:720px){.gameswitch{grid-template-columns:1fr}}
h1{font-family:"Space Grotesk","Plus Jakarta Sans",sans-serif;font-size:30px;font-weight:800;margin-bottom:4px;letter-spacing:-.8px}
.sub{color:var(--textdim);font-size:13.5px;margin-bottom:24px;line-height:1.5}

/* Cards */
.card{background:linear-gradient(145deg,rgba(17,17,25,.8),rgba(24,24,34,.8));border:1px solid var(--border);border-radius:var(--radius);padding:20px;margin-bottom:14px;box-shadow:var(--shadow);transition:all .3s cubic-bezier(.4,0,.2,1);backdrop-filter:blur(10px)}
.card:hover{transform:translateY(-3px);box-shadow:var(--shadow-lg);border-color:var(--border2)}
.cardrow{display:flex;gap:14px;flex-wrap:wrap}
.statcard{flex:1;min-width:130px;background:linear-gradient(145deg,rgba(17,17,25,.8),rgba(24,24,34,.8));border:1px solid var(--border);border-radius:var(--radius);padding:18px;position:relative;overflow:hidden;box-shadow:var(--shadow);transition:all .3s}
.statcard::before{content:'';position:absolute;top:0;left:0;right:0;height:2px;background:linear-gradient(90deg,var(--red),transparent)}
.statcard:hover{transform:translateY(-2px);box-shadow:var(--shadow-lg)}
.statlabel{font-size:10px;color:var(--textmuted);text-transform:uppercase;letter-spacing:1.5px;font-weight:700}
.statval{font-size:34px;font-weight:900;margin-top:6px;background:linear-gradient(135deg,var(--text),var(--textdim));-webkit-background-clip:text;-webkit-text-fill-color:transparent}

/* Tweak cards */
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(350px,1fr));gap:12px}
.tweakcard{background:linear-gradient(145deg,rgba(17,17,25,.7),rgba(24,24,34,.7));border:1px solid var(--border);border-radius:var(--radius);padding:16px;transition:all .3s cubic-bezier(.4,0,.2,1);position:relative;overflow:hidden;backdrop-filter:blur(8px)}
.tweakcard:hover{border-color:rgba(255,26,46,.3);transform:translateY(-4px);box-shadow:0 12px 40px rgba(0,0,0,.6),0 0 20px rgba(255,26,46,.08)}
.tweakcard::after{content:'';position:absolute;inset:0;background:radial-gradient(circle at 0% 0%,rgba(255,26,46,.06),transparent 50%);pointer-events:none;opacity:0;transition:opacity .3s}
.tweakcard:hover::after{opacity:1}
.tweakhead{display:flex;align-items:center;gap:6px;margin-bottom:8px;flex-wrap:wrap}
.badge{padding:3px 9px;border-radius:5px;font-size:9px;font-weight:800;letter-spacing:.5px;text-transform:uppercase}
.badge.safe{background:linear-gradient(135deg,var(--green),#00cc6a);color:#000;box-shadow:0 2px 8px rgba(0,255,136,.25)}
.badge.caution{background:linear-gradient(135deg,var(--warn),#cc8400);color:#000;box-shadow:0 2px 8px rgba(255,170,0,.25)}
.badge.danger{background:linear-gradient(135deg,var(--danger),#cc2f3a);color:#fff;box-shadow:0 2px 8px rgba(255,71,87,.25)}
.badge.free{background:rgba(255,26,46,.1);color:var(--red);border:1px solid rgba(255,26,46,.3)}
.badge.pro{background:rgba(255,170,0,.1);color:var(--warn);border:1px solid rgba(255,170,0,.3)}
.badge.new{background:linear-gradient(135deg,var(--blue),#0088cc);color:#fff;box-shadow:0 2px 8px rgba(0,170,255,.25)}
.tweakname{font-size:14.5px;font-weight:700;margin-bottom:4px;letter-spacing:-.2px}
.tweakdesc{font-size:12px;color:var(--textdim);line-height:1.55}

/* Toggle */
.toggle{margin-left:auto;position:relative;width:48px;height:26px;cursor:pointer;flex-shrink:0}
.toggle input{opacity:0;width:0;height:0;position:absolute}
.slider{position:absolute;inset:0;background:linear-gradient(180deg,#2a2a38,#1a1a28);border:1px solid var(--border2);border-radius:26px;transition:all .35s cubic-bezier(.4,0,.2,1);box-shadow:inset 0 2px 4px rgba(0,0,0,.4)}
.slider:before{content:"";position:absolute;width:20px;height:20px;left:2px;top:2px;background:linear-gradient(145deg,#fff,#d8d8e0);border-radius:50%;transition:all .35s cubic-bezier(.4,0,.2,1);box-shadow:0 2px 8px rgba(0,0,0,.5)}
.toggle input:checked+.slider{background:linear-gradient(135deg,var(--red),var(--red2));border-color:var(--red);box-shadow:0 0 16px var(--redglow),inset 0 1px 2px rgba(255,255,255,.2)}
.toggle input:checked+.slider:before{transform:translateX(22px);background:#fff;box-shadow:0 2px 8px rgba(0,0,0,.3)}
.toggle input:disabled+.slider{opacity:.35;cursor:not-allowed}

/* Buttons */
.btn{background:linear-gradient(135deg,var(--red),var(--red2));color:#fff;border:none;padding:12px 24px;border-radius:var(--radius-sm);font-weight:700;cursor:pointer;font-size:13px;transition:all .25s cubic-bezier(.4,0,.2,1);box-shadow:0 4px 16px var(--redglow),inset 0 1px 0 rgba(255,255,255,.2);text-transform:uppercase;letter-spacing:.8px;position:relative;overflow:hidden}
.btn::before{content:'';position:absolute;inset:0;background:linear-gradient(135deg,rgba(255,255,255,.15),transparent);opacity:0;transition:opacity .25s}
.btn:hover{transform:translateY(-3px);box-shadow:0 8px 32px var(--redglow),inset 0 1px 0 rgba(255,255,255,.3);filter:brightness(1.1)}
.btn:hover::before{opacity:1}
.btn:active{transform:translateY(-1px)}
.btn.danger{background:linear-gradient(135deg,var(--danger),#cc2f3a);box-shadow:0 4px 16px rgba(255,71,87,.3)}
.btn.danger:hover{box-shadow:0 8px 32px rgba(255,71,87,.4)}
.btn.ghost{background:linear-gradient(145deg,rgba(17,17,25,.6),rgba(24,24,34,.6));border:1px solid var(--border2);color:var(--text);box-shadow:var(--shadow)}
.btn.ghost:hover{border-color:var(--red);color:var(--red);box-shadow:0 4px 16px rgba(0,0,0,.3)}
.btn.sm{padding:8px 18px;font-size:11.5px}
.btn.xs{padding:5px 12px;font-size:10.5px}
.btn.full{width:100%}

/* Inputs */
.input{background:rgba(0,0,0,.4);border:1px solid var(--border);color:var(--text);padding:11px 15px;border-radius:var(--radius-sm);font-size:13px;width:100%;transition:all .25s;font-family:inherit}
.input:focus{outline:none;border-color:var(--red);box-shadow:0 0 0 3px var(--redglow2),0 0 16px var(--redglow3)}
.textarea{background:rgba(0,0,0,.4);border:1px solid var(--border);color:var(--text);padding:11px 15px;border-radius:var(--radius-sm);font-size:12px;font-family:'JetBrains Mono',monospace;width:100%;min-height:120px;resize:vertical;transition:all .25s;line-height:1.6}
.textarea:focus{outline:none;border-color:var(--red);box-shadow:0 0 0 3px var(--redglow2)}

/* Category bar */
.catbar{display:flex;gap:6px;margin-bottom:18px;flex-wrap:wrap}
.catbtn{background:linear-gradient(145deg,rgba(17,17,25,.6),rgba(24,24,34,.6));border:1px solid var(--border);color:var(--textdim);padding:9px 20px;border-radius:24px;cursor:pointer;font-size:12px;font-weight:600;transition:all .25s}
.catbtn:hover{color:var(--text);border-color:var(--border2);transform:translateY(-2px)}
.catbtn.active{background:linear-gradient(135deg,var(--red),var(--red2));color:#fff;border-color:var(--red);font-weight:700;box-shadow:0 4px 16px var(--redglow)}

/* Log */
.logbox{background:#030306;border:1px solid var(--border);border-radius:var(--radius);padding:16px;font-family:'JetBrains Mono',monospace;font-size:12px;color:#ff6b7a;height:440px;overflow-y:auto;white-space:pre-wrap;box-shadow:inset 0 2px 12px rgba(0,0,0,.6);line-height:1.7}

/* Toast */
.toast{position:fixed;bottom:28px;right:28px;background:linear-gradient(135deg,rgba(17,17,25,.95),rgba(24,24,34,.95));border:1px solid var(--red);padding:16px 24px;border-radius:var(--radius);font-size:13px;opacity:0;transform:translateY(24px) scale(.95);transition:all .35s cubic-bezier(.4,0,.2,1);pointer-events:none;box-shadow:0 12px 40px rgba(0,0,0,.6),0 0 20px var(--redglow2);z-index:1000;font-weight:600;backdrop-filter:blur(10px)}
.toast.show{opacity:1;transform:translateY(0) scale(1)}

/* Warn box */
.warnbox{background:linear-gradient(135deg,rgba(255,170,0,.08),rgba(255,170,0,.02));border:1px solid rgba(255,170,0,.35);border-radius:var(--radius);padding:14px 18px;font-size:12.5px;color:var(--warn);margin-bottom:16px;box-shadow:0 2px 12px rgba(255,170,0,.08)}

/* Profile cards */
.profilecard{background:linear-gradient(145deg,rgba(17,17,25,.7),rgba(24,24,34,.7));border:1px solid var(--border);border-radius:var(--radius);padding:18px;display:flex;align-items:center;gap:16px;margin-bottom:10px;transition:all .3s cubic-bezier(.4,0,.2,1);backdrop-filter:blur(8px)}
.profilecard:hover{border-color:rgba(255,26,46,.3);transform:translateX(6px);box-shadow:0 8px 30px rgba(0,0,0,.5)}
.profileicon{width:48px;height:48px;border-radius:10px;background:linear-gradient(135deg,var(--red),var(--red2));display:flex;align-items:center;justify-content:center;font-weight:900;color:#fff;font-size:15px;box-shadow:0 4px 14px var(--redglow);flex-shrink:0}

/* BIOS / UEFI + Drag Macro */
.biosgrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:10px}
.biositem{background:rgba(0,0,0,.32);border:1px solid var(--border);border-radius:10px;padding:12px 14px;transition:all .25s}
.biositem:hover{border-color:var(--border2);transform:translateY(-2px)}
.bioskey{font-size:9px;color:var(--textmuted);text-transform:uppercase;letter-spacing:1.2px;font-weight:800;margin-bottom:5px}
.biosval{font-size:12.5px;color:var(--text);line-height:1.55;word-break:break-word}
.macrow{display:flex;gap:14px;flex-wrap:wrap}
.macrow .card{flex:1;min-width:280px}
.macropt{display:flex;align-items:center;gap:10px;background:rgba(0,0,0,.32);border:1px solid var(--border);border-radius:10px;padding:12px 14px;margin-bottom:10px}
.macropt .dot{width:10px;height:10px;border-radius:50%;background:var(--red);box-shadow:0 0 10px var(--redglow)}
.macropt .coords{font-family:'JetBrains Mono',monospace;font-size:13px;color:var(--text)}
.macropt .lbl{font-size:9px;text-transform:uppercase;letter-spacing:1.2px;color:var(--textmuted);font-weight:800}
.macrostatus{font-family:'JetBrains Mono',monospace;font-size:12px;color:var(--textdim);background:rgba(0,0,0,.32);border:1px solid var(--border);border-radius:8px;padding:10px 12px;margin-top:12px}
.slider-row{display:flex;align-items:center;gap:12px;margin:10px 0}
.slider-row input[type=range]{flex:1;accent-color:var(--red)}
.slider-row .val{font-family:'JetBrains Mono',monospace;font-size:12px;color:var(--red);min-width:78px;text-align:right}

/* Scrollbar */
::-webkit-scrollbar{width:8px;height:8px}
::-webkit-scrollbar-track{background:var(--bg)}
::-webkit-scrollbar-thumb{background:var(--border2);border-radius:4px}
::-webkit-scrollbar-thumb:hover{background:var(--textmuted)}

/* Live tool cards */
.livetool{background:linear-gradient(145deg,rgba(17,17,25,.8),rgba(24,24,34,.8));border:1px solid var(--border);border-radius:var(--radius);padding:20px;margin-bottom:14px;position:relative;overflow:hidden}
.livetool::before{content:'';position:absolute;top:0;left:0;right:0;height:2px;background:linear-gradient(90deg,var(--red),var(--purple),var(--blue))}
.livetool-header{display:flex;align-items:center;gap:12px;margin-bottom:14px}
.livetool-icon{width:40px;height:40px;border-radius:10px;background:linear-gradient(135deg,var(--red),var(--red2));display:flex;align-items:center;justify-content:center;font-size:18px;box-shadow:0 4px 12px var(--redglow)}
.livetool-title{font-size:16px;font-weight:700}
.livetool-desc{font-size:12px;color:var(--textdim);margin-bottom:14px;line-height:1.5}
.livetool-stats{display:flex;gap:16px;margin-bottom:14px}
.livetool-stat{background:rgba(0,0,0,.3);border:1px solid var(--border);border-radius:8px;padding:10px 14px;flex:1;text-align:center}
.livetool-stat-val{font-size:20px;font-weight:800;background:linear-gradient(135deg,var(--red),var(--red3));-webkit-background-clip:text;-webkit-text-fill-color:transparent}
.livetool-stat-label{font-size:9px;color:var(--textmuted);text-transform:uppercase;letter-spacing:1px;margin-top:2px;font-weight:600}

/* Pulse */
@keyframes pulse{0%,100%{opacity:1;transform:scale(1)}50%{opacity:.6;transform:scale(1.05)}}
.live-dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--green);box-shadow:0 0 8px var(--green);animation:pulse 2s infinite;margin-right:6px}

/* Section divider */
.section-title{font-size:18px;font-weight:700;margin:24px 0 12px;color:var(--text);display:flex;align-items:center;gap:10px}
.section-title::after{content:'';flex:1;height:1px;background:linear-gradient(90deg,var(--border),transparent)}

/* OS badges */
.badge.os-windows{background:linear-gradient(135deg,var(--blue),#0088cc);color:#fff;box-shadow:0 2px 8px rgba(0,170,255,.25)}
.badge.os-mac{background:linear-gradient(135deg,var(--purple),#8833cc);color:#fff;box-shadow:0 2px 8px rgba(170,68,255,.25)}
.badge.os-both{background:linear-gradient(135deg,var(--green),#00cc6a);color:#000;box-shadow:0 2px 8px rgba(0,255,136,.25)}
.badge.unavailable{background:rgba(255,255,255,.06);color:var(--textmuted);border:1px solid rgba(255,255,255,.14)}
.planbadge.free{background:linear-gradient(135deg,#2b2b3a,#3d3d52);box-shadow:0 2px 12px rgba(0,0,0,.4)}
.planbadge.pro{background:linear-gradient(135deg,var(--red),var(--red2));box-shadow:0 2px 12px var(--redglow)}
.planbadge.ultimate{background:linear-gradient(135deg,#ffc233,#ff7a00);color:#1c1300;box-shadow:0 2px 14px rgba(255,160,0,.35)}
.badge.tier{background:rgba(255,255,255,.05);color:var(--textdim);border:1px solid rgba(255,255,255,.12)}
.badge.tier-free{background:rgba(120,140,180,.12);color:#9fb3d6;border:1px solid rgba(120,140,180,.3)}
.badge.tier-pro{background:rgba(255,26,46,.1);color:var(--red3);border:1px solid rgba(255,26,46,.32)}
.badge.tier-ult{background:rgba(255,170,0,.11);color:var(--warn);border:1px solid rgba(255,170,0,.32)}
.tweakcard.locked{opacity:.66;border-style:dashed}
.tweakcard.locked:hover{transform:none;box-shadow:0 8px 30px rgba(0,0,0,.45)}
.tweakcard.locked .toggle{pointer-events:none;opacity:.5}
.acctgrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:14px}
.acctcard{background:linear-gradient(145deg,rgba(17,17,25,.85),rgba(24,24,34,.85));border:1px solid var(--border);border-radius:var(--radius);padding:18px}
.acctlabel{font-size:10px;text-transform:uppercase;letter-spacing:1.4px;color:var(--textmuted);font-weight:800;margin-bottom:8px}
.acctvalue{font-size:28px;font-weight:900;letter-spacing:-.04em;line-height:1.1}
.acctsub{font-size:11.5px;color:var(--textdim);margin-top:5px;line-height:1.6}
.acctinput{width:100%;background:#0a0a10;border:1px solid var(--border);border-radius:9px;color:var(--text);padding:11px 12px;font-size:12.5px;font-family:inherit;margin-bottom:8px}
.acctinput::placeholder{color:var(--textmuted)}
.acctactions{display:flex;gap:8px;flex-wrap:wrap}
.tierlist{display:grid;gap:10px;margin-top:4px}
.tierrow{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:11px 13px;border:1px solid var(--border);border-radius:10px;background:rgba(255,255,255,.02);font-size:12.5px}
.tierrow b{font-size:13px}

/* Vibrant red outline */
.rotating-outline{position:relative;overflow:visible}
.rotating-outline::before{content:'';position:absolute;inset:-2px;border-radius:inherit;padding:2px;background:conic-gradient(from var(--rot,0deg),#ff1a2e 0deg,#ff4d5e 55deg,#ff8a95 105deg,#cc0018 170deg,#ff1a2e 225deg,#ff5a68 290deg,#ff1a2e 360deg);-webkit-mask:linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);-webkit-mask-composite:xor;mask-composite:exclude;animation:spinOutline 3.4s linear infinite;pointer-events:none;z-index:0;filter:drop-shadow(0 0 5px rgba(255,26,46,.55)) drop-shadow(0 0 14px rgba(255,26,46,.22))}
@keyframes spinOutline{to{--rot:360deg}}
@property --rot{syntax:'<angle>';initial-value:0deg;inherits:false}
.tweakcard.rotating-outline{box-shadow:0 0 0 1px rgba(255,26,46,.12),0 8px 30px rgba(0,0,0,.45),0 0 22px rgba(255,26,46,.08)}
.tweakcard.rotating-outline:hover{box-shadow:0 12px 40px rgba(0,0,0,.6),0 0 28px rgba(255,26,46,.16)}
.tweakcard.rotating-outline::before{border-radius:var(--radius)}

/* Snow canvas */
#snowCanvas{position:fixed;inset:0;pointer-events:none;z-index:0;opacity:.5}

/* Workspace + live network rail */
.workspace{flex:1;display:flex;min-height:0;min-width:0}
.workspace .content{flex:1;min-width:0}
.netrail{width:252px;flex-shrink:0;border-left:1px solid var(--border);background:linear-gradient(180deg,rgba(13,13,20,.98),rgba(8,8,12,.98));padding:14px 14px 18px;overflow-y:auto;position:relative;z-index:2}
.netrail.hidden{display:none}
.netrail-head{display:flex;align-items:center;justify-content:space-between;font-size:12px;font-weight:800;letter-spacing:.3px;margin-bottom:12px}
.netrail-head .live-dot{margin-right:6px}
.netclose{background:transparent;border:1px solid var(--border);color:var(--textmuted);border-radius:6px;width:22px;height:22px;cursor:pointer;line-height:1;font-size:14px}
.netclose:hover{border-color:var(--red);color:var(--red)}
.netmetrics{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:12px}
.netmetric{background:rgba(0,0,0,.34);border:1px solid var(--border);border-radius:9px;padding:9px 10px}
.netmetric-v{font-size:17px;font-weight:900;font-family:'JetBrains Mono',monospace;letter-spacing:-.5px}
.netmetric-l{font-size:8.5px;text-transform:uppercase;letter-spacing:1px;color:var(--textmuted);font-weight:800;margin-top:2px}
.netmetric.wide{grid-column:span 2}
#netChart,#netChartBig{width:100%;display:block;border:1px solid var(--border);border-radius:9px;background:rgba(0,0,0,.3)}
.netrail-foot{display:flex;justify-content:space-between;gap:8px;font-size:9.5px;color:var(--textmuted);margin-top:7px;font-family:'JetBrains Mono',monospace}
.netrail-reopen{display:block!important;position:absolute;right:0;top:58px;z-index:4;background:linear-gradient(135deg,var(--red),var(--red2));border:none;color:#fff;border-radius:8px 0 0 8px;padding:10px 8px;cursor:pointer;box-shadow:0 4px 16px var(--redglow)}
.netrail-reopen.hidden{display:none!important}
@media (max-width:1180px){.netrail{display:none;position:absolute;right:0;top:0;bottom:0;z-index:20;box-shadow:-18px 0 40px rgba(0,0,0,.55)}.netrail.open{display:block}.netrail-reopen{display:block!important}}

/* Badges */
.badgegrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:8px}
.achievement{display:flex;align-items:center;gap:9px;padding:9px 10px;border:1px solid var(--border);border-radius:9px;background:rgba(0,0,0,.26);transition:all .2s}
.achievement:hover{border-color:var(--border2);transform:translateY(-1px)}
.achievement.locked{opacity:.4;filter:grayscale(1)}
.achievement.earned{border-color:rgba(255,26,46,.28);background:linear-gradient(135deg,rgba(255,26,46,.09),rgba(0,0,0,.22))}
.achicon{font-size:20px;line-height:1}
.achname{font-size:11.5px;font-weight:700;line-height:1.2}
.achdesc{font-size:9.5px;color:var(--textmuted);margin-top:2px;line-height:1.3}
.tweakgrid{display:block}
.subgroup{margin-bottom:4px}
.subgroup .grid{margin-top:8px}
.subcount{font-size:10px;color:var(--textmuted);font-weight:600;letter-spacing:0}
.fpslist{color:var(--textdim);font-size:12.5px;line-height:1.9}
.fpslist b{color:var(--text)}

/* Draggable hint */
.draggable{cursor:move}
</style>
</head>
<body>
<canvas id="snowCanvas"></canvas>

<!-- LOGIN OVERLAY -->
<div class="login-overlay" id="loginOverlay">
  <div class="login-box" style="width:520px;padding:0;overflow:hidden">
    <div style="padding:40px 44px 28px;background:linear-gradient(180deg,rgba(255,26,46,.12),transparent);position:relative">
      <div class="login-logo" style="font-size:56px">Nova Tweaks</div>
      <div class="login-sub" style="letter-spacing:6px">Performance Suite</div>
      <div style="display:flex;gap:18px;justify-content:center;margin-top:14px;flex-wrap:wrap">
        <div style="text-align:center"><div id="onlineCount" style="font-size:22px;font-weight:900;color:var(--text)">1</div><div style="font-size:9px;color:var(--textmuted);text-transform:uppercase;letter-spacing:1px">Local Sessions</div></div>
        <div style="text-align:center"><div id="tweakStat" style="font-size:22px;font-weight:900;color:var(--text)">@@TWEAK_COUNT@@</div><div style="font-size:9px;color:var(--textmuted);text-transform:uppercase;letter-spacing:1px">Tweaks</div></div>
        <div style="text-align:center"><div id="catStat" style="font-size:22px;font-weight:900;color:var(--text)">@@CAT_COUNT@@</div><div style="font-size:9px;color:var(--textmuted);text-transform:uppercase;letter-spacing:1px">Categories</div></div>
      </div>
    </div>
    <div style="padding:28px 44px 40px">
      <div class="login-tabs">
        <button class="login-tab active" data-tab="login">Sign In</button>
        <button class="login-tab" data-tab="register">Create Account</button>
      </div>
      <div id="loginForm">
        <div class="login-field"><label>Email</label><input class="login-input" id="loginEmail" type="email" placeholder="you@example.com"></div>
        <div class="login-field"><label>Password</label><input class="login-input" id="loginPass" type="password" placeholder="••••••••"></div>
        <button class="login-btn" id="loginBtn">Sign In</button>
        <div class="login-error" id="loginError"></div>
        <div id="loginStatus" style="font-size:10px;color:var(--textmuted);text-align:center;margin-top:6px"></div>
      </div>
      <div id="registerForm" style="display:none">
        <div class="login-field"><label>Name</label><input class="login-input" id="regName" placeholder="Your name"></div>
        <div class="login-field"><label>Email</label><input class="login-input" id="regEmail" type="email" placeholder="you@example.com"></div>
        <div class="login-field"><label>Password</label><input class="login-input" id="regPass" type="password" placeholder="••••••••"></div>
        <button class="login-btn" id="registerBtn">Create Account</button>
        <div class="login-error" id="registerError"></div>
      </div>
      <div style="margin-top:16px;padding:12px;background:linear-gradient(135deg,rgba(255,26,46,.08),rgba(255,26,46,.02));border:1px solid rgba(255,26,46,.25);border-radius:10px;font-size:11px;color:var(--textdim);line-height:1.7;text-align:center">
        <div style="color:var(--red);font-weight:700;margin-bottom:4px">🔥 Upgrade to Pro or Ultimate</div>
        Exclusive tweaks · Crosshair Overlay · Priority Support · Early Access
      </div>
      <div class="login-footer">Auto-login enabled · Session saved locally · Free plan included</div>
    </div>
  </div>
</div>

<!-- MAIN APP -->
<div id="appContainer" style="display:none;width:100%;height:100vh;position:relative;z-index:1;">
<div class="sidebar">
  <div class="brand" id="brandName">Nova Tweaks</div>
  <div class="brandsub" id="brandSub">Performance Suite</div>
  <div class="planbadge free" id="planBadge">FREE</div>
  <button class="navbtn active" data-page="home"><span class="navicon">◆</span>Home</button>
  <button class="navbtn" data-page="tweaks"><span class="navicon">⚙</span>All Tweaks</button>
  <div style="padding:14px 12px 6px;font-size:9px;text-transform:uppercase;letter-spacing:1.6px;color:var(--textmuted);font-weight:800">Tools</div>
  <div style="padding:0 12px;font-size:11px;color:var(--textmuted);line-height:1.6">Crosshair, Booster, Macro, BIOS and the rest live in the top bar.</div>
  <div class="sidebar-bottom">
    <div class="account-badge" id="accountBadge" style="display:none">
      <div class="account-avatar" id="accountAvatar">G</div>
      <div><div class="userinfo" id="userInfo">Guest</div><div class="ptsinfo" id="ptsInfo">0 tweaks</div></div>
    </div>
    <div class="progress"><div class="progress-fill" id="progressFill" style="width:0%"></div></div>
    <button class="logoutbtn" id="logoutBtn">Sign Out</button>
  </div>
</div>

<div class="maincol">
<div class="topbar">
  <span class="topbar-label">Tools</span>
  <button class="navbtn" data-page="crosshair"><span class="navicon">🎯</span>Crosshair</button>
  <button class="navbtn" data-page="booster"><span class="navicon">⚡</span>Game Booster</button>
  <button class="navbtn" data-page="fps"><span class="navicon">🚀</span>FPS Booster</button>
  <button class="navbtn" data-page="network"><span class="navicon">📡</span>Ping Optimizer</button>
  <button class="navbtn" data-page="potato"><span class="navicon">🥔</span>Potato Graphics</button>
  <button class="navbtn" data-page="macro"><span class="navicon">🖱</span>Drag Macro</button>
  <button class="navbtn" data-page="bios"><span class="navicon">🧬</span>BIOS / UEFI</button>
  <button class="navbtn" data-page="bench"><span class="navicon">📊</span>Benchmark</button>
  <button class="navbtn" data-page="restore"><span class="navicon">↺</span>Restore</button>
  <button class="navbtn" data-page="log"><span class="navicon">☰</span>Log</button>
  <button class="navbtn" data-page="settings"><span class="navicon">✦</span>Settings</button>
</div>

<div class="workspace">
<div class="content">
<!-- HOME -->
<div class="page active" id="page-home">
  <div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px;margin-bottom:6px">
    <div>
      <h1 id="greeting" style="font-size:34px">Good evening</h1>
      <div class="sub" id="homeSub" style="margin-bottom:0">0 tweaks on · Free plan</div>
    </div>
    <div style="display:flex;gap:8px">
      <button class="btn" id="applyAllBtn">⚡ Apply All</button>
      <button class="btn danger" id="revertAllBtn">↺ Revert All</button>
    </div>
  </div>
  <div class="cardrow" id="statsRow" style="margin-top:16px"></div>
  <div class="cardrow" style="margin-top:16px">
    <div class="card" style="flex:2;min-width:300px;position:relative;overflow:hidden">
      <div style="position:absolute;inset:0;background:radial-gradient(circle at 80% 20%,rgba(255,26,46,.15),transparent 60%);pointer-events:none"></div>
      <h3 style="margin-bottom:6px;font-size:16px">Optimization Progress</h3>
      <div id="sugText" style="color:var(--textdim);font-size:13px;margin-bottom:12px">0% optimized</div>
      <div style="height:10px;background:var(--border);border-radius:5px;overflow:hidden">
        <div id="homeProgress" style="height:100%;width:0%;background:linear-gradient(90deg,var(--red),var(--red3),#ff8a95);border-radius:5px;transition:width .6s"></div>
      </div>
      <div style="margin-top:14px;display:flex;gap:8px;flex-wrap:wrap">
        <button class="btn ghost sm" onclick="document.querySelector('[data-page=tweaks]').click()">Browse tweaks</button>
        <button class="btn ghost sm" onclick="document.querySelector('[data-page=crosshair]').click()">Crosshair</button>
        <button class="btn ghost sm" onclick="document.querySelector('[data-page=bench]').click()">Benchmark</button>
      </div>
    </div>
    <div class="card" style="flex:1;min-width:260px">
      <h3 style="margin-bottom:10px;font-size:16px">Quickstart</h3>
      <div style="color:var(--textdim);font-size:13px;line-height:2">
        <div>▸ Create a restore point</div>
        <div>▸ Enable Input Response Accelerator <span style="color:var(--red3)">Pro</span></div>
        <div>▸ Enable Network Spike Smoother <span style="color:var(--red3)">Pro</span></div>
        <div>▸ Turn on Game Booster <span style="color:var(--red3)">Pro</span></div>
        <div>▸ Apply Potato Graphics <span style="color:var(--warn)">Ultimate</span></div>
      </div>
    </div>
  </div>
  <div class="cardrow" style="margin-top:16px">
    <div class="card" style="flex:1;min-width:200px;text-align:center">
      <div style="font-size:32px;font-weight:900;background:linear-gradient(135deg,var(--red),var(--red3));-webkit-background-clip:text;-webkit-text-fill-color:transparent" id="statTweaks">0</div>
      <div style="font-size:11px;color:var(--textmuted);text-transform:uppercase;letter-spacing:1px;margin-top:4px">Tweaks Available</div>
    </div>
    <div class="card" style="flex:1;min-width:200px;text-align:center">
      <div style="font-size:32px;font-weight:900;background:linear-gradient(135deg,var(--green),#00cc6a);-webkit-background-clip:text;-webkit-text-fill-color:transparent" id="statApplied">0</div>
      <div style="font-size:11px;color:var(--textmuted);text-transform:uppercase;letter-spacing:1px;margin-top:4px">Applied</div>
    </div>
