    <div class="netmetric wide"><div class="netmetric-v" id="netLoss">—</div><div class="netmetric-l">Packet loss %</div></div>
  </div>
  <canvas id="netChart" height="92"></canvas>
  <div class="netrail-foot"><span id="netMinMaxSm">min — · max —</span><span id="netTargetSm">1.1.1.1</span></div>
  <div style="margin-top:12px;font-size:10.5px;color:var(--textmuted);line-height:1.7">Live ICMP samples. Jitter is the average change between packets.</div>
  <button class="btn ghost sm full" style="margin-top:10px" id="netOpenPage">Open Ping Optimizer</button>
</div>
</div>
<button class="netrail-reopen hidden" id="netReopen" title="Show network panel">📡</button>
</div>
</div>

<div class="game-welcome" id="gameWelcome">
  <div class="game-welcome-inner">
    <div class="game-welcome-icon" id="gameWelcomeIcon">⛏</div>
    <div class="game-welcome-title" id="gameWelcomeTitle">Welcome to Minecraft Tweaks</div>
    <div class="game-welcome-sub" id="gameWelcomeSub">Loading your new profile</div>
    <div class="game-welcome-bar"><i></i></div>
  </div>
</div>

<div class="toast" id="toast"></div>

<script>
const state={plan:'Free',tweaks:{},os:'unknown',game:'Fortnite',previewWindows:false,user:null,balance:0,planUntil:null,badges:[],streak:0,bestStreak:0,appliedEver:0};
window.onerror=(m,u,l)=>{const e=document.getElementById('loginError');if(e)e.textContent='JS Error: '+m+' (line '+l+')';console.error(m,u,l);};
// Snowfall
(function(){
  const c=document.getElementById('snowCanvas');const ctx=c.getContext('2d');
  let w,h,flakes=[];
  function resize(){w=c.width=window.innerWidth;h=c.height=window.innerHeight}
  window.addEventListener('resize',resize);resize();
  for(let i=0;i<120;i++)flakes.push({x:Math.random()*w,y:Math.random()*h,r:Math.random()*2.5+0.5,vx:(Math.random()-.5)*.4,vy:Math.random()*1.2+.4,o:Math.random()*.6+.3});
  function draw(){ctx.clearRect(0,0,w,h);for(const f of flakes){f.x+=f.vx;f.y+=f.vy;if(f.y>h){f.y=-5;f.x=Math.random()*w}if(f.x>w)f.x=0;if(f.x<0)f.x=w;ctx.beginPath();ctx.arc(f.x,f.y,f.r,0,Math.PI*2);ctx.fillStyle='rgba(255,255,255,'+f.o+')';ctx.fill()}requestAnimationFrame(draw)}
  draw();
})();

// Draggable GUI (move the whole app container by dragging the sidebar brand)
(function(){
  const app=document.getElementById('appContainer');
  let dragging=false,sx=0,sy=0,ox=0,oy=0;
  function onDown(e){
    if(e.target.closest('button,input,textarea,select,a,.toggle'))return;
    const sb=e.target.closest('.sidebar');if(!sb)return;
    dragging=true;sx=e.clientX;sy=e.clientY;
    const r=app.getBoundingClientRect();ox=r.left;oy=r.top;
    app.style.position='fixed';app.style.left=ox+'px';app.style.top=oy+'px';app.style.width=r.width+'px';app.style.height=r.height+'px';
    e.preventDefault();
  }
  function onMove(e){if(!dragging)return;app.style.left=(ox+e.clientX-sx)+'px';app.style.top=(oy+e.clientY-sy)+'px'}
  function onUp(){dragging=false}
  document.addEventListener('mousedown',onDown);document.addEventListener('mousemove',onMove);document.addEventListener('mouseup',onUp);
})();
function showToast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),3000)}

const GAME_PROFILES={
  Fortnite:{brand:'Nova Tweaks',sub:'Fortnite Performance Suite',welcome:'Welcome to Fortnite Tweaks',icon:'🎮',note:'Current profile: Fortnite. Fortnite and shared Windows tweaks are loaded.'},
  Minecraft:{brand:'Minecraft Tweaks',sub:'Minecraft Performance Suite',welcome:'Welcome to Minecraft Tweaks',icon:'⛏',note:'Current profile: Minecraft. Minecraft and shared Windows tweaks are loaded.'}
};
function applyGameBranding(game){
  const key=(game==='Minecraft')?'Minecraft':'Fortnite';
  const p=GAME_PROFILES[key];
  state.game=key;
  const fixed = !!state.fixedGame;
  const brand = fixed ? ('Nova Tweaks ('+key+')') : p.brand;
  const sub = fixed ? (key==='Minecraft' ? 'Minecraft Performance Suite' : 'Fortnite Performance Suite') : p.sub;
  const title = fixed ? ('Nova Tweaks ('+key+')') : p.brand;
  const bn=document.getElementById('brandName'); if(bn) bn.textContent=brand;
  const bs=document.getElementById('brandSub'); if(bs) bs.textContent=sub;
  document.title=title;
  document.querySelectorAll('.gamebtn').forEach(b=>b.classList.toggle('active',b.dataset.game===key));
  const note=document.getElementById('gameNote'); if(note) note.textContent = fixed ? ('This Nova Tweaks app is dedicated to '+key+'.') : p.note;
  const card=document.getElementById('gameSwitchCard'); if(card) card.style.display = fixed ? 'none' : '';
}
async function switchGame(game){
  const key=(game==='Minecraft')?'Minecraft':'Fortnite';
  if(key===state.game) return;
  if(state.fixedGame){ showToast('This app is dedicated to '+state.fixedGame+' tweaks.'); return; }
  const p=GAME_PROFILES[key];
  applyGameBranding(key);
  const w=document.getElementById('gameWelcome');
  const icon=document.getElementById('gameWelcomeIcon');
  const title=document.getElementById('gameWelcomeTitle');
  const sub=document.getElementById('gameWelcomeSub');
  if(icon) icon.textContent=p.icon;
  if(title) title.textContent=p.welcome;
  if(sub) sub.textContent='Loading your '+(key==='Minecraft'?'blocks and':'"Fortnite"')+' tweak profile';
  if(w){
    w.classList.remove('show','out');
    void w.offsetWidth;
    w.classList.add('show');
  }
  try{ await api('/api/game',{game:key}); }catch(e){}
  await new Promise(r=>setTimeout(r,2200));
  try{ currentCat='General'; await loadTweaks(); }catch(e){}
  await new Promise(r=>setTimeout(r,500));
  if(w){ w.classList.add('out'); await new Promise(r=>setTimeout(r,500)); w.classList.remove('show','out'); }
  showToast('Switched to '+key+' Tweaks');
}
document.querySelectorAll('.gamebtn').forEach(b=>b.addEventListener('click',()=>switchGame(b.dataset.game)));
async function api(path,body={}){
  const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});
  return r.json();
}

document.querySelectorAll('.login-tab').forEach(t=>t.addEventListener('click',()=>{
  document.querySelectorAll('.login-tab').forEach(x=>x.classList.remove('active'));
  t.classList.add('active');
  document.getElementById('loginForm').style.display=t.dataset.tab==='login'?'block':'none';
  document.getElementById('registerForm').style.display=t.dataset.tab==='register'?'block':'none';
}));

document.getElementById('loginBtn').addEventListener('click',async()=>{
  const r=await api('/api/login',{email:document.getElementById('loginEmail').value,password:document.getElementById('loginPass').value});
  if(r.success){onLogin(r.account)}else document.getElementById('loginError').textContent=r.message;
});
document.getElementById('registerBtn').addEventListener('click',async()=>{
  const r=await api('/api/register',{name:document.getElementById('regName').value,email:document.getElementById('regEmail').value,password:document.getElementById('regPass').value});
  if(r.success){document.getElementById('registerError').textContent='Account created! Sign in now.';document.getElementById('registerError').style.color='var(--green)'}
  else document.getElementById('registerError').textContent=r.message;
});
document.getElementById('loginPass').addEventListener('keydown',e=>{if(e.key==='Enter')document.getElementById('loginBtn').click()});

function setPlanUI(plan, planUntil, balance){
  const p = plan || 'Free';
  state.plan = p;
  state.balance = Number(balance || 0);
  state.planUntil = planUntil || null;
  const pb = document.getElementById('planBadge');
  if(pb){ pb.textContent = p.toUpperCase(); pb.className = 'planbadge ' + p.toLowerCase(); }
  const ap = document.getElementById('acctPlan'); if(ap) ap.textContent = p;
  const sp = document.getElementById('statPlan'); if(sp) sp.textContent = p.toUpperCase();
  const ae = document.getElementById('acctEmail'); if(ae && state.user) ae.textContent = state.user.Email || '—';
  const ab = document.getElementById('acctBalance'); if(ab) ab.textContent = '$' + (state.balance / 100).toFixed(2);
  const au = document.getElementById('acctPlanUntil');
  if(au){
    if(p === 'Free') au.textContent = 'Free tier — no renewal date.';
    else if(planUntil){ const d = new Date(planUntil); au.textContent = 'Active through ' + d.toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric'}); }
    else au.textContent = '30-day plan.';
  }
  const cs = document.getElementById('chStyle');
  if(cs){
    [...cs.options].forEach(o => { o.disabled = (p === 'Free' && o.value !== 'cross'); });
    if(p === 'Free' && cs.value !== 'cross'){ cs.value = 'cross'; chState.style = 'cross'; }
  }
  updateMacroAvailability();
}

function onLogin(acc){
  try{
  const st=document.getElementById('loginStatus'); if(st) st.textContent='Loading...';
  state.user=acc;
  document.getElementById('loginOverlay').style.display='none';
  document.getElementById('appContainer').style.display='flex';
  document.getElementById('accountBadge').style.display='flex';
  document.getElementById('userInfo').textContent=acc.Name||acc.Email;
  document.getElementById('accountAvatar').textContent=(acc.Name||acc.Email).charAt(0).toUpperCase();
  setPlanUI(acc.Plan, acc.PlanUntil, acc.Balance);
  document.getElementById('keyInput').value=acc.LicenseKey||'';
  if(st) st.textContent='Loading tweaks...';
  loadTweaks().then(()=>{ if(st) st.textContent='Done'; }).catch(e=>{ if(st) st.textContent='Tweak load error: '+e; });
  }catch(e){ const er=document.getElementById('loginError'); if(er) er.textContent='Login error: '+e; console.error(e);}
}

(async function(){const r=await api('/api/autologin');if(r.success){onLogin(r.account)}})();

document.querySelectorAll('.navbtn').forEach(b=>b.addEventListener('click',()=>{
  document.querySelectorAll('.navbtn').forEach(x=>x.classList.remove('active'));
  b.classList.add('active');
  document.querySelectorAll('.page').forEach(p=>p.classList.remove('active'));
  document.getElementById('page-'+b.dataset.page).classList.add('active');
  if(b.dataset.page==='log')refreshLog();
  if(b.dataset.page==='bios')loadBios();
  if(b.dataset.page==='macro')refreshMacroStatus();
  if(b.dataset.page==='settings')renderBadges();
  if(b.dataset.page==='network'){ if(!netAutoTimer) startNetAuto(); }
}));

document.getElementById('logoutBtn').addEventListener('click',async()=>{
  try{await api('/api/logout')}catch(e){}
  if(window.chrome&&window.chrome.webview){window.chrome.webview.postMessage('nova-reload');return;}
  if(window.__novaNative || (window.webkit&&window.webkit.messageHandlers&&window.webkit.messageHandlers.nova)){
    try{if(typeof stopNetAuto==='function')stopNetAuto()}catch(e){}
    try{if(window.state){state.user=null;state.plan='Free';state.planUntil=null;state.balance=0;}}catch(e){}
    const app=document.getElementById('appContainer'); if(app) app.style.display='none';
    const ov=document.getElementById('loginOverlay'); if(ov) ov.style.display='';
    const st=document.getElementById('loginStatus'); if(st) st.textContent='';
    const er=document.getElementById('loginError'); if(er) er.textContent='';
    const pw=document.getElementById('loginPass'); if(pw) pw.value='';
    return;
  }
  location.reload();
});

async function renderStats(){
  let r={};
  try{ r=await api('/api/sysstats',{}); }catch{}
  const pct=v=>(v===null||v===undefined||isNaN(v))?'—':v+'%';
  const stats=[
    {label:'CPU LOAD',value:pct(r.cpu),color:'var(--red)'},
    {label:'MEMORY USED',value:pct(r.ram),color:'var(--warn)'},
    {label:'DISK FREE',value:(r.diskFree==null?'—':r.diskFree+' GB'),color:'var(--green)'},
    {label:'PLATFORM',value:(r.os||'—'),color:'var(--blue)'}
  ];
  document.getElementById('statsRow').innerHTML=stats.map(s=>`<div class="statcard"><div class="statlabel">${s.label}</div><div class="statval" style="background:linear-gradient(135deg,${s.color},var(--textdim));-webkit-background-clip:text;-webkit-text-fill-color:transparent">${s.value}</div></div>`).join('');
}

const cats=['General','Input','Ping Optimizer','Power','Visual','Services','Game','Storage','Firmware','Privacy','Windows'];
let currentCat='General';
function catCount(c){
  const all=Object.values(state.tweaks||{});
  if(c==='Windows') return all.filter(t=>t.os==='Windows'||t.os==='Both').length;
  return all.filter(t=>t.available&&t.cat===c).length;
}
function renderCatBar(){
  document.getElementById('catBar').innerHTML=cats.map(c=>`<button class="catbtn ${c===currentCat?'active':''}" data-cat="${c}">${c}<span style="opacity:.55;margin-left:6px;font-size:10px">${catCount(c)}</span></button>`).join('');
  document.querySelectorAll('.catbtn').forEach(b=>b.addEventListener('click',()=>{currentCat=b.dataset.cat;renderCatBar();renderTweaks()}));
}

function ensurePreviewBanner(on){
  let b=document.getElementById('previewBanner');
  if(!on){ if(b) b.style.display='none'; return; }
  if(!b){
    b=document.createElement('div');
    b.id='previewBanner';
    b.style.cssText='position:sticky;top:0;z-index:50;margin:-4px 0 14px;padding:10px 14px;border:1px solid rgba(255,170,0,.45);background:linear-gradient(135deg,rgba(255,170,0,.14),rgba(255,26,46,.06));border-radius:10px;color:#ffdca8;font-size:12px;line-height:1.5';
    b.innerHTML='<b style="color:#fff">Windows Preview (macOS dev mode)</b> — You’re seeing the Windows UI and tweak availability as Windows users see it. Toggling tweaks is simulated only; no Windows system changes are made on this Mac.';
    const c=document.querySelector('.content'); if(c) c.insertBefore(b,c.firstChild);
  }
  b.style.display='block';
}

async function loadTweaks(){
  const r=await api('/api/tweaks/list');
  state.tweaks=r.tweaks||{};
  state.os=r.os||'unknown';
  state.previewWindows=!!r.previewWindows;
  state.fixedGame=r.fixedGame||null;
  state.appVariant=r.appVariant||null;
  ensurePreviewBanner(state.previewWindows);
  if(r.game) applyGameBranding(r.game);
  else if(state.fixedGame) applyGameBranding(state.fixedGame);
  if(r.plan) setPlanUI(r.plan, r.planUntil, r.balance);
  state.badges=r.badges||[];
  state.streak=r.streak||0;
  state.bestStreak=r.bestStreak||0;
  state.appliedEver=r.appliedEver||0;
  const tsub=document.getElementById('tweakSub');
  if(tsub) tsub.textContent=Object.keys(state.tweaks).length+' working tweaks in the '+state.game+' profile. Every change is reversible.';
  renderCatBar();renderTweaks();updateCounts();updateMacroAvailability();renderBadges();
}
function tweaksFor(cat){
  const all=Object.values(state.tweaks);
  if(cat==='Windows') return all.filter(t=>t.os==='Windows'||t.os==='Both');
  return all.filter(t=>t.available&&t.cat===cat);
}
function tweakCard(t){
  const locked = !!t.locked && !t.state;
  const checked=t.state?'checked':'';
  const disabled=(!t.available||locked)?'disabled':'';
  const riskCls=t.risk.toLowerCase();
  const tier=t.required||'Free';
  const tierCls=tier==='Ultimate'?'ult':tier.toLowerCase();
  const planBadge=`<span class="badge tier tier-${tierCls}">${tier.toUpperCase()}</span>`;
  const availBadge=t.available?'':'<span class="badge unavailable">Not on this PC</span>';
  const lockBadge=locked?'<span class="badge unavailable">🔒 Locked</span>':'';
  const newBadge=t.id==='inputdelay'||t.id==='pingstab'||t.id==='bcdedit'?'<span class="badge new">NEW</span>':'';
  const osCls='os-'+(t.os||'').toLowerCase();
  const osBadge='<span class="badge '+osCls+'">'+(t.os||'')+'</span>';
  return `<div class="tweakcard rotating-outline${locked?' locked':''}" data-tweak="${t.id}">
      <div class="tweakhead">
        <span class="badge ${riskCls}">${t.risk}</span>${osBadge}${availBadge}${planBadge}${lockBadge}${newBadge}
        <label class="toggle"><input type="checkbox" data-id="${t.id}" ${checked} ${disabled}><span class="slider"></span></label>
      </div>
      <div class="tweakname">${t.name}</div>
      <div class="tweakdesc">${t.desc}</div>
    </div>`;
}
function renderTweaks(){
  const grid=document.getElementById('tweakGrid');
  const list=tweaksFor(currentCat);
  const groups=[];
  const bySub={};
  for(const t of list){
    const sub=t.sub||'Other';
    if(!bySub[sub]){bySub[sub]=[];groups.push(sub);}
    bySub[sub].push(t);
  }
  grid.innerHTML=groups.map(sub=>`<div class="subgroup">
      <div style="display:flex;align-items:center;gap:8px;margin:18px 0 2px">
        <h3 style="font-size:13px;margin:0;letter-spacing:.2px">${sub}</h3>
        <span class="subcount">${bySub[sub].length} tweak${bySub[sub].length===1?'':'s'}</span>
        <div style="flex:1;height:1px;background:var(--border)"></div>
      </div>
      <div class="grid">${bySub[sub].map(tweakCard).join('')}</div>
    </div>`).join('');
  grid.querySelectorAll('.tweakcard.locked').forEach(card=>card.addEventListener('click',e=>{
    if(e.target.closest('.toggle'))return;
    const t=state.tweaks[card.dataset.tweak];
    showToast('Locked: '+t.name+' needs '+t.required+'. Open Settings to upgrade.');
  }));
  grid.querySelectorAll('input[type=checkbox]').forEach(cb=>cb.addEventListener('change',async e=>{
    const id=cb.dataset.id;const tw=state.tweaks[id];
    const prev=!!tw.state;
    if(cb.checked&&tw.risk!=='Safe'){if(!confirm(tw.name+'\n\nRisk: '+tw.risk+'\n'+tw.desc+'\n\nApply?')){cb.checked=prev;return}}
    const r=await api('/api/tweak/toggle',{id,state:cb.checked});
    if(r.locked||r.success===false){cb.checked=prev;showToast(r.message||'Locked.');return;}
    tw.state=cb.checked;
    showToast(r.message||(cb.checked?'Applied':'Reverted'));
    updateCounts();
    try{const b=await api('/api/badges');if(b.success){state.badges=b.badges;state.streak=b.streak;state.bestStreak=b.bestStreak;renderBadges();}}catch{}
  }));
}
function updateCounts(){
  const all=Object.values(state.tweaks);
  const applied=all.filter(t=>t.state).length;
  const total=all.length;
  const available=all.filter(t=>t.available).length;
  const unlocked=all.filter(t=>t.available&&!t.locked).length;
  const locked=all.filter(t=>t.available&&t.locked).length;
  const pct=available?Math.min(100,Math.round(applied/available*100)):0;
  document.getElementById('ptsInfo').textContent=applied+' tweaks applied';
  document.getElementById('homeSub').textContent=applied+' of '+unlocked+' unlocked tweaks on · '+state.plan+' plan'+(locked?' · '+locked+' locked':'');
  document.getElementById('sugText').textContent=pct+'% optimized · '+applied+' of '+available+' available on this PC.';
  document.getElementById('progressFill').style.width=pct+'%';
  const hp=document.getElementById('homeProgress'); if(hp) hp.style.width=pct+'%';
  const sa=document.getElementById('statApplied'); if(sa) sa.textContent=applied;
  const st=document.getElementById('statTweaks'); if(st) st.textContent=total;
  const sc=document.getElementById('statCats'); if(sc) sc.textContent=total? (new Set(all.map(t=>t.cat))).size : 10;
}

function badgeCard(b){
  const cls=b.earned?'achievement earned':'achievement locked';
  const when=b.earned&&b.earnedOn?'<div class="achdesc">Earned '+new Date(b.earnedOn).toLocaleDateString()+'</div>':'<div class="achdesc">'+b.desc+'</div>';
  return `<div class="${cls}" title="${b.desc}"><div class="achicon">${b.icon}</div><div><div class="achname">${b.name}</div>${when}</div></div>`;
}
function renderBadges(){
  const badges=state.badges||[];
  const earned=badges.filter(b=>b.earned).length;
  const home=document.getElementById('homeBadges');
  if(home) home.innerHTML=badges.length?badges.map(badgeCard).join(''):'<div style="color:var(--textmuted);font-size:12px">Sign in to start earning badges.</div>';
  const set=document.getElementById('settingsBadges');
  if(set) set.innerHTML=badges.length?badges.map(badgeCard).join(''):'<div style="color:var(--textmuted);font-size:12px">Sign in to start earning badges.</div>';
  const hs=document.getElementById('homeStreak'), hb=document.getElementById('homeBestStreak'), hc=document.getElementById('homeBadgeCount');
  if(hs) hs.textContent=state.streak||0;
  if(hb) hb.textContent=state.bestStreak||0;
  if(hc) hc.textContent=earned;
  const ss=document.getElementById('setStreak'), sb=document.getElementById('setBestStreak'), sc2=document.getElementById('setBadgeCount'), st=document.getElementById('setBadgeTotal');
  if(ss) ss.textContent=state.streak||0;
  if(sb) sb.textContent=state.bestStreak||0;
  if(sc2) sc2.textContent=earned;
  if(st) st.textContent=badges.length;
}

const profiles=[{name:'Fortnite',desc:'DX11 and Performance mode',plan:'Ultimate',icon:'FN'},{name:'Fortnite Competitive',desc:'Fixed floor (lowest settings)',plan:'Ultimate',icon:'FC'},{name:'Marvel Rivals',desc:'Low-graphics competitive profile',plan:'Ultimate',icon:'MR'},{name:'AMD/Intel Potato',desc:'Works on any GPU. Removes texture packs.',plan:'Ultimate',icon:'AI'}];
document.getElementById('profileList').innerHTML=profiles.map(p=>`<div class="profilecard"><div class="profileicon">${p.icon}</div><div style="flex:1"><div style="font-weight:700;font-size:14px">${p.name}</div><div style="font-size:12px;color:var(--textdim);margin-top:2px">${p.desc}</div></div><span class="badge tier tier-ult">${p.plan.toUpperCase()}</span><button class="btn sm" data-profile="${p.name}">Apply</button></div>`).join('');
document.querySelectorAll('[data-profile]').forEach(b=>b.addEventListener('click',async()=>{
  if(state.plan!=='Ultimate'){showToast('Graphics profiles need Ultimate. Open Account to upgrade.');return;}
  if(!confirm('This will change Fortnite graphics (Engine.ini).\nRevert anytime. Continue?'))return;
  const r=await api('/api/potato',{profile:b.dataset.profile});showToast(r.message||(r.locked?r.message:'Applied'));
}));

document.getElementById('boostBtn').addEventListener('click',async()=>{
  const wl=document.getElementById('whitelist').value.split('\n').map(s=>s.trim()).filter(Boolean);
  const r=await api('/api/booster',{whitelist:wl});showToast(r.message);
});

// FPS Booster
document.getElementById('fpsBoostBtn').addEventListener('click',async()=>{
  if(state.plan==='Free'){showToast('FPS Booster needs Pro. Open Settings to upgrade.');return;}
  const btn=document.getElementById('fpsBoostBtn');
  const out=document.getElementById('fpsResult');
  btn.disabled=true;const old=btn.textContent;btn.textContent='Running...';
  out.textContent='Applying real system changes...';
  try{
    const r=await api('/api/fpsbooster',{});
    if(r.locked||r.success===false){out.textContent=r.message||'FPS Booster is locked.';showToast(r.message||'Locked');}
    else{
      out.textContent=r.message||'FPS Booster applied.';
      showToast('FPS Booster applied');
      if(Array.isArray(r.steps)&&r.steps.length){
        document.getElementById('fpsSteps').innerHTML=r.steps.map(s=>'<div>✓ <b>'+escHtml(s)+'</b></div>').join('');
      }
      await loadTweaks();
    }
  }catch(e){out.textContent='FPS Booster failed: '+e;}
  btn.disabled=false;btn.textContent=old;
});

// Live network health (rail + full page)
let netAutoTimer=null;
let netHistory=[];
function netNum(v){return (v===null||v===undefined||isNaN(v))?'—':String(v);}
function netSet(id,val){const el=document.getElementById(id);if(el)el.textContent=val;}
function drawNetChart(id,values){
  const c=document.getElementById(id);if(!c)return;
  const dpr=window.devicePixelRatio||1;
  const w=c.clientWidth||c.offsetWidth||240;
  const h=c.dataset.chartH?parseInt(c.dataset.chartH,10):(parseInt(c.getAttribute('height'),10)||90);
  c.dataset.chartH=h;
  c.width=Math.max(1,Math.round(w*dpr));c.height=Math.round(h*dpr);
  const ctx=c.getContext('2d');ctx.setTransform(1,0,0,1,0,0);ctx.scale(dpr,dpr);ctx.clearRect(0,0,w,h);
  ctx.strokeStyle='rgba(255,255,255,.06)';ctx.lineWidth=1;
  for(let i=1;i<4;i++){const y=(h/4)*i;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke();}
  const pts=values.filter(v=>v!==null&&v!==undefined&&!isNaN(v));
  if(pts.length<2){
    ctx.fillStyle='rgba(255,255,255,.25)';ctx.font='10px Inter,sans-serif';ctx.fillText('Waiting for samples…',10,h/2);
    return;
  }
  const max=Math.max(20,Math.max(...pts))*1.25;
  const step=w/Math.max(1,values.length-1);
  let started=false;
  ctx.beginPath();
  values.forEach((v,i)=>{
    if(v===null||v===undefined||isNaN(v)){started=false;return;}
    const x=i*step,y=h-8-(v/max)*(h-16);
    if(!started){ctx.moveTo(x,y);started=true;}else ctx.lineTo(x,y);
  });
  const grad=ctx.createLinearGradient(0,0,w,0);
  grad.addColorStop(0,'#ff1a2e');grad.addColorStop(1,'#ff8a95');
  ctx.strokeStyle=grad;ctx.lineWidth=2;ctx.lineJoin='round';ctx.stroke();
  const last=pts[pts.length-1];
  const lx=(values.length-1)*step,ly=h-8-(last/max)*(h-16);
  ctx.beginPath();ctx.arc(lx,ly,2.5,0,Math.PI*2);ctx.fillStyle='#ff8a95';ctx.fill();
}
function applyNetStats(r){
  if(!r||r.success===false){
    netSet('netStatus',r&&r.message?r.message:'Ping failed');
    return;
  }
  const avg=netNum(r.avg), jit=netNum(r.jitter), loss=netNum(r.loss);
  netSet('netAvg',avg);netSet('netJitter',jit);netSet('netLoss',loss);
  netSet('netAvgBig',avg);netSet('netJitterBig',jit);netSet('netLossBig',loss);
  netSet('netMinMax','min '+netNum(r.min)+' ms · max '+netNum(r.max)+' ms');
  netSet('netMinMaxSm','min '+netNum(r.min)+' · max '+netNum(r.max));
  netSet('netTargetSm',r.target||'1.1.1.1');
  netSet('netTargetBig',r.target||'1.1.1.1');
  netSet('netStatus','Updated '+new Date().toLocaleTimeString());
  const hist=Array.isArray(r.history)?r.history:[];
  netHistory=hist.map(h=>h.avg);
  if(netHistory.length) drawNetChart('netChart',netHistory);
  if(netHistory.length) drawNetChart('netChartBig',netHistory);
}
async function pingNow(){
  const target=(document.getElementById('netTarget')?.value||'1.1.1.1').trim()||'1.1.1.1';
  if(!netHistory.length) netSet('netStatus','Sampling '+target+'…');
  try{
    const r=await api('/api/net/stats',{target});
    applyNetStats(r);
  }catch(e){ netSet('netStatus','Ping error: '+e); }
}
function startNetAuto(){
  const auto=document.getElementById('netAuto');
  if(auto&&!auto.checked){stopNetAuto();return;}
  stopNetAuto();
  pingNow();
  netAutoTimer=setInterval(pingNow,5000);
}
function stopNetAuto(){if(netAutoTimer){clearInterval(netAutoTimer);netAutoTimer=null;}}
document.getElementById('netPingBtn').addEventListener('click',pingNow);
document.getElementById('netAuto').addEventListener('change',e=>{if(e.target.checked)startNetAuto();else stopNetAuto();});
document.getElementById('netClose').addEventListener('click',()=>{
  document.getElementById('netRail').classList.add('hidden');
  document.getElementById('netRail').classList.remove('open');
  document.getElementById('netReopen').classList.remove('hidden');
  try{localStorage.setItem('nova_netrail','0')}catch{}
});
document.getElementById('netReopen').addEventListener('click',()=>{
  document.getElementById('netRail').classList.remove('hidden');
  document.getElementById('netRail').classList.add('open');
  document.getElementById('netReopen').classList.add('hidden');
  try{localStorage.setItem('nova_netrail','1')}catch{}
  drawNetChart('netChart',netHistory);
});
document.getElementById('netOpenPage').addEventListener('click',()=>{document.querySelector('[data-page=network]').click();});
(function(){
  try{
    const closed = localStorage.getItem('nova_netrail')==='0';
    if(closed || window.innerWidth<=1180){
