// Crosshair overlay
const chState={on:false,style:'cross',color:'#00ff88',size:12,thick:2};
function drawCrosshair(canvas){
  const ctx=canvas.getContext('2d');
  const w=canvas.width=canvas.offsetWidth*devicePixelRatio;
  const h=canvas.height=canvas.offsetHeight*devicePixelRatio;
  ctx.clearRect(0,0,w,h);
  if(!chState.on) return;
  const cx=w/2,cy=h/2,s=chState.size*devicePixelRatio,t=chState.thick*devicePixelRatio;
  ctx.strokeStyle=chState.color;ctx.fillStyle=chState.color;ctx.lineWidth=t;ctx.lineCap='round';
  const st=chState.style;
  if(st==='cross'||st==='crosscircle'){ctx.beginPath();ctx.moveTo(cx-s,cy);ctx.lineTo(cx-s/2,cy);ctx.moveTo(cx+s/2,cy);ctx.lineTo(cx+s,cy);ctx.moveTo(cx,cy-s);ctx.lineTo(cx,cy-s/2);ctx.moveTo(cx,cy+s/2);ctx.lineTo(cx,cy+s);ctx.stroke();}
  if(st==='dot'){ctx.beginPath();ctx.arc(cx,cy,t*2,0,Math.PI*2);ctx.fill();}
  if(st==='circle'||st==='crosscircle'){ctx.beginPath();ctx.arc(cx,cy,s,0,Math.PI*2);ctx.stroke();}
  if(st==='t'){ctx.beginPath();ctx.moveTo(cx-s,cy);ctx.lineTo(cx+s,cy);ctx.moveTo(cx,cy);ctx.lineTo(cx,cy+s);ctx.stroke();}
  if(st==='chevron'){ctx.beginPath();ctx.moveTo(cx-s,cy+s);ctx.lineTo(cx,cy);ctx.lineTo(cx+s,cy+s);ctx.stroke();}
  if(st==='square'){ctx.strokeRect(cx-s,cy-s,s*2,s*2);}
  if(st==='x'){ctx.beginPath();ctx.moveTo(cx-s,cy-s);ctx.lineTo(cx+s,cy+s);ctx.moveTo(cx+s,cy-s);ctx.lineTo(cx-s,cy+s);ctx.stroke();}
}
function chPreviewLoop(){const c=document.getElementById('chPreview');if(c)drawCrosshair(c);requestAnimationFrame(chPreviewLoop)}
chPreviewLoop();
document.getElementById('chStyle').addEventListener('change',e=>{chState.style=e.target.value;});
document.getElementById('chColor').addEventListener('input',e=>{chState.color=e.target.value;});
document.getElementById('chSize').addEventListener('input',e=>{chState.size=+e.target.value;});
document.getElementById('chThick').addEventListener('input',e=>{chState.thick=+e.target.value;});
document.getElementById('chToggle').addEventListener('click',()=>{chState.on=!chState.on;if(chState.on)enableOverlay();else disableOverlay();});
document.getElementById('chHide').addEventListener('click',()=>{chState.on=false;disableOverlay();});

// fullscreen overlay canvas
let overlayCanvas=null;
function enableOverlay(){
  if(overlayCanvas) return;
  overlayCanvas=document.createElement('canvas');
  overlayCanvas.style.cssText='position:fixed;inset:0;width:100vw;height:100vh;pointer-events:none;z-index:99999;';
  document.body.appendChild(overlayCanvas);
  function loop(){if(!chState.on){overlayCanvas.remove();overlayCanvas=null;return;}const c=overlayCanvas;c.width=innerWidth*devicePixelRatio;c.height=innerHeight*devicePixelRatio;const ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);const cx=c.width/2,cy=c.height/2,s=chState.size*devicePixelRatio,t=chState.thick*devicePixelRatio;ctx.strokeStyle=chState.color;ctx.fillStyle=chState.color;ctx.lineWidth=t;ctx.lineCap='round';const st=chState.style;
  if(st==='cross'||st==='crosscircle'){ctx.beginPath();ctx.moveTo(cx-s,cy);ctx.lineTo(cx-s/2,cy);ctx.moveTo(cx+s/2,cy);ctx.lineTo(cx+s,cy);ctx.moveTo(cx,cy-s);ctx.lineTo(cx,cy-s/2);ctx.moveTo(cx,cy+s/2);ctx.lineTo(cx,cy+s);ctx.stroke();}
  if(st==='dot'){ctx.beginPath();ctx.arc(cx,cy,t*2,0,Math.PI*2);ctx.fill();}
  if(st==='circle'||st==='crosscircle'){ctx.beginPath();ctx.arc(cx,cy,s,0,Math.PI*2);ctx.stroke();}
  if(st==='t'){ctx.beginPath();ctx.moveTo(cx-s,cy);ctx.lineTo(cx+s,cy);ctx.moveTo(cx,cy);ctx.lineTo(cx,cy+s);ctx.stroke();}
  if(st==='chevron'){ctx.beginPath();ctx.moveTo(cx-s,cy+s);ctx.lineTo(cx,cy);ctx.lineTo(cx+s,cy+s);ctx.stroke();}
  if(st==='square'){ctx.strokeRect(cx-s,cy-s,s*2,s*2);}
  if(st==='x'){ctx.beginPath();ctx.moveTo(cx-s,cy-s);ctx.lineTo(cx+s,cy+s);ctx.moveTo(cx+s,cy-s);ctx.lineTo(cx-s,cy+s);ctx.stroke();}
  requestAnimationFrame(loop);}
  loop();
}
function disableOverlay(){chState.on=false;if(overlayCanvas){overlayCanvas.remove();overlayCanvas=null;}}

// Drag macro
const macroState={start:null,end:null,running:false};
function macroFmt(p){return p?('X '+p.x+' · Y '+p.y):'Not captured'}
function updateMacroUI(){
  const s=document.getElementById('macroStart'),e=document.getElementById('macroEnd');
  if(s&&!s.textContent.startsWith('Capturing'))s.textContent=macroFmt(macroState.start);
  if(e&&!e.textContent.startsWith('Capturing'))e.textContent=macroFmt(macroState.end);
  document.getElementById('macroDurationVal').textContent=document.getElementById('macroDuration').value+' ms';
  document.getElementById('macroHoldVal').textContent=document.getElementById('macroHold').value+' ms';
}
function updateMacroAvailability(){
  const win=state.os==='Windows';
  const paid=state.plan==='Pro'||state.plan==='Ultimate';
  ['captureStartBtn','captureEndBtn','macroStartBtn','macroStopBtn'].forEach(id=>{const el=document.getElementById(id);if(el)el.disabled=!win||!paid});
  const w=document.getElementById('macroWarn');
  if(w){
    if(!win){ w.style.display='block'; w.textContent='Drag Macro uses the Windows cursor API, so it is disabled on macOS.'; }
    else if(!paid){ w.style.display='block'; w.textContent='Drag Macro is a Pro feature. Open Account and upgrade, or redeem a gift code, to unlock it.'; }
    else { w.style.display='none'; }
  }
}
async function captureMacroPoint(which){
  if(state.os!=='Windows'){showToast('Drag Macro is Windows only');return;}
  let n=3;const el=document.getElementById(which==='start'?'macroStart':'macroEnd');
  el.textContent='Capturing in '+n+'…';
  const iv=setInterval(()=>{n--;if(n>0)el.textContent='Capturing in '+n+'…';},1000);
  setTimeout(async()=>{
    clearInterval(iv);
    const r=await api('/api/macro/capture');
    if(r.success){macroState[which]={x:r.x,y:r.y};showToast(which==='start'?'Start point captured':'End point captured');}
    else showToast(r.message||'Capture failed');
    updateMacroUI();
  },3000);
}
async function refreshMacroStatus(){
  if(state.os!=='Windows')return;
  const r=await api('/api/macro/status');
  if(r.success){
    macroState.running=!!r.running;
    document.getElementById('macroStatus').textContent=(r.status||'Idle')+(r.iteration?' · pass '+r.iteration:'');
  }
}
async function startMacro(){
  if(state.os!=='Windows'){showToast('Drag Macro is Windows only');return;}
  if(!macroState.start||!macroState.end){showToast('Capture a start and end point first');return;}
  const body={start:macroState.start,end:macroState.end,duration:+document.getElementById('macroDuration').value,hold:+document.getElementById('macroHold').value,repeat:+document.getElementById('macroRepeat').value,loop:document.getElementById('macroLoop').checked};
  const r=await api('/api/macro/start',body);
  showToast(r.message);
  refreshMacroStatus();
}
async function stopMacro(){const r=await api('/api/macro/stop');showToast(r.message);refreshMacroStatus();}
document.getElementById('captureStartBtn').addEventListener('click',()=>captureMacroPoint('start'));
document.getElementById('captureEndBtn').addEventListener('click',()=>captureMacroPoint('end'));
document.getElementById('macroDuration').addEventListener('input',updateMacroUI);
document.getElementById('macroHold').addEventListener('input',updateMacroUI);
document.getElementById('macroStartBtn').addEventListener('click',startMacro);
document.getElementById('macroStopBtn').addEventListener('click',stopMacro);
setInterval(()=>{const p=document.getElementById('page-macro');if(p&&p.classList.contains('active'))refreshMacroStatus()},700);
updateMacroUI();

// BIOS / UEFI detection
function escHtml(s){return String(s==null?'':s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]))}
function biosItem(k,v){return `<div class="biositem"><div class="bioskey">${escHtml(k)}</div><div class="biosval">${escHtml(v)}</div></div>`}
async function loadBios(){
  const box=document.getElementById('biosInfo');
  box.innerHTML=biosItem('Status','Detecting firmware and memory profile...');
  const r=await api('/api/bios/info');
  const items=r.items||[];
  box.innerHTML=items.length?items.map(i=>biosItem(i.k,i.v)).join(''):biosItem('Status','No firmware data available');
  const g=document.getElementById('biosGuidance');
  g.innerHTML=(r.guidance||[]).map(s=>'▸ '+escHtml(s)).join('<br>');
}
document.getElementById('biosRefreshBtn').addEventListener('click',loadBios);
document.getElementById('biosRebootBtn').addEventListener('click',async()=>{
  if(!confirm('Reboot into UEFI firmware settings?\n\nSave your work first. The PC will restart in 5 seconds.'))return;
  const r=await api('/api/bios/reboot');showToast(r.message);
});

document.getElementById('accentColor').addEventListener('input',e=>{document.documentElement.style.setProperty('--red',e.target.value);});
document.getElementById('sidebarColor').addEventListener('input',e=>{document.querySelector('.sidebar').style.background=e.target.value;});
document.getElementById('toggleOutline').addEventListener('change',e=>{document.querySelectorAll('.tweakcard').forEach(c=>{if(e.target.checked)c.classList.add('rotating-outline');else c.classList.remove('rotating-outline');});});
document.getElementById('toggleSnow').addEventListener('change',e=>{document.getElementById('snowCanvas').style.display=e.target.checked?'block':'none';});


// Live online-user counter (tracks open sessions via BroadcastChannel + localStorage heartbeat)
(function(){
  const KEY='nova_online_users';
  const ID=Math.random().toString(36).slice(2);
  function read(){try{return JSON.parse(localStorage.getItem(KEY)||'{}')}catch{return {}}}
  function write(o){try{localStorage.setItem(KEY,JSON.stringify(o))}catch{}}
  function beat(){const o=read();const now=Date.now();for(const k in o){if(now-o[k]>15000)delete o[k]}o[ID]=now;write(o);update();}
  function update(){const o=read();const now=Date.now();let n=0;for(const k in o){if(now-o[k]<=15000)n++}const el=document.getElementById('onlineCount');if(el)el.textContent=Math.max(1,n);}
  beat();setInterval(beat,5000);
  try{const bc=new BroadcastChannel('nova_online');bc.onmessage=()=>update();}catch{}
  window.addEventListener('beforeunload',()=>{const o=read();delete o[ID];write(o);});
})();


document.getElementById('exportSyncBtn').addEventListener('click',()=>{
  const acc=state.user; if(!acc){showToast('Sign in first');return;}
  const code=btoa(JSON.stringify(acc));
  document.getElementById('syncCode').value=code; showToast('Sync code generated');
});
document.getElementById('importSyncBtn').addEventListener('click',async()=>{
  const code=document.getElementById('syncCode').value.trim(); if(!code){showToast('Paste a sync code');return;}
  try{
    const acc=JSON.parse(atob(code));
    await api('/api/register',{name:acc.Name,email:acc.Email,password:'synced'});
    const r=await api('/api/login',{email:acc.Email,password:'synced'});
    if(r.success){onLogin(r.account);showToast('Account imported');}
    else showToast(r.message);
  }catch(e){showToast('Invalid sync code');}
});

