'@

# Show real Windows counts plus the active game profile.
$totalTweaks = @($Script:Tweaks).Count
$allCats = @($Script:Tweaks | ForEach-Object { $_.Cat } | Select-Object -Unique)
$availableTweaks = @($Script:Tweaks | Where-Object { $_.Win })
$gameTweaks = @($Script:Tweaks | Where-Object { Test-NovaTweakForGame $_ })
$insideLead = "$totalTweaks hand-built tweaks across $($allCats -join ', '). $($availableTweaks.Count) apply on Windows."
$tweakSub = "$totalTweaks working tweaks across $($allCats.Count) categories. $($gameTweaks.Count) load in the $(Get-NovaGame) profile; every change is reversible."
$Script:HtmlPage = $Script:HtmlPage.Replace('@@INSIDE_LEAD@@', $insideLead).Replace('@@TWEAK_SUB@@', $tweakSub)
$Script:HtmlPage = $Script:HtmlPage.Replace('@@TWEAK_COUNT@@', [string]$totalTweaks)
$Script:HtmlPage = $Script:HtmlPage.Replace('@@CAT_COUNT@@', [string]$allCats.Count)

# ---------- Embedded WebView2 SDK (single-file; no downloads at runtime) ----------
$Script:WV2_CoreB64 = ''
$Script:WV2_WinFormsB64 = ''
$Script:WV2_LoaderX64B64 = ''
$Script:WV2_LoaderX86B64 = ''

# ---------- API (shared by browser server + native WebView2 window) ----------
function ConvertTo-NovaJson { param($Obj) return ($Obj | ConvertTo-Json -Depth 8 -Compress) }

function Get-NovaTweakState {
    param([string]$Id)
    $ts = $Script:Config.TweakStates
    if ($ts -is [hashtable] -and $ts.ContainsKey($Id)) { return [bool]$ts[$Id] }
    return $false
}

function Set-NovaTweakState {
    param([string]$Id, [bool]$State)
    if (-not ($Script:Config.TweakStates -is [hashtable])) { $Script:Config.TweakStates = @{} }
    $Script:Config.TweakStates[$Id] = $State
}

# Plain-language subcategory used to group tweak cards inside their existing tab.
function Get-NovaTweakSub {
    param($Tweak)
    $id = [string]$Tweak.Id
    $cat = [string]$Tweak.Cat
    $name = ([string]$Tweak.Name).ToLower()
    $desc = ([string]$Tweak.Desc).ToLower()

    switch ($cat) {
        "General" {
            if ($id -in @("memory","temp","fontcache","cleariconcache","clearrecyclebin")) { return "Cleanup & Storage" }
            if ($id -in @("startup")) { return "Boot & Startup" }
            if ($id -in @("disableballoontips","disableinfotips","searchboxhide","taskviewhide","widgetstaskbarhide","desktopslideshowoff","lockstoriesoff","activityfeedoff")) { return "Shell & Notifications" }
            if ($name -match "startup|boot") { return "Boot & Startup" }
            if ($name -match "clean|temp|cache|recycle|memory") { return "Cleanup & Storage" }
            return "System"
        }
        "Input" {
            if ($id -in @("mouseprec","mousesens10","disableenhancepointer","disablemousetrails","setmousespeed1","mousekeysoff","scrollinactiveoff")) { return "Mouse & Aim" }
            if ($id -in @("kbdlag","filterkeysoff","stickykeysoff","togglekeysoff","setkeyboarddelay0","setkeyboardspeed31","cursorblinkoff")) { return "Keyboard" }
            if ($id -in @("inputdelay","usb","foregroundboost","hungapptimeout","autokillhung")) { return "Input Pipeline" }
            if ($name -match "mouse|pointer|aim") { return "Mouse & Aim" }
            if ($name -match "keyboard|key |keys|cursor|blink") { return "Keyboard" }
            return "Input Pipeline"
        }
        "Network" {
            if ($id -in @("dnsgoogle","dnsquad9","dnsauto","flushdnscache","flusharp")) { return "DNS & Resolution" }
            if ($id -in @("teredooff","isatapoff","six4off","disableipv6")) { return "IPv6 & Tunnels" }
            if ($id -in @("netdiscoveryoff","filesharingoff","disablellmnr","disablenetbios","disablesmb1")) { return "Discovery & Sharing" }
            if ($id -in @("pingstab","wifipowersave","eeeoff","flowcontroloff","woloff","smbmultichannel")) { return "Adapter & Wi-Fi" }
            if ($id -in @("nagle","autotune","qos","rscdisable","initialrto","disableinterruptmoderation","enablerss")) { return "TCP & Offloads" }
            if ($name -match "dns") { return "DNS & Resolution" }
            if ($name -match "offload|tcp|nagle|autotun|qos|interrupt|rss") { return "TCP & Offloads" }
            if ($name -match "adapter|ethernet|wi-fi|wifi|power saving|flow control") { return "Adapter & Wi-Fi" }
            return "Latency & Adapters"
        }
        "Power" {
            if ($id -in @("corepark","powerthrottle","timer")) { return "CPU Scheduling" }
            if ($id -in @("hags")) { return "GPU Scheduling" }
            if ($id -in @("power","faststartup","hibernate","usbss","nosleep","displaysleepoff","disksleepoff","batterysaveroff","macpower")) { return "Power Plan & Sleep" }
            if ($name -match "gpu|graphics|hardware-accelerated") { return "GPU Scheduling" }
            if ($name -match "cpu|core|timer|throttl") { return "CPU Scheduling" }
            return "Power Plan & Sleep"
        }
        "Visual" {
            if ($id -in @("transp","disablelockscreenblur")) { return "Transparency & Blur" }
            if ($id -in @("fontcache","disablefontsmoothing2","disablecursorshadow","disablelistviewalpha")) { return "Text & Cursors" }
            if ($id -in @("visual","menu","disablemenuanim","winanimoff","disabletaskbaranim","disableaeropeek","disableshake","disableshadow","macwinanim","macdock","macfinderanim","macreducemotion","macappnap")) { return "Animations & Effects" }
            if ($name -match "transparen|blur|acrylic|mica") { return "Transparency & Blur" }
            if ($name -match "font|cursor|text|clear") { return "Text & Cursors" }
            if ($name -match "animation|effect|peek|shake|shadow|menu") { return "Animations & Effects" }
            return "Shell & Appearance"
        }
        "Services" {
            if ($name -match "xbox|game") { return "Xbox & Gaming" }
            if ($name -match "telemetry|diagnostic|error|feedback|advertis|consumer|activity|copilot|recall|insider") { return "Telemetry & Diagnostics" }
            if ($name -match "update|delivery|bits|download") { return "Update & Delivery" }
            if ($name -match "audio|bluetooth|print|fax|tablet|touch|phone|media") { return "Media & Devices" }
            if ($name -match "remote|rss|smb|remote access|connection sharing|ras|telephony|netbios|llmnr") { return "Remote & Sharing" }
            if ($name -match "search|prefetch|superfetch|defrag|maintenance|sysmain") { return "Maintenance & Search" }
            return "Background Services"
        }
        "Game" {
            if ($id -like "mc*") { return "Minecraft" }
            if ($id -in @("potato","gamemode","mpo","fullopt","gamedvr","fpsbooster")) { return "Fortnite & Rendering" }
            if ($id -in @("bcdedit","timer")) { return "Stutter & Scheduling" }
            if ($name -match "stutter|stutter|scheduling|timer|bcd") { return "Stutter & Scheduling" }
            return "Game"
        }
        "Storage" {
            if ($name -match "clean|temp|cache|recycle|winsxs|space") { return "Disk Cleanup" }
            if ($name -match "ntfs|8\.3|trim|filesystem|last access") { return "Filesystem & NTFS" }
            if ($name -match "health|smart|defrag|optimize") { return "Disk Health" }
            return "Storage"
        }
        "Firmware" {
            if ($id -in @("vbsdisable","memoryintegrityoff","hypervisoroff","smartscreen","defendercloud")) { return "Virtualization & Security" }
            if ($name -match "virtual|vbs|hypervisor|integrity|secure boot|defender|smartscreen") { return "Virtualization & Security" }
            if ($name -match "memory|xmp|expo|ram|hags|gpu") { return "CPU & Memory" }
            if ($name -match "boot|uefi|bios|firmware") { return "Boot & Firmware" }
            return "Firmware"
        }
        "Privacy" {
            if ($name -match "telemetry|advertis|activity|feedback|tips|consumer|copilot|recall|lock") { return "Telemetry & Tracking" }
            if ($name -match "search|cortana|widget|news|web") { return "Search & Web" }
            if ($name -match "remote|share|smb|netbios|llmnr|onedrive") { return "Sharing & Remote" }
            return "Privacy"
        }
    }
    if ($name -match "xbox|game") { return "Gaming" }
    if ($name -match "dns") { return "DNS & Resolution" }
    if ($name -match "mouse|pointer") { return "Mouse & Aim" }
    if ($name -match "keyboard|keys") { return "Keyboard" }
    return "Other"
}

function Invoke-NovaApi {
    param([string]$Path, [string]$BodyJson)

    $body = @{}
    if ($BodyJson) {
        try {
            $parsed = $BodyJson | ConvertFrom-Json
            if ($parsed) { $body = $parsed }
        } catch { $body = @{} }
    }

    try {
        if ($Path -eq "/api/autologin") {
            $acc = $Script:CurrentUser
            if ($acc) {
                Update-NovaStreak | Out-Null
                $acc = $Script:CurrentUser
                return (ConvertTo-NovaJson @{ success = $true; account = $acc })
            }
            return (ConvertTo-NovaJson @{ success = $false })
        }

        if ($Path -eq "/api/login") {
            $result = Verify-Login $body.email $body.password
            if ($result.success) {
                $Script:CurrentUser = Normalize-NovaAccount $result.account
                $Script:Config.Plan = $Script:CurrentUser.Plan
                $Script:Config.PlanUntil = $Script:CurrentUser.PlanUntil
                $Script:Config.Balance = $Script:CurrentUser.Balance
                $Script:Config.CurrentUser = $result.account.Email
                Save-Config
                Update-NovaStreak | Out-Null
                $result.account = $Script:CurrentUser
            }
            return (ConvertTo-NovaJson $result)
        }

        if ($Path -eq "/api/register") {
            $result = Create-Account $body.email $body.password $body.name
            return (ConvertTo-NovaJson $result)
        }

        if ($Path -eq "/api/logout") {
            Logout
            $Script:CurrentUser = $null
            $Script:Config.Plan = "Free"
            $Script:Config.PlanUntil = $null
            $Script:Config.Balance = 0
            $Script:Config.CurrentUser = ""
            Save-Config
            return (ConvertTo-NovaJson @{ success = $true })
        }

        if ($Path -eq "/api/game") {
            if ($Script:FixedGame) { return (ConvertTo-NovaJson @{ success = $false; fixed = $true; game = (Get-NovaGame); message = "This Nova Tweaks app is dedicated to $(Get-NovaGame)." }) }
            $game = [string]$body.game
            if (-not $game) { return (ConvertTo-NovaJson @{ success = $true; game = (Get-NovaGame) }) }
            if ($game -notin @("Fortnite","Minecraft")) {
                return (ConvertTo-NovaJson @{ success = $false; message = "Unknown game."; game = (Get-NovaGame) })
            }
            $Script:Config.Game = $game
            Save-Config
            return (ConvertTo-NovaJson @{ success = $true; game = $game; message = "Switched to $game Tweaks." })
        }

        if ($Path -eq "/api/tweaks/list") {
            if ($Script:CurrentUser) { Update-NovaStreak | Out-Null }
            $activePlan = Get-NovaEffectivePlan
            $activeGame = Get-NovaGame
            $tweakObj = [ordered]@{}
            $viewWin = Get-NovaViewIsWin
            foreach ($t in $Script:Tweaks) {
                if (-not (Test-NovaTweakForGame $t)) { continue }
                $isAvail = if ($viewWin) { $t.Win } else { $t.Mac }
                $osLabel = if ($t.Win -and $t.Mac) { "Both" } elseif ($t.Win) { "Windows" } else { "Mac" }
                $required = Get-NovaTweakRequiredPlan $t
                $allowed = Test-NovaTweakAllowed $t $activePlan
                $tweakObj[$t.Id] = @{
                    id        = $t.Id
                    name      = $t.Name
                    desc      = $t.Desc
                    risk      = $t.Risk
                    free      = ($required -eq "Free")
                    required  = $required
                    locked    = [bool]($isAvail -and -not $allowed)
                    cat       = $t.Cat
                    sub       = (Get-NovaTweakSub $t)
                    os        = $osLabel
                    game      = $(if ($t.Game) { [string]$t.Game } else { "Shared" })
                    available = [bool]$isAvail
                    state     = (Get-NovaTweakState ([string]$t.Id))
                }
            }
            $gameTweaks = @($Script:Tweaks | Where-Object { Test-NovaTweakForGame $_ })
            $balance = if ($Script:CurrentUser) { [int]$Script:CurrentUser.Balance } else { [int]$Script:Config.Balance }
            $planUntil = if ($Script:CurrentUser) { $Script:CurrentUser.PlanUntil } else { $Script:Config.PlanUntil }
            $badges = @(Get-NovaBadgeState)
            $streak = if ($Script:CurrentUser) { [int]$Script:CurrentUser.Streak } else { 0 }
            $bestStreak = if ($Script:CurrentUser) { [int]$Script:CurrentUser.BestStreak } else { 0 }
            $appliedEver = if ($Script:CurrentUser) { @($Script:CurrentUser.AppliedEver | Where-Object { $_ }).Count } else { 0 }
            return (ConvertTo-NovaJson @{
                tweaks = $tweakObj
                os = $(if ($viewWin) { "Windows" } else { "Mac" })
                game = $activeGame
                plan = $activePlan
                balance = $balance
                planUntil = $planUntil
                badges = $badges
                streak = $streak
                bestStreak = $bestStreak
                appliedEver = $appliedEver
                previewWindows = [bool]$Script:WindowsPreview
                fixedGame = $Script:FixedGame
                appVariant = $Script:AppVariant
                freeCount = @($gameTweaks | Where-Object { (Get-NovaTweakRequiredPlan $_) -eq "Free" }).Count
                paidCount = @($gameTweaks | Where-Object { (Get-NovaTweakRequiredPlan $_) -ne "Free" }).Count
            })
        }

        if ($Path -eq "/api/badges") {
            if ($Script:CurrentUser) { Update-NovaStreak | Out-Null }
            $badges = @(Get-NovaBadgeState)
            $streak = if ($Script:CurrentUser) { [int]$Script:CurrentUser.Streak } else { 0 }
            $bestStreak = if ($Script:CurrentUser) { [int]$Script:CurrentUser.BestStreak } else { 0 }
            return (ConvertTo-NovaJson @{
                success = $true
                badges = $badges
                streak = $streak
                bestStreak = $bestStreak
                earned = @($badges | Where-Object { $_.earned }).Count
                total = @($badges).Count
            })
        }

        if ($Path -eq "/api/macro/capture") {
            if (-not $IsWin) { return (ConvertTo-NovaJson @{ success = $false; message = "Drag Macro is Windows only." }) }
            $pos = Get-NovaCursorPos
            if (-not $pos) { return (ConvertTo-NovaJson @{ success = $false; message = "Could not read the cursor position." }) }
            return (ConvertTo-NovaJson @{ success = $true; x = $pos.x; y = $pos.y })
        }

        if ($Path -eq "/api/macro/start") {
            if ((Get-NovaPlanRank (Get-NovaEffectivePlan)) -lt 1) { return (ConvertTo-NovaJson @{ success = $false; locked = $true; required = "Pro"; message = "Drag Macro needs Pro." }) }
            $res = Start-NovaMacro `
                -StartX ([int]$body.start.x) -StartY ([int]$body.start.y) `
                -EndX ([int]$body.end.x) -EndY ([int]$body.end.y) `
                -Duration ([int]$body.duration) -Hold ([int]$body.hold) `
                -Repeat ([int]$body.repeat) -Loop ([bool]$body.loop)
            return (ConvertTo-NovaJson $res)
        }

        if ($Path -eq "/api/macro/stop") {
            return (ConvertTo-NovaJson (Stop-NovaMacro))
        }

        if ($Path -eq "/api/macro/status") {
            return (ConvertTo-NovaJson (Get-NovaMacroStatus))
        }

        if ($Path -eq "/api/bios/info") {
            return (ConvertTo-NovaJson (Get-NovaBiosInfo))
        }

        if ($Path -eq "/api/bios/reboot") {
            if (-not $IsWin) { return (ConvertTo-NovaJson @{ success = $false; message = "UEFI firmware settings are Windows only. On macOS, restart while holding Command+R." }) }
            try {
                $out = & shutdown /r /fw /t 5 2>&1
                if ($LASTEXITCODE -ne 0) { throw (($out | Out-String).Trim()) }
                return (ConvertTo-NovaJson @{ success = $true; message = "Rebooting into UEFI in 5 seconds. Save your work." })
            } catch {
                return (ConvertTo-NovaJson @{ success = $false; message = "Could not open UEFI: $($_.Exception.Message). Restart and press Del/F2 to enter firmware settings." })
            }
        }

        if ($Path -eq "/api/tweak/toggle") {
            if ($Script:WindowsPreview) { return (ConvertTo-NovaJson @{ success = $false; preview = $true; message = "Windows preview: showing the Windows UI only. No system changes are made on this Mac." }) }
            $tw = $Script:Tweaks | Where-Object { $_.Id -eq $body.id } | Select-Object -First 1
            if (-not $tw) { return (ConvertTo-NovaJson @{ message = "Tweak not found." }) }
            if (-not (Test-NovaTweakForGame $tw)) { return (ConvertTo-NovaJson @{ success = $false; message = "That tweak belongs to a different game profile. Switch games in Settings first." }) }
            $desired = [bool]$body.state
            if ($desired) {
                $activePlan = Get-NovaEffectivePlan
                if (-not (Test-NovaTweakAllowed $tw $activePlan)) {
                    $required = Get-NovaTweakRequiredPlan $tw
                    return (ConvertTo-NovaJson @{
                        success = $false
                        locked = $true
                        required = $required
                        message = "Locked: $($tw.Name) needs $required. Open Settings to upgrade."
                    })
                }
            }
            Set-NovaTweakState ([string]$body.id) $desired
            Save-Config
            $msg = "Reverted: $($tw.Name)"
            if ($desired) {
                try { & $tw.Action; $msg = "Applied: $($tw.Name)" }
                catch { $msg = "Failed: $($_.Exception.Message)" }
            } elseif ($tw.Off) {
                try { & $tw.Off; $msg = "Reverted: $($tw.Name)" }
                catch { $msg = "Reverted state; restore may be partial: $($_.Exception.Message)" }
            } elseif ($tw.Svc) {
                Invoke-ServiceRestore -Name $tw.Svc
                $msg = "Reverted: $($tw.Name)"
            }
            if ($desired) { Add-NovaAppliedTweak ([string]$tw.Id) }
            return (ConvertTo-NovaJson @{ success = $true; message = $msg })
        }

        if ($Path -eq "/api/inputdelay") {
            if ((Get-NovaPlanRank (Get-NovaEffectivePlan)) -lt 1) { return (ConvertTo-NovaJson @{ success = $false; locked = $true; required = "Pro"; message = "Input Response Accelerator needs Pro." }) }
            Invoke-InputDelayReducer; Invoke-MousePrecision; Invoke-KeyboardLatency; Invoke-USBPolling
            return (ConvertTo-NovaJson @{ message = "Input Response Accelerator applied (10 changes)." })
        }

        if ($Path -eq "/api/pingstab") {
            if ((Get-NovaPlanRank (Get-NovaEffectivePlan)) -lt 1) { return (ConvertTo-NovaJson @{ success = $false; locked = $true; required = "Pro"; message = "Network Spike Smoother needs Pro." }) }
            Invoke-PingStabilizer
            return (ConvertTo-NovaJson @{ message = "Network Spike Smoother applied." })
        }

        if ($Path -eq "/api/booster") {
            if ((Get-NovaPlanRank (Get-NovaEffectivePlan)) -lt 1) { return (ConvertTo-NovaJson @{ success = $false; locked = $true; required = "Pro"; message = "Game Booster needs Pro." }) }
            Invoke-GameBooster
            return (ConvertTo-NovaJson @{ message = "Game Booster complete." })
        }

        if ($Path -eq "/api/fpsbooster") {
            if ($Script:WindowsPreview) { return (ConvertTo-NovaJson @{ success = $false; preview = $true; message = "Windows preview: FPS Booster is simulated only; no system changes are made on this Mac." }) }
            if ((Get-NovaPlanRank (Get-NovaEffectivePlan)) -lt 1) { return (ConvertTo-NovaJson @{ success = $false; locked = $true; required = "Pro"; message = "FPS Booster needs Pro." }) }
            $steps = @(Invoke-FpsBooster)
            Add-NovaAppliedTweak "fpsbooster"
            $detail = if ($steps.Count -gt 0) { $steps -join ", " } else { "no supported changes were found" }
            return (ConvertTo-NovaJson @{ success = $true; steps = $steps; message = "FPS Booster applied: $detail." })
        }

        if ($Path -eq "/api/net/stats") {
            $target = if ($body.target) { [string]$body.target } else { "1.1.1.1" }
            $stats = Get-NovaNetworkStats -Target $target -Count 4
            return (ConvertTo-NovaJson $stats)
        }

        if ($Path -eq "/api/potato") {
            if ((Get-NovaPlanRank (Get-NovaEffectivePlan)) -lt 2) { return (ConvertTo-NovaJson @{ success = $false; locked = $true; required = "Ultimate"; message = "Potato Graphics needs Ultimate." }) }
            Invoke-PotatoGraphics
            return (ConvertTo-NovaJson @{ message = "Potato Graphics applied." })
        }

        if ($Path -eq "/api/applyall") {
            if ($Script:WindowsPreview) { return (ConvertTo-NovaJson @{ success = $false; preview = $true; message = "Windows preview: no system changes are made on this Mac." }) }
            $activePlan = Get-NovaEffectivePlan
            $count = 0
            $skipped = 0
            $appliedIds = New-Object System.Collections.Generic.List[string]
            foreach ($t in $Script:Tweaks) {
                if (-not (Test-NovaTweakForGame $t)) { continue }
                $isAvail = if ($IsWin) { $t.Win } else { $t.Mac }
                if (-not $isAvail) { continue }
                if (-not (Test-NovaTweakAllowed $t $activePlan)) { $skipped++; continue }
                Set-NovaTweakState ([string]$t.Id) $true
                try { & $t.Action } catch {}
                [void]$appliedIds.Add([string]$t.Id)
                $count++
            }
            Save-Config
            if ($appliedIds.Count -gt 0) { Add-NovaAppliedTweaks -Ids @($appliedIds) }
            $msg = "Applied $count tweaks."
            if ($skipped -gt 0) { $msg += " $skipped locked tweaks were skipped." }
            return (ConvertTo-NovaJson @{ message = $msg; applied = $count; skipped = $skipped })
        }

        if ($Path -eq "/api/sysstats") {
            $s = Get-NovaSysStats
            if ($Script:WindowsPreview) { try { $s.os = "Windows (preview)" } catch {} }
            return (ConvertTo-NovaJson $s)
        }

        if ($Path -eq "/api/sysinfo") {
            $viewWin = Get-NovaViewIsWin
            $info = "OS: $(if ($Script:WindowsPreview) { 'Windows (preview on macOS)' } elseif ($IsWin) { 'Windows' } else { 'macOS' })`n"
            if ($IsWin) {
                $cpu = (Get-CimInstance Win32_Processor).Name
                $gpu = (Get-CimInstance Win32_VideoController | Select-Object -First 1).Name
                $ram = [math]::Round((Get-CimInstance Win32_ComputerSystem).TotalPhysicalMemory / 1GB, 1)
                $info += "CPU: $cpu`nGPU: $gpu`nRAM: $ram GB"
            } elseif ($Script:WindowsPreview) {
                $info += "CPU: $(sysctl -n machdep.cpu.brand_string 2>$null)`nRAM: $([math]::Round((sysctl -n hw.memsize 2>$null) / 1GB, 1)) GB`nNote: preview mode shows Windows tweaks/UI; this Mac's hardware is listed for reference."
            } else {
                $info += "CPU: $(sysctl -n machdep.cpu.brand_string 2>$null)`nRAM: $([math]::Round((sysctl -n hw.memsize 2>$null) / 1GB, 1)) GB"
            }
            return (ConvertTo-NovaJson @{ info = $info })
        }

        if ($Path -eq "/api/bench") {
            $sw = [Diagnostics.Stopwatch]::StartNew()
            $c = 0
            for ($i = 2; $i -lt 200000; $i++) {
                $isP = $true
                for ($j = 2; $j * $j -le $i; $j++) { if ($i % $j -eq 0) { $isP = $false; break } }
                if ($isP) { $c++ }
            }
            $sw.Stop()
            return (ConvertTo-NovaJson @{ result = "Micro-bench: $([math]::Round($sw.Elapsed.TotalMilliseconds,1)) ms (lower = better)" })
        }

        if ($Path -eq "/api/savebench") {
            $row = "$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss'),$($body.before),$($body.after)"
            $bp = Join-Path $Script:Root "benchmark.csv"
            if (-not (Test-Path $bp)) { "Date,FPS_Before,FPS_After" | Set-Content $bp }
            Add-Content $bp $row
            return (ConvertTo-NovaJson @{ message = "Saved to $bp" })
        }

        if ($Path -eq "/api/restorepoint") {
            if ($Script:WindowsPreview) { return (ConvertTo-NovaJson @{ success = $false; preview = $true; message = "Windows preview: restore points are Windows-only and not created on this Mac." }) }
            $msg = "Restore point: not supported on this OS."
            if ($IsWin) {
                try { Checkpoint-Computer -Description "Nova Tweaks" -RestorePointType "MODIFY_SETTINGS" -ErrorAction Stop; $msg = "Restore point created." }
                catch { $msg = "Restore point failed: $($_.Exception.Message)" }
            }
            return (ConvertTo-NovaJson @{ message = $msg })
        }

        if ($Path -eq "/api/revertall") {
            if ($Script:WindowsPreview) { return (ConvertTo-NovaJson @{ success = $false; preview = $true; message = "Windows preview: no system changes are made on this Mac." }) }
            Revert-All
            if ($Script:CurrentUser) {
                $acc = Normalize-NovaAccount $Script:CurrentUser
                $acc.CleanSweeps = [int]$acc.CleanSweeps + 1
                $Script:CurrentUser = $acc
                Update-NovaBadges | Out-Null
                Save-NovaCurrentAccount | Out-Null
            }
            return (ConvertTo-NovaJson @{ message = "All changes reverted. Reboot recommended." })
        }

        if ($Path -eq "/api/log") {
            $logContent = if (Test-Path $Script:LogPath) { Get-Content $Script:LogPath -Raw } else { "" }
            return (ConvertTo-NovaJson @{ log = $logContent })
        }

        if ($Path -eq "/api/gift/redeem") {
            if (-not $Script:CurrentUser) { return (ConvertTo-NovaJson @{ success = $false; message = "Sign in to redeem a gift code." }) }
            $code = ([string]$body.code).Trim().ToUpper()
            $cents = Test-NovaGiftCode $code
            if (-not $cents) { return (ConvertTo-NovaJson @{ success = $false; message = "That gift code is not valid." }) }
            $acc = Normalize-NovaAccount $Script:CurrentUser
            $redeemed = @($acc.Redeemed)
            if ($code -in $redeemed) { return (ConvertTo-NovaJson @{ success = $false; message = "That gift code was already redeemed on this account." }) }
            $acc.Redeemed = @($redeemed + $code)
            $acc.Balance = [int]$acc.Balance + [int]$cents
            $Script:CurrentUser = $acc
            $updated = Save-NovaCurrentAccount
            return (ConvertTo-NovaJson @{
                success = $true
                message = ("Added $" + ([math]::Round($cents / 100, 2)).ToString("0.00") + " to your balance.")
                balance = [int]$updated.Balance
                plan = $updated.Plan
                planUntil = $updated.PlanUntil
            })
        }

        if ($Path -eq "/api/plan/buy") {
            if (-not $Script:CurrentUser) { return (ConvertTo-NovaJson @{ success = $false; message = "Sign in to change your plan." }) }
            $target = switch (([string]$body.plan).ToLower()) { "pro" { "Pro" } "ultimate" { "Ultimate" } default { $null } }
            if (-not $target) { return (ConvertTo-NovaJson @{ success = $false; message = "Unknown plan." }) }
            $acc = Normalize-NovaAccount $Script:CurrentUser
            if ((Get-NovaPlanRank $acc.Plan) -gt (Get-NovaPlanRank $target)) {
                return (ConvertTo-NovaJson @{ success = $false; message = "You are already on $($acc.Plan), which is higher than $target." })
            }
            $cost = Get-NovaPlanPriceCents $target
            $balance = [int]$acc.Balance
            if ($balance -lt $cost) {
                $short = $cost - $balance
                return (ConvertTo-NovaJson @{
                    success = $false
                    balance = $balance
                    cost = $cost
                    shortfall = $short
                    message = ("Balance is $" + ([math]::Round($balance / 100, 2)).ToString("0.00") + " — you need $" + ([math]::Round($cost / 100, 2)).ToString("0.00") + ". Redeem a gift code or buy a license on the website.")
                })
            }
            $acc.Balance = $balance - $cost
            $Script:CurrentUser = $acc
            $updated = Set-NovaAccountPlan $target 30
            $until = Get-NovaPlanUntil $updated
            return (ConvertTo-NovaJson @{
                success = $true
                plan = $updated.Plan
                planUntil = $updated.PlanUntil
                balance = [int]$updated.Balance
                message = ("$target active through " + $(if ($until) { $until.ToString("MMM d, yyyy") } else { "30 days" }) + ". Balance left: $" + ([math]::Round($updated.Balance / 100, 2)).ToString("0.00") + ".")
            })
        }

        if ($Path -eq "/api/activate") {
            if (-not $Script:CurrentUser) { return (ConvertTo-NovaJson @{ success = $false; message = "Sign in before activating a license key." }) }
            $key = ([string]$body.key).Trim()
            $kind = Test-NovaLicenseKey $key
            if (-not $kind) {
                return (ConvertTo-NovaJson @{ success = $false; message = "Invalid or tampered license key." })
            }
            $target = if ($kind -eq "ULT") { "Ultimate" } else { "Pro" }
            $acc = Normalize-NovaAccount $Script:CurrentUser
            $acc.LicenseKey = $key
            $Script:CurrentUser = $acc
            $updated = Set-NovaAccountPlan $target 30
            $until = Get-NovaPlanUntil $updated
            $msg = "$target activated through " + $(if ($until) { $until.ToString("MMM d, yyyy") } else { "30 days" }) + "."
            return (ConvertTo-NovaJson @{ success = $true; plan = $updated.Plan; planUntil = $updated.PlanUntil; balance = [int]$updated.Balance; message = $msg })
        }

        if ($Path -eq "/__html" -or $Path -eq "/__init" -or $Path -eq "__html" -or $Path -eq "__init") {
            return (ConvertTo-NovaJson @{ html = $Script:HtmlPage })
        }

        return (ConvertTo-NovaJson @{ success = $false; message = "Unknown endpoint: $Path" })
    } catch {
        return (ConvertTo-NovaJson @{ success = $false; message = $_.Exception.Message })
    }
}

# ---------- Native stdio bridge (no localhost) ----------
function Start-NovaStdioServer {
    [Console]::OutputEncoding = [System.Text.Encoding]::UTF8
    $utf8 = New-Object System.Text.UTF8Encoding($false)
    $stdin = [Console]::OpenStandardInput()
    $reader = New-Object System.IO.StreamReader($stdin, $utf8)
    $stdout = [Console]::OpenStandardOutput()
    $writer = New-Object System.IO.StreamWriter($stdout, $utf8)
    $writer.AutoFlush = $true
    try {
        while ($null -ne ($line = $reader.ReadLine())) {
            if ([string]::IsNullOrWhiteSpace($line)) { continue }
            $id = $null
            try {
                $msg = $line | ConvertFrom-Json
                $id = $msg.id
                $path = [string]$msg.path
                $bodyJson = if ($null -ne $msg.body) { [string]$msg.body } else { "" }
                if ($path -eq "/__html" -or $path -eq "/__init" -or $path -eq "__html" -or $path -eq "__init") {
                    $resp = ConvertTo-NovaJson @{ html = $Script:HtmlPage }
                } else {
                    $resp = Invoke-NovaApi -Path $path -BodyJson $bodyJson
                    if (-not $resp) { $resp = "{}" }
                }
                $writer.WriteLine((ConvertTo-NovaJson @{ id = $id; body = [string]$resp }))
            } catch {
                $err = ConvertTo-NovaJson @{ success = $false; message = $_.Exception.Message }
                $writer.WriteLine((ConvertTo-NovaJson @{ id = $id; body = [string]$err }))
            }
        }
    } finally {
        try { $writer.Dispose() } catch {}
        try { $reader.Dispose() } catch {}
    }
}

# ---------- Browser server (macOS) ----------
function Get-NovaFreePort {
    $l = New-Object System.Net.Sockets.TcpListener([System.Net.IPAddress]::Loopback, 0)
    $l.Start()
    $p = $l.LocalEndpoint.Port
    $l.Stop()
    return $p
}

function Start-NovaWebServer {
    $listener = $null
    $port = 0
    foreach ($candidate in @(8765, 8766, 8767, 0)) {
        try {
            $listener = New-Object System.Net.HttpListener
            $port = if ($candidate -eq 0) { Get-NovaFreePort } else { $candidate }
            $listener.Prefixes.Add("http://localhost:$port/")
            $listener.Start()
            break
        } catch {
            if ($listener) { try { $listener.Close() } catch {} }
            $listener = $null
        }
    }
    if (-not $listener -or -not $listener.IsListening) { throw "Could not start the Nova Tweaks UI server." }

    $url = "http://localhost:$port"
    Write-Host "Nova Tweaks UI running at $url" -ForegroundColor Red
    if (-not $env:NOVA_NOOPEN) {
        if ($IsMac) {
            $chrome = @("/Applications/Google Chrome.app/Contents/MacOS/Google Chrome", "/Applications/Microsoft Edge.app/Contents/MacOS/Microsoft Edge", "/Applications/Chromium.app/Contents/MacOS/Chromium") | Where-Object { Test-Path $_ } | Select-Object -First 1
            if ($env:NOVA_APP_WINDOW -eq '1' -and $chrome) {
                Start-Process $chrome -ArgumentList @("--app=$url", "--user-data-dir=$env:HOME/.novatweaks/chrome-app-profile") | Out-Null
            } else {
                Start-Process "open" -ArgumentList $url | Out-Null
            }
        }
        elseif ($IsWin) { Start-Process $url | Out-Null }
    }

    while ($listener.IsListening) {
        $ctx = $listener.GetContext()
        $req = $ctx.Request
        $res = $ctx.Response
        try {
            $path = $req.Url.AbsolutePath
            if ($path -eq "/" -or $path -eq "/index.html") {
                $buf = [System.Text.Encoding]::UTF8.GetBytes($Script:HtmlPage)
                $res.ContentType = "text/html; charset=utf-8"
                $res.OutputStream.Write($buf, 0, $buf.Length)
            } else {
                $bodyJson = ""
                if ($req.HasEntityBody) {
                    $reader = New-Object System.IO.StreamReader($req.InputStream)
                    $bodyJson = $reader.ReadToEnd()
                }
                $json = Invoke-NovaApi -Path $path -BodyJson $bodyJson
                if (-not $json) { $json = "{}" }
                $buf = [System.Text.Encoding]::UTF8.GetBytes($json)
                $res.ContentType = "application/json; charset=utf-8"
                $res.OutputStream.Write($buf, 0, $buf.Length)
            }
        } catch {
            try { $res.StatusCode = 500 } catch {}
        } finally {
            try { $res.Close() } catch {}
        }
    }
}

# ---------- Native WebView2 window (Windows) ----------
function Get-NovaWebView2Dir {
    $dir = Join-Path $Script:Root "webview2"
    if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
    $core = Join-Path $dir "Microsoft.Web.WebView2.Core.dll"
    $wf = Join-Path $dir "Microsoft.Web.WebView2.WinForms.dll"
    $loader = Join-Path $dir "WebView2Loader.dll"
    if (-not (Test-Path $core)) { [IO.File]::WriteAllBytes($core, [Convert]::FromBase64String($Script:WV2_CoreB64)) }
    if (-not (Test-Path $wf)) { [IO.File]::WriteAllBytes($wf, [Convert]::FromBase64String($Script:WV2_WinFormsB64)) }
    if (-not (Test-Path $loader)) {
        $b64 = if ([Environment]::Is64BitProcess) { $Script:WV2_LoaderX64B64 } else { $Script:WV2_LoaderX86B64 }
        [IO.File]::WriteAllBytes($loader, [Convert]::FromBase64String($b64))
    }
    return $dir
}

function Install-NovaWebView2Runtime {
    try {
        [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
        $exe = Join-Path $env:TEMP "MicrosoftEdgeWebView2Setup.exe"
        Invoke-WebRequest -Uri "https://go.microsoft.com/fwlink/p/?LinkId=2124703" -OutFile $exe -UseBasicParsing
        $p = Start-Process -FilePath $exe -ArgumentList "/silent", "/install" -PassThru -Wait
        return ($p.ExitCode -eq 0)
    } catch {
        return $false
    }
}

function Start-NovaWebView {
    Add-Type -AssemblyName System.Windows.Forms
    Add-Type -AssemblyName System.Drawing
    [System.Windows.Forms.Application]::EnableVisualStyles()
    [System.Windows.Forms.Application]::SetCompatibleTextRenderingDefault($false)

    $dir = Get-NovaWebView2Dir

    Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
public class NovaWebViewNative {
    [DllImport("kernel32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
    public static extern bool SetDllDirectory(string lpPathName);
}
"@ -ErrorAction SilentlyContinue
    try { [NovaWebViewNative]::SetDllDirectory($dir) | Out-Null } catch {}
    try { $env:PATH = $dir + ";" + $env:PATH } catch {}

    [System.Reflection.Assembly]::LoadFrom((Join-Path $dir "Microsoft.Web.WebView2.Core.dll")) | Out-Null
    [System.Reflection.Assembly]::LoadFrom((Join-Path $dir "Microsoft.Web.WebView2.WinForms.dll")) | Out-Null

    $runtime = $null
    try { $runtime = [Microsoft.Web.WebView2.Core.CoreWebView2Environment]::GetAvailableBrowserVersionString() } catch { $runtime = $null }
    if (-not $runtime) {
        $installed = Install-NovaWebView2Runtime
        try { $runtime = [Microsoft.Web.WebView2.Core.CoreWebView2Environment]::GetAvailableBrowserVersionString() } catch { $runtime = $null }
        if (-not $runtime) {
            [System.Windows.Forms.MessageBox]::Show(
                "Nova Tweaks needs the Microsoft WebView2 runtime (it ships with Windows 11 and most Windows 10 PCs).`n`nPlease install it from:`nhttps://go.microsoft.com/fwlink/p/?LinkId=2124703`n`nThen open Nova Tweaks again.",
                "Nova Tweaks - Missing Runtime",
                [System.Windows.Forms.MessageBoxButtons]::OK,
                [System.Windows.Forms.MessageBoxIcon]::Warning) | Out-Null
            return
        }
    }

    $dataDir = Join-Path $Script:Root "webview2-data"
    if (-not (Test-Path $dataDir)) { New-Item -ItemType Directory -Path $dataDir -Force | Out-Null }
    $env:WEBVIEW2_USER_DATA_FOLDER = $dataDir

    # Write the UI to a real folder so it gets a proper https origin (localStorage, history,
    # reload all behave like a normal web app). No localhost server is started.
    $Script:WebUiDir = Join-Path $Script:Root "webui"
    if (-not (Test-Path $Script:WebUiDir)) { New-Item -ItemType Directory -Path $Script:WebUiDir -Force | Out-Null }
    $Script:WebUiPath = Join-Path $Script:WebUiDir "index.html"
    [IO.File]::WriteAllText($Script:WebUiPath, $Script:HtmlPage)

    $form = New-Object System.Windows.Forms.Form
    $winTitle = if ($Script:FixedGame) { "Nova Tweaks ($($Script:FixedGame))" } else { "Nova Tweaks" }
    $form.Text = $winTitle
    $form.StartPosition = "CenterScreen"
    $form.Size = New-Object System.Drawing.Size(1440, 900)
    $form.MinimumSize = New-Object System.Drawing.Size(1100, 720)
    $form.WindowState = "Maximized"
    $form.BackColor = [System.Drawing.Color]::FromArgb(8, 8, 12)
    $form.ForeColor = [System.Drawing.Color]::White

    $wv = New-Object Microsoft.Web.WebView2.WinForms.WebView2
    $wv.Dock = "Fill"
    $wv.DefaultBackgroundColor = [System.Drawing.Color]::FromArgb(8, 8, 12)
    $form.Controls.Add($wv)

    $wv.add_CoreWebView2InitializationCompleted({
        param($sender, $e)
        if (-not $e.IsSuccess) {
            $reason = if ($e.InitializationException) { $e.InitializationException.Message } else { "Unknown error" }
            [System.Windows.Forms.MessageBox]::Show("WebView2 could not start.`n`n$reason", "Nova Tweaks", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Error) | Out-Null
            return
        }
        try {
            $sender.CoreWebView2.Settings.AreDefaultContextMenusEnabled = $false
            $sender.CoreWebView2.Settings.AreDevToolsEnabled = $false
            $sender.CoreWebView2.Settings.IsStatusBarEnabled = $false
            $sender.CoreWebView2.add_DocumentTitleChanged({
                param($s, $a)
                try {
                    $t = $s.DocumentTitle
                    if ($t) { $form.Text = $t }
                } catch {}
            })
        } catch {}

        $Script:WebUiVirtual = $false
        try {
            $sender.CoreWebView2.SetVirtualHostNameToFolderMapping(
                "nova.local",
                $Script:WebUiDir,
                [Microsoft.Web.WebView2.Core.CoreWebView2HostResourceAccessKind]::DenyCors)
            $Script:WebUiVirtual = $true
        } catch { $Script:WebUiVirtual = $false }

        $sender.CoreWebView2.add_WebMessageReceived({
            param($core, $msgArgs)
            $raw = $null
            try {
                $raw = $msgArgs.TryGetWebMessageAsString()
                if (-not $raw) { return }
                if ($raw -eq "nova-reload") {
                    if ($Script:WebUiVirtual) { $core.Navigate("https://nova.local/index.html") }
                    else { $core.NavigateToString($Script:HtmlPage) }
                    return
                }
                $msg = $raw | ConvertFrom-Json
                $resp = Invoke-NovaApi -Path $msg.path -BodyJson $msg.body
                $envelope = ConvertTo-NovaJson @{ id = $msg.id; body = [string]$resp }
                $core.PostWebMessageAsString($envelope)
            } catch {
                $errMsg = $_.Exception.Message
                $errId = $null
                try { if ($raw -and $raw -ne "nova-reload") { $errId = ($raw | ConvertFrom-Json).id } } catch {}
                try {
                    $payload = ConvertTo-NovaJson @{ success = $false; message = $errMsg }
                    $core.PostWebMessageAsString((ConvertTo-NovaJson @{ id = $errId; body = $payload }))
                } catch {}
            }
        })

        if ($Script:WebUiVirtual) {
            $sender.CoreWebView2.Navigate("https://nova.local/index.html")
        } else {
            $sender.CoreWebView2.NavigateToString($Script:HtmlPage)
        }
    })

    $form.Add_Shown({
        try { $wv.EnsureCoreWebView2Async() | Out-Null }
        catch {
            [System.Windows.Forms.MessageBox]::Show("WebView2 failed to load.`n`n$($_.Exception.Message)", "Nova Tweaks", [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Error) | Out-Null
        }
    })

    [System.Windows.Forms.Application]::Run($form)
}

# ---------- Entry ----------
if ($env:NOVA_STDIO_BRIDGE -eq '1') {
    Start-NovaStdioServer
} elseif ($IsWin) {
    try {
        Start-NovaWebView
    } catch {
        $msg = $_.Exception.Message
        try { Write-Log "Startup failed: $msg" "ERROR" } catch {}
        try {
            Add-Type -AssemblyName System.Windows.Forms
            [System.Windows.Forms.MessageBox]::Show(
                "Nova Tweaks could not start.`n`n$msg",
                "Nova Tweaks",
                [System.Windows.Forms.MessageBoxButtons]::OK,
                [System.Windows.Forms.MessageBoxIcon]::Error) | Out-Null
        } catch {}
    }
} else {
    Start-NovaWebServer
}
